276	// StartHeartbeat publishes greet immediately, then keeps re-greeting on the configured interval.
277	func (r *Router) StartHeartbeat(ctx context.Context, sessionID string, summary string) (*Heartbeat, error) {
278		if ctx == nil {
279			return nil, errors.New("network: heartbeat context is required")
280		}
281		if r == nil || r.peers == nil {
282			return nil, fmt.Errorf("%w: router peer registry is required", ErrInvalidField)
283		}
284	
285		interval := r.peers.GreetInterval()
286		if interval <= 0 {
287			return nil, fmt.Errorf("%w: greet interval must be positive", ErrInvalidField)
288		}
289		if _, err := r.PublishGreet(ctx, sessionID, summary); err != nil {
290			return nil, err
291		}
292	
293		heartbeat := &Heartbeat{
294			stop: make(chan struct{}),
295			done: make(chan struct{}),
296		}
297	
298		go func() {
299			defer close(heartbeat.done)
300	
301			ticker := time.NewTicker(interval)
302			defer ticker.Stop()
303	
304			for {
305				select {
306				case <-heartbeat.stop:
307					return
308				case <-ctx.Done():
309					return
310				case <-ticker.C:
311					if _, err := r.PublishGreet(
312						ctx,
313						sessionID,
314						summary,
315					); err != nil &&
316						errors.Is(err, ErrLocalPeerNotFound) {
317						return
318					}
319				}
320			}
321		}()
322	
323		return heartbeat, nil
324	}
