326	// PrepareSend validates one outbound request and computes the publish subject
327	// without performing transport side effects.
328	func (r *Router) PrepareSend(ctx context.Context, req SendRequest) (SendResult, error) {
329		if ctx == nil {
330			return SendResult{}, errors.New("network: send context is required")
331		}
332		if r == nil {
333			return SendResult{}, errors.New("network: router is required")
334		}
335		if err := ctx.Err(); err != nil {
336			return SendResult{}, err
337		}
338	
339		now := r.now().UTC()
340		envelope, err := r.buildEnvelope(req, now)
341		if err != nil {
342			return SendResult{}, err
343		}
344		if envelope.IsDirected() && !r.peers.HasPresence(envelope.WorkspaceID, envelope.Channel, *envelope.To, now) {
345			return SendResult{}, fmt.Errorf(
346				"%w: peer_id=%q channel=%q",
347				ErrTargetPeerNotFound,
348				*envelope.To,
349				envelope.Channel,
350			)
351		}
352		if err := r.validateSendLifecycle(envelope, now); err != nil {
353			return SendResult{}, err
354		}
355	
356		subject, err := subjectForEnvelope(envelope)
357		if err != nil {
358			return SendResult{}, err
359		}
360	
361		return SendResult{
362			ID:       envelope.ID,
363			Subject:  subject,
364			Envelope: envelope,
365		}, nil
366	}
