436	func (r *Router) handleReceiveParseError(
437		ctx context.Context,
438		payload []byte,
439		now time.Time,
440		parseErr error,
441	) (RouteResult, error) {
442		reason := reasonCodeForReceiveError(parseErr)
443		result := RouteResult{
444			Rejected:   true,
445			ReasonCode: &reason,
446		}
447		partial := parseEnvelopeSummary(payload)
448		if partial == nil {
449			return result, nil
450		}
451		result.Envelope = partial
452		if !shouldEmitWorkReceipt(*partial) {
453			return result, nil
454		}
455	
456		directedTarget, ok, err := r.resolveDirectedTarget(*partial)
457		if err != nil {
458			return RouteResult{}, err
459		}
460		if !ok {
461			return result, nil
462		}
463		status, emit := rejectionReceiptStatus(reason)
464		result, _, err = r.appendPublishedReceipt(ctx, result, directedTarget, *partial, now, status, emit)
465		return result, err
466	}
