468	func (r *Router) prepareReceiveState(
469		ctx context.Context,
470		envelope Envelope,
471		now time.Time,
472	) (receiveState, bool, error) {
473		state := receiveState{
474			result:   RouteResult{Envelope: &envelope},
475			envelope: envelope,
476			now:      now,
477		}
478		directedTarget, ok, err := r.resolveDirectedTarget(envelope)
479		if err != nil {
480			return receiveState{}, false, err
481		}
482		state.directedTarget = directedTarget
483		state.hasDirectedTarget = ok
484		if envelope.IsDirected() && !ok {
485			reason := ReasonCodeNotTarget
486			state.result.Rejected = true
487			state.result.ReasonCode = &reason
488			return state, true, nil
489		}
490		if !r.markSeen(envelope, now) {
491			return state, false, nil
492		}
493	
494		reason := ReasonCodeDuplicate
495		state.result.Duplicate = true
496		state.result.Rejected = true
497		state.result.ReasonCode = &reason
498		if !shouldEmitWorkReceipt(envelope) || !ok {
499			return state, true, nil
500		}
501	
502		result, _, err := r.appendPublishedReceipt(
503			ctx,
504			state.result,
505			directedTarget,
506			envelope,
507			now,
508			ReceiptStatusDuplicate,
509			true,
510		)
511		if err != nil {
512			return receiveState{}, false, err
513		}
514		state.result = result
515		return state, true, nil
516	}
