518	func (r *Router) dispatchReceivedEnvelope(ctx context.Context, state *receiveState) (RouteResult, error) {
519		switch state.envelope.Kind {
520		case KindGreet:
521			return r.handleReceivedGreet(state)
522		case KindWhois:
523			return r.handleWhois(
524				ctx,
525				state.envelope,
526				state.result,
527				state.directedTarget,
528				state.hasDirectedTarget,
529				state.now,
530			)
531		case KindSay:
532			return r.handleReceivedSay(ctx, state)
533		case KindCapability:
534			return r.handleReceivedCapability(ctx, state)
535		case KindReceipt, KindTrace:
536			return r.handleReceivedLifecycle(ctx, state)
537		default:
538			reason := ReasonCodeUnsupportedKind
539			state.result.Rejected = true
540			state.result.ReasonCode = &reason
541			return state.result, nil
542		}
543	}
