545	func (r *Router) handleReceivedGreet(state *receiveState) (RouteResult, error) {
546		body, err := decodeReceivedBody[GreetBody](state.envelope, "greet")
547		if err != nil {
548			return RouteResult{}, err
549		}
550		refresh, refreshErr := r.peers.RefreshRemoteDetailed(
551			state.envelope.WorkspaceID,
552			state.envelope.Channel,
553			body.PeerCard,
554			nil,
555			false,
556			state.now,
557		)
558		if refreshErr != nil {
559			return RouteResult{}, refreshErr
560		}
561		state.result.PeerEvents = append(
562			state.result.PeerEvents,
563			peerLifecycleEventsFromExpired(refresh.Expired, state.now, r.peers.GreetInterval())...,
564		)
565		if refresh.Joined {
566			state.result.PeerEvents = append(
567				state.result.PeerEvents,
568				PeerLifecycleEvent{
569					Kind:      PeerLifecycleJoined,
570					Peer:      peerInfoFromRemote(refresh.Entry, state.now, r.peers.GreetInterval()),
571					Timestamp: state.now,
572				},
573			)
574		}
575		return state.result, nil
576	}
