578	func peerLifecycleEventsFromExpired(
579		expired []RemotePeerEntry,
580		at time.Time,
581		greetInterval time.Duration,
582	) []PeerLifecycleEvent {
583		if len(expired) == 0 {
584			return nil
585		}
586		events := make([]PeerLifecycleEvent, 0, len(expired))
587		for _, entry := range expired {
588			peer := peerInfoFromRemote(entry, at, greetInterval)
589			peer.PresenceState = PresenceStateExpired
590			events = append(events, PeerLifecycleEvent{
591				Kind:      PeerLifecycleLeft,
592				Peer:      peer,
593				Timestamp: at,
594			})
595		}
596		return events
597	}
