661	func (r *Router) applyReceiveLifecycle(
662		ctx context.Context,
663		state *receiveState,
664		emitRejectionReceipt bool,
665	) (RouteResult, bool, error) {
666		result := state.result
667		if state.envelope.WorkID == nil {
668			return result, true, nil
669		}
670	
671		lifecycleResult, err := r.applyLifecycle(state.envelope, state.now)
672		switch {
673		case err == nil:
674			switch lifecycleResult.Action {
675			case LifecycleActionIgnored:
676				result.Ignored = true
677				return result, false, nil
678			case LifecycleActionRejectWork:
679				reason := ReasonCodeWorkClosed
680				if lifecycleResult.ReasonCode != nil {
681					reason = *lifecycleResult.ReasonCode
682				}
683				result.Rejected = true
684				result.ReasonCode = &reason
685				if !emitRejectionReceipt || !shouldEmitWorkReceipt(state.envelope) {
686					return result, false, nil
687				}
688				return r.appendPublishedReceipt(
689					ctx,
690					result,
691					state.directedTarget,
692					state.envelope,
693					state.now,
694					ReceiptStatusRejected,
695					true,
696				)
697			default:
698				return result, true, nil
699			}
700		case errors.Is(err, ErrWorkContainerMismatch):
701			reason := ReasonCodeWorkContainerMismatch
702			result.Rejected = true
703			result.ReasonCode = &reason
704			if !emitRejectionReceipt || !shouldEmitWorkReceipt(state.envelope) {
705				return result, false, nil
706			}
707			return r.appendPublishedReceipt(
708				ctx,
709				result,
710				state.directedTarget,
711				state.envelope,
712				state.now,
713				ReceiptStatusRejected,
714				true,
715			)
716		case errors.Is(err, ErrWorkActorNotAllowed),
717			errors.Is(err, ErrWorkNotFound):
718			result.Ignored = true
719			return result, false, nil
720		case errors.Is(err, ErrInvalidStateTransition):
721			reason := ReasonCodeInternal
722			result.Rejected = true
723			result.ReasonCode = &reason
724			return result, false, nil
725		default:
726			return RouteResult{}, false, err
727		}
728	}
