730	func (r *Router) appendPublishedReceipt(
731		ctx context.Context,
732		result RouteResult,
733		directedTarget LocalPeer,
734		envelope Envelope,
735		now time.Time,
736		status ReceiptStatus,
737		emit bool,
738	) (RouteResult, bool, error) {
739		if !emit {
740			return result, false, nil
741		}
742		receipt, built, err := buildWorkReceipt(directedTarget, envelope, now, status, *result.ReasonCode, nil)
743		if err != nil {
744			return RouteResult{}, false, err
745		}
746		if !built {
747			return result, false, nil
748		}
749	
750		result.Generated = append(result.Generated, receipt)
751		if err := r.publishGenerated(ctx, result.Generated); err != nil {
752			return RouteResult{}, false, err
753		}
754		return result, false, nil
755	}
