770	func (r *Router) handleWhois(
771		ctx context.Context,
772		envelope Envelope,
773		result RouteResult,
774		directedTarget LocalPeer,
775		hasDirectedTarget bool,
776		now time.Time,
777	) (RouteResult, error) {
778		body, err := envelope.DecodeBody()
779		if err != nil {
780			return RouteResult{}, err
781		}
782		whois, ok := body.(WhoisBody)
783		if !ok {
784			return RouteResult{}, fmt.Errorf("network: unexpected whois body type %T", body)
785		}
786	
787		switch whois.Type {
788		case WhoisTypeResponse:
789			if whois.PeerCard != nil {
790				capabilityCatalog, capabilityCatalogKnown := decodeWhoisCapabilityCatalogResponseExt(envelope.Ext)
791				if _, _, refreshErr := r.peers.RefreshRemoteWithCapabilityCatalog(
792					envelope.WorkspaceID,
793					envelope.Channel,
794					*whois.PeerCard,
795					capabilityCatalog,
796					capabilityCatalogKnown,
797					now,
798				); refreshErr != nil {
799					return RouteResult{}, refreshErr
800				}
801			}
802			if hasDirectedTarget {
803				if delivery, ok := deliveryFromLocalPeer(directedTarget, envelope); ok {
804					result.Deliveries = []Delivery{delivery}
805				}
806			}
807			return result, nil
808		case WhoisTypeRequest:
809			return r.handleWhoisRequest(ctx, envelope, result, whois, directedTarget, hasDirectedTarget, now)
810		default:
811			reason := ReasonCodeMalformed
812			result.Rejected = true
813			result.ReasonCode = &reason
814			return result, nil
815		}
816	}
