818	func (r *Router) handleWhoisRequest(
819		ctx context.Context,
820		envelope Envelope,
821		result RouteResult,
822		whois WhoisBody,
823		directedTarget LocalPeer,
824		hasDirectedTarget bool,
825		now time.Time,
826	) (RouteResult, error) {
827		discoveryRequest := parseWhoisCapabilityDiscoveryRequest(envelope.Ext)
828		if envelope.IsDirected() && hasDirectedTarget && isEnvelopeSender(directedTarget, envelope) {
829			result.Ignored = true
830			return result, nil
831		}
832		responders := r.whoisRequestResponders(envelope, whois, directedTarget, hasDirectedTarget)
833	
834		for _, responder := range responders {
835			reply, err := r.buildWhoisResponseEnvelope(envelope, responder, discoveryRequest, now)
836			if err != nil {
837				return RouteResult{}, err
838			}
839			result.Generated = append(result.Generated, reply)
840		}
841		if len(result.Generated) > 0 {
842			if err := r.publishGenerated(ctx, result.Generated); err != nil {
843				return RouteResult{}, err
844			}
845		}
846		return result, nil
847	}
