849	func (r *Router) whoisRequestResponders(
850		envelope Envelope,
851		whois WhoisBody,
852		directedTarget LocalPeer,
853		hasDirectedTarget bool,
854	) []LocalPeer {
855		if envelope.IsDirected() {
856			if hasDirectedTarget && !isEnvelopeSender(directedTarget, envelope) {
857				return []LocalPeer{directedTarget}
858			}
859			return nil
860		}
861		matches := r.peers.MatchLocalPeers(envelope.WorkspaceID, envelope.Channel, whois.Query)
862		responders := make([]LocalPeer, 0, len(matches))
863		for _, peer := range matches {
864			if isEnvelopeSender(peer, envelope) {
865				continue
866			}
867			responders = append(responders, peer)
868		}
869		return responders
870	}
