872	func (r *Router) buildWhoisResponseEnvelope(
873		request Envelope,
874		responder LocalPeer,
875		discoveryRequest whoisCapabilityDiscoveryRequest,
876		now time.Time,
877	) (Envelope, error) {
878		responseCard := clonePeerCard(responder.PeerCard)
879		if len(responder.CapabilityCatalog) != 0 {
880			responseCatalog := responder.CapabilityCatalog
881			if discoveryRequest.includeCapabilityCatalog {
882				responseCatalog = selectWhoisCapabilityCatalog(
883					responder.CapabilityCatalog,
884					discoveryRequest.capabilityIDs,
885				)
886			}
887			if err := applyCapabilityBriefProjection(&responseCard, responseCatalog); err != nil {
888				return Envelope{}, err
889			}
890		}
891	
892		payload, err := marshalEnvelopeBody(WhoisBody{
893			Type:     WhoisTypeResponse,
894			PeerCard: &responseCard,
895		})
896		if err != nil {
897			return Envelope{}, err
898		}
899		responseExt, err := buildWhoisCapabilityCatalogResponseExt(
900			discoveryRequest,
901			responder.CapabilityCatalog,
902		)
903		if err != nil {
904			return Envelope{}, err
905		}
906	
907		reply := Envelope{
908			Protocol:    ProtocolV0,
909			ID:          store.NewID("msg"),
910			WorkspaceID: request.WorkspaceID,
911			Kind:        KindWhois,
912			Channel:     request.Channel,
913			From:        responder.PeerID,
914			To:          ptrString(request.From),
915			ReplyTo:     ptrString(request.ID),
916			TS:          now.Unix(),
917			Body:        payload,
918			Proof:       nil,
919			Ext:         responseExt,
920		}
921		if err := ValidateEnvelope(reply, ValidateOptions{Now: now, MaxReplayAge: r.maxReplayAge}); err != nil {
922			return Envelope{}, err
923		}
924		if err := ensureEnvelopeSizeLimit(reply); err != nil {
925			return Envelope{}, err
926		}
927		return reply, nil
928	}
