930	func (r *Router) buildEnvelope(req SendRequest, now time.Time) (Envelope, error) {
931		if r.peers == nil {
932			return Envelope{}, fmt.Errorf("%w: peer registry is required", ErrInvalidField)
933		}
934	
935		sessionID := strings.TrimSpace(req.SessionID)
936		if sessionID == "" {
937			return Envelope{}, fmt.Errorf("%w: session is required", ErrMissingField)
938		}
939	
940		local, ok := r.peers.LocalBySession(sessionID)
941		if !ok {
942			return Envelope{}, fmt.Errorf("%w: session=%q", ErrLocalPeerNotFound, sessionID)
943		}
944	
945		channel := strings.TrimSpace(req.Channel)
946		if channel == "" {
947			return Envelope{}, fmt.Errorf("%w: channel is required", ErrMissingField)
948		}
949		if local.Channel != channel {
950			return Envelope{}, fmt.Errorf("%w: session=%q channel=%q", ErrLocalPeerNotFound, sessionID, channel)
951		}
952		if reqWorkspaceID := strings.TrimSpace(
953			req.WorkspaceID,
954		); reqWorkspaceID != "" &&
955			reqWorkspaceID != local.WorkspaceID {
956			return Envelope{}, fmt.Errorf(
957				"%w: session=%q workspace_id=%q",
958				ErrLocalPeerNotFound,
959				sessionID,
960				reqWorkspaceID,
961			)
962		}
963	
964		id := normalizeOptionalIdentifier(req.ID)
965		if id == nil {
966			id = ptrString(store.NewID("msg"))
967		}
968		envelope := Envelope{
969			Protocol:    ProtocolV0,
970			ID:          *id,
971			WorkspaceID: local.WorkspaceID,
972			Kind:        Kind(strings.TrimSpace(string(req.Kind))),
973			Channel:     channel,
974			Surface:     normalizeOptionalSurface(req.Surface),
975			ThreadID:    normalizeOptionalIdentifier(req.ThreadID),
976			DirectID:    normalizeOptionalIdentifier(req.DirectID),
977			From:        local.PeerID,
978			To:          normalizeOptionalIdentifier(req.To),
979			Mentions:    normalizeEnvelopeMentions(req.Mentions),
980			WorkID:      normalizeOptionalIdentifier(req.WorkID),
981			ReplyTo:     normalizeOptionalIdentifier(req.ReplyTo),
982			TraceID:     normalizeOptionalIdentifier(req.TraceID),
983			CausationID: normalizeOptionalIdentifier(req.CausationID),
984			TS:          now.Unix(),
985			ExpiresAt:   cloneInt64Ptr(req.ExpiresAt),
986			Body:        cloneRawMessage(req.Body),
987			Ext:         cloneExtensionMap(req.Ext),
988		}
989	
990		if isConversationKind(envelope.Kind) &&
991			envelope.Surface != nil &&
992			*envelope.Surface == SurfaceDirect &&
993			envelope.To != nil {
994			directID, _, _, err := DirectRoomIdentity(envelope.WorkspaceID, channel, envelope.From, *envelope.To)
995			if err != nil {
996				return Envelope{}, err
997			}
998			envelope.DirectID = ptrString(directID)
999		}
1000	
1001		if err := ValidateEnvelope(envelope, ValidateOptions{Now: now, MaxReplayAge: r.maxReplayAge}); err != nil {
1002			return Envelope{}, err
1003		}
1004		return envelope, nil
1005	}
