1022	func (r *Router) markSeen(envelope Envelope, now time.Time) bool {
1023		r.mu.Lock()
1024		defer r.mu.Unlock()
1025	
1026		for id, expiresAt := range r.seen {
1027			if !expiresAt.After(now) {
1028				delete(r.seen, id)
1029			}
1030		}
1031		if expiresAt, ok := r.seen[envelope.ID]; ok && expiresAt.After(now) {
1032			return true
1033		}
1034		r.seen[envelope.ID] = replayDeadline(envelope, now, r.maxReplayAge)
1035		return false
1036	}
