1173	func replayDeadline(envelope Envelope, now time.Time, maxReplayAge time.Duration) time.Time {
1174		deadline := time.Unix(envelope.TS, 0).Add(maxReplayAge).UTC()
1175		if envelope.ExpiresAt != nil {
1176			expiresAt := time.Unix(*envelope.ExpiresAt, 0).UTC()
1177			if expiresAt.Before(deadline) {
1178				deadline = expiresAt
1179			}
1180		}
1181		minDeadline := time.Unix(now.Unix()+1, 0).UTC()
1182		if deadline.Before(minDeadline) {
1183			return minDeadline
1184		}
1185		return deadline
1186	}
