1208	func (r *Router) deliveriesFromLocalPeers(ctx context.Context, envelope Envelope) ([]Delivery, error) {
1209		peers := r.peers.LocalPeers(envelope.WorkspaceID, envelope.Channel)
1210		if !envelopeRequiresThreadParticipantRouting(envelope) {
1211			return deliveriesFromLocalPeers(peers, envelope), nil
1212		}
1213		mentioned := mentionedPeerSet(envelope)
1214		if r.threadParticipants == nil {
1215			return deliveriesFromLocalPeers(r.selectActivatedThreadPeers(peers, envelope, nil, mentioned), envelope), nil
1216		}
1217		participants, err := r.threadParticipantSet(ctx, envelope)
1218		if err != nil {
1219			return nil, err
1220		}
1221		if len(participants) == 0 {
1222			return deliveriesFromLocalPeers(r.selectActivatedThreadPeers(peers, envelope, nil, mentioned), envelope), nil
1223		}
1224		filtered := make([]LocalPeer, 0, len(peers))
1225		for _, peer := range peers {
1226			peerID := strings.TrimSpace(peer.PeerID)
1227			if participants[peerID] || mentioned[peerID] {
1228				filtered = append(filtered, peer)
1229			}
1230		}
1231		return deliveriesFromLocalPeers(filtered, envelope), nil
1232	}
