1234	func (r *Router) selectActivatedThreadPeers(
1235		peers []LocalPeer,
1236		envelope Envelope,
1237		participants map[string]bool,
1238		mentioned map[string]bool,
1239	) []LocalPeer {
1240		if len(peers) == 0 {
1241			return nil
1242		}
1243		selected := make([]LocalPeer, 0, min(len(peers), r.activationTopK+len(mentioned)))
1244		seen := make(map[string]bool, len(peers))
1245		for _, peer := range peers {
1246			peerID := strings.TrimSpace(peer.PeerID)
1247			if peerID == "" || isEnvelopeSender(peer, envelope) {
1248				continue
1249			}
1250			if mentioned[peerID] || participants[peerID] {
1251				selected = append(selected, peer)
1252				seen[peerID] = true
1253			}
1254		}
1255		candidates := rankActivationCandidates(peers, envelope)
1256		limit := r.activationTopK
1257		for _, candidate := range candidates {
1258			if len(selected) >= limit+len(mentioned) {
1259				break
1260			}
1261			peerID := strings.TrimSpace(candidate.peer.PeerID)
1262			if seen[peerID] || isEnvelopeSender(candidate.peer, envelope) {
1263				continue
1264			}
1265			selected = append(selected, candidate.peer)
1266			seen[peerID] = true
1267		}
1268		sort.SliceStable(selected, func(i int, j int) bool {
1269			return selected[i].PeerID < selected[j].PeerID
1270		})
1271		return selected
1272	}
1273	
1274	type activationCandidate struct {
1275		peer  LocalPeer
1276		score int
1277	}
1278	
1279	func rankActivationCandidates(peers []LocalPeer, envelope Envelope) []activationCandidate {
1280		candidates := make([]activationCandidate, 0, len(peers))
1281		terms := activationTerms(envelope)
1282		for _, peer := range peers {
1283			candidates = append(candidates, activationCandidate{
1284				peer:  peer,
1285				score: activationScore(peer, terms),
1286			})
1287		}
1288		sort.SliceStable(candidates, func(i int, j int) bool {
1289			if candidates[i].score != candidates[j].score {
1290				return candidates[i].score > candidates[j].score
1291			}
1292			return candidates[i].peer.PeerID < candidates[j].peer.PeerID
1293		})
1294		return candidates
1295	}
1296	
1297	func activationTerms(envelope Envelope) []string {
1298		body, err := envelope.DecodeBody()
1299		if err != nil {
1300			return nil
1301		}
1302		var text string
1303		switch typed := body.(type) {
1304		case SayBody:
1305			text = typed.Text + " " + typed.Intent
1306		case CapabilityBody:
1307			text = typed.Capability.ID + " " + typed.Capability.Summary + " " + typed.Capability.Outcome
1308		default:
1309			return nil
1310		}
1311		fields := strings.FieldsFunc(strings.ToLower(text), func(r rune) bool {
1312			return (r < 'a' || r > 'z') && (r < '0' || r > '9')
1313		})
1314		terms := make([]string, 0, len(fields))
1315		seen := make(map[string]bool, len(fields))
1316		for _, field := range fields {
1317			if len(field) < 3 || seen[field] {
1318				continue
1319			}
1320			seen[field] = true
1321			terms = append(terms, field)
1322		}
1323		return terms
1324	}
1325	
1326	func activationScore(peer LocalPeer, terms []string) int {
1327		if len(terms) == 0 {
1328			return 0
1329		}
1330		var builder strings.Builder
1331		builder.WriteString(strings.Join(peer.PeerCard.Capabilities, " "))
1332		for _, capability := range peer.CapabilityCatalog {
1333			builder.WriteByte(' ')
1334			builder.WriteString(capability.ID)
1335			builder.WriteByte(' ')
1336			builder.WriteString(capability.Summary)
1337			builder.WriteByte(' ')
1338			builder.WriteString(capability.Outcome)
1339		}
1340		haystack := strings.ToLower(builder.String())
1341		score := 0
1342		for _, term := range terms {
1343			if strings.Contains(haystack, term) {
1344				score++
1345			}
1346		}
1347		return score
1348	}
