1	package store
2	
3	import (
4		"context"
5		"crypto/sha256"
6		"database/sql"
7		"encoding/hex"
8		"errors"
9		"fmt"
10		"sort"
11		"strings"
12		"time"
13	)
14	
15	const schemaMigrationsTable = "schema_migrations"
16	
17	type migrationConfig struct {
18		table string
19	}
20	
21	// MigrationOption customizes migration execution.
22	type MigrationOption func(*migrationConfig)
23	
24	// WithMigrationsTable stores migration records in a subsystem-specific table.
25	// Use this when independent migration streams share one SQLite database file.
26	func WithMigrationsTable(name string) MigrationOption {
27		return func(cfg *migrationConfig) {
28			if cfg == nil {
29				return
30			}
31			cfg.table = name
32		}
33	}
34	
35	// Migration describes one ordered SQLite schema change.
36	type Migration struct {
37		Version    int
38		Name       string
39		Statements []string
40		Up         func(ctx context.Context, tx *sql.Tx) error
41		// UpConn runs the migration on a dedicated connection OUTSIDE any wrapping
42		// transaction. It is the only way to perform a table rebuild that must toggle
43		// PRAGMA foreign_keys (a no-op inside a transaction), e.g. dropping a CHECK.
44		UpConn   func(ctx context.Context, conn *sql.Conn) error
45		Checksum string
46	}
47	
48	// MigrationRecord describes one applied schema migration row.
49	type MigrationRecord struct {
50		Version   int
51		Name      string
52		Checksum  string
53		AppliedAt time.Time
54	}
55	
56	// EnsureSchema executes each schema statement in order.
57	func EnsureSchema(ctx context.Context, db *sql.DB, statements []string) error {
58		for _, stmt := range statements {
59			if _, err := db.ExecContext(ctx, stmt); err != nil {
60				return err
61			}
62		}
63		return nil
64	}
65	
66	// RunMigrations applies pending migrations once in deterministic version order.
67	func RunMigrations(ctx context.Context, db *sql.DB, migrations []Migration, opts ...MigrationOption) error {
68		if ctx == nil {
69			return errors.New("store: migrate schema context is required")
70		}
71		if db == nil {
72			return errors.New("store: migrate schema database is required")
73		}
74		cfg, err := newMigrationConfig(opts...)
75		if err != nil {
76			return err
77		}
78		ordered, err := normalizeMigrations(migrations)
79		if err != nil {
80			return err
81		}
82		if err := ensureSchemaMigrationsTable(ctx, db, cfg.table); err != nil {
83			return err
84		}
85	
86		applied, err := appliedMigrationRecords(ctx, db, cfg.table)
87		if err != nil {
88			return err
89		}
90		expected, err := expectedMigrationRecords(ordered)
91		if err != nil {
92			return err
93		}
94		if err := validateAppliedMigrationRecords(applied, expected); err != nil {
95			return err
96		}
97		for _, migration := range ordered {
98			if _, ok := applied[migration.Version]; ok {
99				continue
100			}
101			if err := applyMigration(ctx, db, cfg.table, migration, expected[migration.Version].Checksum); err != nil {
102				return err
103			}
104		}
105		return nil
106	}
107	
108	// MigrationChecksum returns the checksum RunMigrations records for migration.
109	func MigrationChecksum(migration Migration) (string, error) {
110		return migrationChecksum(migration)
111	}
112	
113	// AppliedMigrations returns applied migration records ordered by version.
114	func AppliedMigrations(ctx context.Context, db *sql.DB) ([]MigrationRecord, error) {
115		return appliedMigrations(ctx, db, schemaMigrationsTable)
116	}
117	
118	// AppliedMigrationsWithTable returns applied migration records from a named migration table.
119	func AppliedMigrationsWithTable(ctx context.Context, db *sql.DB, table string) ([]MigrationRecord, error) {
120		return appliedMigrations(ctx, db, table)
121	}
122	
123	func newMigrationConfig(opts ...MigrationOption) (migrationConfig, error) {
124		cfg := migrationConfig{table: schemaMigrationsTable}
125		for _, opt := range opts {
126			if opt != nil {
127				opt(&cfg)
128			}
129		}
130		table, err := normalizeMigrationTableName(cfg.table)
131		if err != nil {
132			return migrationConfig{}, err
133		}
134		cfg.table = table
135		return cfg, nil
136	}
137	
138	func normalizeMigrationTableName(name string) (string, error) {
139		trimmed := strings.TrimSpace(name)
140		if trimmed == "" {
141			return "", errors.New("store: migration table name is required")
142		}
143		for idx, r := range trimmed {
144			valid := r == '_' ||
145				(r >= 'a' && r <= 'z') ||
146				(r >= 'A' && r <= 'Z') ||
147				(idx > 0 && r >= '0' && r <= '9')
148			if !valid {
149				return "", fmt.Errorf("store: invalid migration table name %q", trimmed)
150			}
151		}
152		return trimmed, nil
153	}
154	
155	func quoteIdentifier(name string) string {
156		return `"` + name + `"`
157	}
158	
159	func normalizeMigrations(migrations []Migration) ([]Migration, error) {
160		ordered := append([]Migration(nil), migrations...)
161		sort.SliceStable(ordered, func(i, j int) bool {
162			if ordered[i].Version == ordered[j].Version {
163				return strings.TrimSpace(ordered[i].Name) < strings.TrimSpace(ordered[j].Name)
164			}
165			return ordered[i].Version < ordered[j].Version
166		})
167	
168		versions := make(map[int]string, len(ordered))
169		names := make(map[string]int, len(ordered))
170		for _, migration := range ordered {
171			name := strings.TrimSpace(migration.Name)
172			if migration.Version <= 0 {
173				return nil, fmt.Errorf("store: migration %q has invalid version %d", name, migration.Version)
174			}
175			if name == "" {
176				return nil, fmt.Errorf("store: migration %d name is required", migration.Version)
177			}
178			if previous, ok := versions[migration.Version]; ok {
179				return nil, fmt.Errorf(
180					"store: duplicate migration version %d for %q and %q",
181					migration.Version,
182					previous,
183					name,
184				)
185			}
186			if previous, ok := names[name]; ok {
187				return nil, fmt.Errorf(
188					"store: duplicate migration name %q for versions %d and %d",
189					name,
190					previous,
191					migration.Version,
192				)
193			}
194			ops := 0
195			if migration.Up != nil {
196				ops++
197			}
198			if migration.UpConn != nil {
199				ops++
200			}
201			if len(migration.Statements) > 0 {
202				ops++
203			}
204			if ops == 0 {
205				return nil, fmt.Errorf("store: migration %d %q has no operation", migration.Version, name)
206			}
207			if ops > 1 {
208				return nil, fmt.Errorf(
209					"store: migration %d %q must set exactly one of Up, UpConn, or Statements",
210					migration.Version,
211					name,
212				)
213			}
214			versions[migration.Version] = name
215			names[name] = migration.Version
216		}
217		return ordered, nil
218	}
