349	// applyConnMigration runs a UpConn migration on a dedicated connection (outside any
350	// wrapping transaction so the migration can toggle PRAGMA foreign_keys), then records it.
351	// The migration body owns its own inner transaction and foreign-key restoration.
352	func applyConnMigration(
353		ctx context.Context,
354		db *sql.DB,
355		table string,
356		migration Migration,
357		checksum string,
358	) (err error) {
359		name := strings.TrimSpace(migration.Name)
360		conn, err := db.Conn(ctx)
361		if err != nil {
362			return fmt.Errorf("store: open connection for migration %d %q: %w", migration.Version, name, err)
363		}
364		defer func() {
365			if closeErr := conn.Close(); closeErr != nil {
366				closeErr = fmt.Errorf(
367					"store: close connection for migration %d %q: %w",
368					migration.Version,
369					name,
370					closeErr,
371				)
372				if err == nil {
373					err = closeErr
374					return
375				}
376				err = errors.Join(err, closeErr)
377			}
378		}()
379		if err := migration.UpConn(ctx, conn); err != nil {
380			return fmt.Errorf("store: apply migration %d %q: %w", migration.Version, name, err)
381		}
382		if _, err := conn.ExecContext(
383			ctx,
384			fmt.Sprintf(`INSERT INTO %s (version, name, checksum, applied_at) VALUES (?, ?, ?, ?)`, quoteIdentifier(table)),
385			migration.Version,
386			name,
387			checksum,
388			FormatTimestamp(time.Now().UTC()),
389		); err != nil {
390			return fmt.Errorf("store: record migration %d %q: %w", migration.Version, name, err)
391		}
392		return nil
393	}
