395	func migrationChecksum(migration Migration) (string, error) {
396		if checksum := strings.TrimSpace(migration.Checksum); checksum != "" {
397			return checksum, nil
398		}
399		name := strings.TrimSpace(migration.Name)
400		if len(migration.Statements) == 0 {
401			return "", fmt.Errorf(
402				"store: migration %d %q checksum is required for custom operation",
403				migration.Version,
404				name,
405			)
406		}
407	
408		hash := sha256.New()
409		if _, err := fmt.Fprintf(hash, "%d\n%s\n", migration.Version, name); err != nil {
410			return "", fmt.Errorf(
411				"store: hash migration %d %q header: %w",
412				migration.Version,
413				name,
414				err,
415			)
416		}
417		for _, statement := range migration.Statements {
418			if _, err := hash.Write([]byte(strings.TrimSpace(statement))); err != nil {
419				return "", fmt.Errorf(
420					"store: hash migration %d %q statement: %w",
421					migration.Version,
422					name,
423					err,
424				)
425			}
426			if _, err := hash.Write([]byte{'\n'}); err != nil {
427				return "", fmt.Errorf(
428					"store: hash migration %d %q separator: %w",
429					migration.Version,
430					name,
431					err,
432				)
433			}
434		}
435		return hex.EncodeToString(hash.Sum(nil)), nil
436	}
