350	func (c *deliveryCoordinator) waitInbox(
351		ctx context.Context,
352		sessionID string,
353		channel string,
354	) ([]Envelope, error) {
355		if ctx == nil {
356			return nil, errors.New("network: wait inbox context is required")
357		}
358		if c == nil {
359			return nil, errors.New("network: delivery coordinator is required")
360		}
361	
362		target := strings.TrimSpace(sessionID)
363		if target == "" {
364			return nil, fmt.Errorf("%w: delivery session id is required", ErrMissingField)
365		}
366		channel = strings.TrimSpace(channel)
367	
368		for {
369			if err := ctx.Err(); err != nil {
370				return nil, err
371			}
372			if err := c.lifecycleCtx.Err(); err != nil {
373				return nil, err
374			}
375			if messages := filterInboxByChannel(c.inbox(target), channel); len(messages) > 0 {
376				return messages, nil
377			}
378	
379			waiter := c.registerWaiter(target)
380			if messages := filterInboxByChannel(c.inbox(target), channel); len(messages) > 0 {
381				c.unregisterWaiter(target, waiter)
382				return messages, nil
383			}
384	
385			select {
386			case <-ctx.Done():
387				c.unregisterWaiter(target, waiter)
388				return nil, ctx.Err()
389			case <-c.lifecycleCtx.Done():
390				c.unregisterWaiter(target, waiter)
391				return nil, c.lifecycleCtx.Err()
392			case <-waiter:
393			}
394		}
395	}
