505	func (c *deliveryCoordinator) guidanceModeForDelivery(
506		sessionID string,
507		envelope Envelope,
508	) networkMessageGuidanceMode {
509		target := strings.TrimSpace(sessionID)
510		if target == "" {
511			return networkMessageGuidanceVerbose
512		}
513	
514		c.mu.Lock()
515		defer c.mu.Unlock()
516	
517		state := c.guidance[target]
518		if !state.replyDelivered && !state.protocolDelivered && c.guidanceStore != nil {
519			if stored, err := c.guidanceStore.GetNetworkDeliveryGuidanceState(c.lifecycleCtx, target); err == nil {
520				state = deliveryGuidanceState{
521					replyDelivered:    stored.ReplyGuidanceDelivered,
522					protocolDelivered: stored.ProtocolGuidanceDelivered,
523				}
524				c.guidance[target] = state
525			}
526		}
527		if !state.replyDelivered {
528			return networkMessageGuidanceVerbose
529		}
530		if lifecycleWorkID(envelope) != "" && !state.protocolDelivered {
531			return networkMessageGuidanceVerbose
532		}
533		return networkMessageGuidanceCompact
534	}
