580			return
581		}
582		if c.queueDepth(sessionID) == 0 {
583			return
584		}
585	
586		state := &deliveryState{done: make(chan struct{})}
587		if _, loaded := c.deliveries.LoadOrStore(sessionID, state); loaded {
