595	func (c *deliveryCoordinator) runWorker(sessionID string, state *deliveryState) {
596		defer c.wg.Done()
597		defer close(state.done)
598		defer c.deliveries.Delete(sessionID)
599	
600		target := strings.TrimSpace(sessionID)
601		for {
602			if err := c.lifecycleCtx.Err(); err != nil {
603				return
604			}
605			if c.prompter.IsPrompting(target) {
606				return
607			}
608	
609			item, ok := c.dequeue(target)
610			if !ok {
611				return
612			}
613			if !c.processQueuedItem(target, item, state) {
614				return
615			}
616		}
617	}
