619	func (c *deliveryCoordinator) processQueuedItem(sessionID string, item queuedEnvelope, state *deliveryState) bool {
620		c.markInFlight(sessionID, item)
621		envelope := item.Envelope
622	
623		message, err := formatNetworkMessageWithDeliveryMode(
624			envelope,
625			c.guidanceModeForDelivery(sessionID, envelope),
626			item.PromptMode,
627		)
628		if err != nil {
629			c.handleRenderFailure(sessionID, item, state, err)
630			return false
631		}
632	
633		cost := deliveredPromptCostForMessage(message)
634		events, err := c.prompter.PromptNetwork(
635			c.lifecycleCtx,
636			sessionID,
637			message,
638			promptNetworkMeta(envelope, cost, item.PromptMode),
639		)
640		if err != nil {
641			c.handleDeliveryFailure(sessionID, item, state, err)
642			return false
643		}
644		if !c.drainPromptEvents(events) {
645			c.handleInterruptedDelivery(sessionID, item)
646			return false
647		}
648	
649		c.finishDeliveredMessage(sessionID, item, cost)
650		return true
651	}
652	
653	func deliveredPromptCostForMessage(message string) deliveredPromptCost {
654		sizeBytes := int64(len(message))
655		return deliveredPromptCost{
656			PromptSizeBytes:       sizeBytes,
657			EstimatedPromptTokens: estimatePromptTokens(sizeBytes),
658		}
659	}
660	
661	func estimatePromptTokens(sizeBytes int64) int64 {
662		if sizeBytes <= 0 {
663			return 0
664		}
665		return (sizeBytes + 3) / 4
666	}
