668	func promptNetworkMeta(envelope Envelope, cost deliveredPromptCost, deliveryMode ...string) acp.PromptNetworkMeta {
669		meta := acp.PromptNetworkMeta{
670			MessageID:             envelope.ID,
671			Kind:                  string(envelope.Kind),
672			Channel:               envelope.Channel,
673			From:                  envelope.From,
674			Mentions:              normalizeEnvelopeMentions(envelope.Mentions),
675			Trust:                 networkMessageTrustUntrusted,
676			DeliveryMode:          normalizePromptDeliveryMode(firstPromptDeliveryMode(deliveryMode)),
677			PromptSizeBytes:       cost.PromptSizeBytes,
678			EstimatedPromptTokens: cost.EstimatedPromptTokens,
679		}
680		if envelope.To != nil {
681			meta.To = strings.TrimSpace(*envelope.To)
682		}
683		if envelope.Surface != nil {
684			meta.Surface = strings.TrimSpace(string(*envelope.Surface))
685		}
686		if envelope.ThreadID != nil {
687			meta.ThreadID = strings.TrimSpace(*envelope.ThreadID)
688		}
689		if envelope.DirectID != nil {
690			meta.DirectID = strings.TrimSpace(*envelope.DirectID)
691		}
692		if workID := lifecycleWorkID(envelope); workID != "" {
693			meta.WorkID = workID
694		}
695		if envelope.ReplyTo != nil {
696			meta.ReplyTo = strings.TrimSpace(*envelope.ReplyTo)
697		}
698		if envelope.TraceID != nil {
699			meta.TraceID = strings.TrimSpace(*envelope.TraceID)
700		}
701		if envelope.CausationID != nil {
702			meta.CausationID = strings.TrimSpace(*envelope.CausationID)
703		}
704		return meta.Normalize()
705	}
