707	func (c *deliveryCoordinator) handleRenderFailure(
708		sessionID string,
709		item queuedEnvelope,
710		state *deliveryState,
711		err error,
712	) {
713		c.clearInFlight(sessionID)
714		item = item.withNextRetryAttempt()
715		requeued := c.requeueFront(sessionID, item)
716		c.logger.Warn(
717			"network.message.render_failed",
718			"session_id", sessionID,
719			"envelope_id", item.Envelope.ID,
720			"error", err,
721			"retry_attempt", item.RetryAttempt,
722		)
723		if requeued && json.Valid(item.Envelope.Body) {
724			c.retryAfterWorkerExit(sessionID, item, state)
725		}
726	}
