826	func (c *deliveryCoordinator) retryAfterWorkerExit(sessionID string, item queuedEnvelope, state *deliveryState) {
827		if c == nil || state == nil {
828			return
829		}
830	
831		target := strings.TrimSpace(sessionID)
832		if target == "" {
833			return
834		}
835	
836		delay := c.retryDelayFor(item.RetryAttempt)
837		c.wg.Go(func() {
838			select {
839			case <-state.done:
840			case <-c.lifecycleCtx.Done():
841				return
842			}
843	
844			c.scheduleRetry(c.lifecycleCtx, delay, func() {
845				if err := c.lifecycleCtx.Err(); err != nil {
846					return
847				}
848				if c.prompter.IsPrompting(target) {
849					return
850				}
851				if c.queueDepth(target) == 0 {
852					return
853				}
854				c.trigger(target)
855			})
856		})
857	}
858	
859	func (c *deliveryCoordinator) retryDelayFor(attempt int) time.Duration {
860		if c == nil {
861			return defaultDeliveryRetryBaseDelay
862		}
863		delay := c.retryBaseDelay
864		for i := 1; i < attempt; i++ {
865			if delay >= c.retryMaxDelay/2 {
866				return c.retryMaxDelay
867			}
868			delay *= 2
869		}
870		if delay > c.retryMaxDelay {
871			return c.retryMaxDelay
872		}
873		return delay
874	}
875	
876	func scheduleDeliveryRetry(ctx context.Context, delay time.Duration, fn func()) {
877		if fn == nil {
878			return
879		}
880		if delay <= 0 {
881			select {
882			case <-ctx.Done():
883				return
884			default:
885				fn()
886				return
887			}
888		}
889	
890		timer := time.NewTimer(delay)
891		defer timer.Stop()
892	
893		select {
894		case <-ctx.Done():
895			return
896		case <-timer.C:
897			fn()
898		}
899	}
