901	func (c *deliveryCoordinator) stats() deliveryCoordinatorStats {
902		if c == nil {
903			return deliveryCoordinatorStats{}
904		}
905	
906		c.mu.Lock()
907		queues := make([]*inboundQueue, 0, len(c.queues))
908		for _, queue := range c.queues {
909			queues = append(queues, queue)
910		}
911		inFlightMessages := len(c.inFlight)
912		c.mu.Unlock()
913	
914		stats := deliveryCoordinatorStats{
915			InFlightMessages: inFlightMessages,
916		}
917		for _, queue := range queues {
918			depth := queue.len()
919			if depth <= 0 {
920				continue
921			}
922			stats.QueuedMessages += depth
923			stats.QueuedSessions++
924		}
925		c.deliveries.Range(func(_, _ any) bool {
926			stats.DeliveryWorkers++
927			return true
928		})
929		return stats
930	}
