990	func (q *inboundQueue) enqueue(
991		peerID string,
992		envelope Envelope,
993		promptMode string,
994		acceptedAt time.Time,
995		prompting bool,
996	) enqueueResult {
997		q.mu.Lock()
998		defer q.mu.Unlock()
999	
1000		var dropped *Envelope
1001		wasEmpty := len(q.items) == 0
1002		if len(q.items) >= q.maxDepth {
1003			evicted := cloneEnvelope(q.items[0].Envelope)
1004			dropped = &evicted
1005			copy(q.items[0:], q.items[1:])
1006			q.items = q.items[:len(q.items)-1]
1007		}
1008		deliveryMode := "queued"
1009		if !prompting && wasEmpty {
1010			deliveryMode = "immediate"
1011		}
1012		q.items = append(q.items, queuedEnvelope{
1013			Envelope:     cloneEnvelope(envelope),
1014			PeerID:       strings.TrimSpace(peerID),
1015			AcceptedAt:   acceptedAt.UTC(),
1016			DeliveryMode: deliveryMode,
1017			PromptMode:   strings.TrimSpace(promptMode),
1018			SessionToken: q.token,
1019		})
1020	
1021		return enqueueResult{
1022			Depth:        len(q.items),
1023			DeliveryMode: deliveryMode,
1024			Dropped:      dropped,
1025		}
1026	}
