1035	func (q *inboundQueue) dequeue() (queuedEnvelope, bool) {
1036		q.mu.Lock()
1037		defer q.mu.Unlock()
1038	
1039		if len(q.items) == 0 {
1040			return queuedEnvelope{}, false
1041		}
1042	
1043		envelope := cloneQueuedEnvelope(q.items[0])
1044		copy(q.items[0:], q.items[1:])
1045		q.items = q.items[:len(q.items)-1]
1046		return envelope, true
1047	}
