1055	func (q *inboundQueue) snapshot() []Envelope {
1056		q.mu.Lock()
1057		defer q.mu.Unlock()
1058	
1059		if len(q.items) == 0 {
1060			return nil
1061		}
1062	
1063		out := make([]Envelope, 0, len(q.items))
1064		for _, envelope := range q.items {
1065			out = append(out, cloneEnvelope(envelope.Envelope))
1066		}
1067		return out
