1087	type networkDeliveryBody struct {
1088		preview       string
1089		plainTextBody string
1090		canonicalBody []byte
1091	}
1092	
1093	func networkDeliveryBodyForEnvelope(envelope Envelope) (networkDeliveryBody, error) {
1094		body, err := envelope.DecodeBody()
1095		switch {
1096		case err == nil:
1097			if say, ok := body.(SayBody); ok && len(say.Artifacts) == 0 {
1098				return networkDeliveryBody{
1099					preview:       strings.TrimSpace(say.Text),
1100					plainTextBody: say.Text,
1101				}, nil
1102			}
1103			canonicalBody, marshalErr := json.Marshal(body)
1104			if marshalErr != nil {
1105				return networkDeliveryBody{}, fmt.Errorf("network: marshal canonical body for delivery: %w", marshalErr)
1106			}
1107			return networkDeliveryBody{
1108				preview:       previewForBody(body),
1109				canonicalBody: canonicalBody,
1110			}, nil
1111		case !json.Valid(envelope.Body):
1112			return networkDeliveryBody{}, fmt.Errorf("network: decode envelope body for delivery: %w", err)
1113		default:
1114			var compact bytes.Buffer
1115			if compactErr := json.Compact(&compact, envelope.Body); compactErr != nil {
1116				return networkDeliveryBody{}, fmt.Errorf("network: compact raw envelope body for delivery: %w", compactErr)
1117			}
1118			return networkDeliveryBody{canonicalBody: compact.Bytes()}, nil
1119		}
1120	}
1121	
1122	func formatNetworkMessageWithDeliveryMode(
1123		envelope Envelope,
1124		guidanceMode networkMessageGuidanceMode,
1125		deliveryMode string,
1126	) (string, error) {
1127		if normalizePromptDeliveryMode(deliveryMode) == store.NetworkSubscriptionModeDigest {
1128			return formatNetworkDigestMessage(envelope, guidanceMode)
1129		}
1130	
1131		deliveryBody, err := networkDeliveryBodyForEnvelope(envelope)
1132		if err != nil {
1133			return "", err
1134		}
1135		encodedBody := ""
1136		if deliveryBody.plainTextBody == "" {
1137			encodedBody = base64.StdEncoding.EncodeToString(deliveryBody.canonicalBody)
1138		}
1139	
1140		var builder strings.Builder
1141		builder.Grow(
1142			base64.StdEncoding.EncodedLen(len(deliveryBody.canonicalBody)) +
1143				len(deliveryBody.preview)*6 +
1144				len(deliveryBody.plainTextBody)*2 +
1145				2048,
1146		)
1147		builder.WriteString("<network-message")
1148		writeNetworkMessageAttrs(&builder, envelope, "")
1149		builder.WriteString(">\n")
1150		if deliveryBody.preview != "" {
1151			builder.WriteString("  <network-preview encoding=\"xml-escaped\">")
1152			builder.WriteString(xmlEscape(deliveryBody.preview))
1153			builder.WriteString("</network-preview>\n")
1154		}
1155		if deliveryBody.plainTextBody != "" {
1156			builder.WriteString("  <network-body encoding=\"text\">")
1157			builder.WriteString(xmlEscape(deliveryBody.plainTextBody))
1158			builder.WriteString("</network-body>\n")
1159		} else {
1160			builder.WriteString("  <network-body encoding=\"base64-json\">")
1161			builder.WriteString(encodedBody)
1162			builder.WriteString("</network-body>\n")
1163		}
1164		builder.WriteString("</network-message>")
1165		writeReplyGuidance(&builder, envelope, guidanceMode)
1166	
1167		return builder.String(), nil
1168	}
1169	
1170	func formatNetworkDigestMessage(
1171		envelope Envelope,
1172		guidanceMode networkMessageGuidanceMode,
1173	) (string, error) {
1174		body, err := envelope.DecodeBody()
1175		preview := ""
1176		switch {
1177		case err == nil:
1178			preview = previewForBody(body)
1179		case !json.Valid(envelope.Body):
1180			return "", fmt.Errorf("network: decode envelope body for digest delivery: %w", err)
1181		default:
1182			var compact bytes.Buffer
1183			if compactErr := json.Compact(&compact, envelope.Body); compactErr != nil {
1184				return "", fmt.Errorf("network: compact raw envelope body for digest delivery: %w", compactErr)
1185			}
1186			preview = compact.String()
1187		}
1188		preview = strings.TrimSpace(preview)
1189		if preview == "" {
1190			preview = string(envelope.Kind)
1191		}
1192	
1193		var builder strings.Builder
1194		builder.Grow(len(preview)*6 + 1024)
1195		builder.WriteString("<network-message")
1196		writeNetworkMessageAttrs(&builder, envelope, store.NetworkSubscriptionModeDigest)
1197		builder.WriteString(">\n")
1198		builder.WriteString("  <network-digest encoding=\"xml-escaped\">")
1199		builder.WriteString(xmlEscape(preview))
1200		builder.WriteString("</network-digest>\n")
1201		builder.WriteString("</network-message>")
1202		writeReplyGuidance(&builder, envelope, guidanceMode)
1203		return builder.String(), nil
1204	}
