1206	func writeNetworkMessageAttrs(builder *strings.Builder, envelope Envelope, deliveryMode string) {
1207		writeXMLAttr(builder, "id", envelope.ID)
1208		writeXMLAttr(builder, "from", envelope.From)
1209		writeXMLAttr(builder, "channel", envelope.Channel)
1210		writeXMLAttr(builder, "kind", string(envelope.Kind))
1211		if deliveryMode != "" {
1212			writeXMLAttr(builder, "delivery-mode", deliveryMode)
1213		}
1214		if envelope.Surface != nil {
1215			writeXMLAttr(builder, "surface", string(*envelope.Surface))
1216		}
1217		if envelope.ThreadID != nil {
1218			writeXMLAttr(builder, "thread-id", *envelope.ThreadID)
1219		}
1220		if envelope.DirectID != nil {
1221			writeXMLAttr(builder, "direct-id", *envelope.DirectID)
1222		}
1223		if envelope.To != nil {
1224			writeXMLAttr(builder, "to", *envelope.To)
1225		}
1226		if len(envelope.Mentions) > 0 {
1227			writeXMLAttr(builder, "mentions", strings.Join(normalizeEnvelopeMentions(envelope.Mentions), ","))
1228		}
1229		if envelope.WorkID != nil {
1230			if workID := lifecycleWorkID(envelope); workID != "" {
1231				writeXMLAttr(builder, "work-id", workID)
1232			}
1233		}
1234		if envelope.ReplyTo != nil {
1235			writeXMLAttr(builder, "reply-to", *envelope.ReplyTo)
1236		}
1237		if envelope.TraceID != nil {
1238			writeXMLAttr(builder, "trace-id", *envelope.TraceID)
1239		}
1240		if envelope.CausationID != nil {
1241			writeXMLAttr(builder, "causation-id", *envelope.CausationID)
1242		}
1243		if envelope.ExpiresAt != nil {
1244			writeXMLAttr(builder, "expires-at", strconv.FormatInt(*envelope.ExpiresAt, 10))
