1269	func writeReplyGuidance(
1270		builder *strings.Builder,
1271		envelope Envelope,
1272		guidanceMode networkMessageGuidanceMode,
1273	) {
1274		if builder == nil {
1275			return
1276		}
1277	
1278		ctx := newReplyGuidanceContext(envelope)
1279		builder.WriteString("\n\n")
1280		writeGuidanceLine(
1281			builder,
1282			"Prefer `agh__network_send` when available; otherwise use `agh network send` to respond.",
1283		)
1284		writeGuidanceLine(builder, responseRegisterGuidanceLine(envelope))
1285		writeGuidanceLine(builder, ctx.replyFlagsLine())
1286		writeGuidanceLine(builder, ctx.causationLine())
1287	
1288		if traceLine := ctx.traceLine(); traceLine != "" {
1289			writeGuidanceLine(builder, traceLine)
1290		}
1291		if workLine := ctx.workLine(); workLine != "" {
1292			writeGuidanceLine(builder, workLine)
1293		}
1294		for _, line := range protocolGuidanceText {
1295			writeGuidanceLine(builder, line)
1296		}
1297		if guidanceMode == networkMessageGuidanceCompact {
1298			writeCompactReplyGuidance(builder)
1299			return
1300		}
1301	
1302		writeGuidanceLine(builder, "Examples:")
1303		writeGuidanceLine(builder, "```bash")
1304		ctx.writeReplyExample(builder)
1305		if ctx.reuseWork {
1306			ctx.writeProtocolReceiptExample(builder)
1307			ctx.writeProtocolTraceExample(builder)
1308			ctx.writeProtocolCapabilityExample(builder)
1309		}
1310		writeGuidanceLine(builder, "```")
1311		builder.WriteString("See `agh network --help` for options.")
1312	}
