1546	func previewForBody(body Body) string {
1547		switch value := body.(type) {
1548		case GreetBody:
1549			return ResolveGreetSummary(value.PeerCard, value.Summary)
1550		case WhoisBody:
1551			if value.Type == WhoisTypeRequest {
1552				return strings.TrimSpace(value.Query)
1553			}
1554			return ""
1555		case SayBody:
1556			return strings.TrimSpace(value.Text)
1557		case CapabilityBody:
1558			if summary := strings.TrimSpace(value.Capability.Summary); summary != "" {
1559				return summary
1560			}
1561			if outcome := strings.TrimSpace(value.Capability.Outcome); outcome != "" {
1562				return outcome
1563			}
1564			return strings.TrimSpace(value.Capability.ID)
1565		case ReceiptBody:
1566			if value.Detail != nil {
1567				return strings.TrimSpace(*value.Detail)
1568			}
1569			return ""
1570		case TraceBody:
1571			return strings.TrimSpace(value.Message)
1572		default:
1573			return ""
1574		}
1575	}
