598	func (m *Manager) LeaveChannel(ctx context.Context, sessionID string) error {
599		if ctx == nil {
600			return errors.New("network: leave context is required")
601		}
602		if m == nil {
603			return errors.New("network: manager is required")
604		}
605		if err := ctx.Err(); err != nil {
606			return err
607		}
608	
609		targetSession := strings.TrimSpace(sessionID)
610		if targetSession == "" {
611			return fmt.Errorf("%w: session id is required", ErrMissingField)
612		}
613	
614		runtime, ok := m.removeSessionRuntime(targetSession)
615		if !ok {
616			m.deliveries.dropSession(targetSession)
617			m.dispatchLocalPeerLeft(ctx, targetSession)
618			return nil
619		}
620	
621		var errs []error
622		m.deliveries.dropSession(targetSession)
623	
624		if runtime.heartbeat != nil {
625			runtime.heartbeat.Stop()
626		}
627		if runtime.directSub != nil {
628			if err := runtime.directSub.Unsubscribe(); err != nil && !errors.Is(err, nats.ErrConnectionClosed) {
629				errs = append(errs, fmt.Errorf("network: unsubscribe direct subject for %q: %w", targetSession, err))
630			}
631		}
632		if err := m.releaseBroadcastSubscription(runtime.workspaceID, runtime.channel); err != nil {
633			errs = append(errs, err)
634		}
635		m.dispatchLocalPeerLeft(ctx, targetSession)
636	
637		m.logger.Info(
638			"network.peer.left",
639			"session_id", runtime.sessionID,
640			"peer_id", runtime.peerID,
641			"workspace_id", runtime.workspaceID,
642			managerChannelKey, runtime.channel,
643		)
644		return errors.Join(errs...)
645	}
