746	func (m *Manager) prepareRuntimeSend(req RuntimeSendRequest) (SendResult, error) {
747		if m == nil || m.router == nil {
748			return SendResult{}, errors.New("network: manager router is required")
749		}
750		now := m.now().UTC()
751		workspaceID := strings.TrimSpace(req.WorkspaceID)
752		if err := ValidateWorkspaceID(workspaceID); err != nil {
753			return SendResult{}, err
754		}
755		channel := strings.TrimSpace(req.Channel)
756		if err := ValidateChannel(channel); err != nil {
757			return SendResult{}, err
758		}
759		id := normalizeOptionalIdentifier(req.ID)
760		if id == nil {
761			id = ptrString(store.NewID("msg"))
762		}
763		envelope := Envelope{
764			Protocol:    ProtocolV0,
765			ID:          *id,
766			WorkspaceID: workspaceID,
767			Kind:        Kind(strings.TrimSpace(string(req.Kind))),
768			Channel:     channel,
769			Surface:     normalizeOptionalSurface(req.Surface),
770			ThreadID:    normalizeOptionalIdentifier(req.ThreadID),
771			DirectID:    normalizeOptionalIdentifier(req.DirectID),
772			From:        RuntimePeerID,
773			To:          normalizeOptionalIdentifier(req.To),
774			Mentions:    normalizeEnvelopeMentions(req.Mentions),
775			WorkID:      normalizeOptionalIdentifier(req.WorkID),
776			ReplyTo:     normalizeOptionalIdentifier(req.ReplyTo),
777			TraceID:     normalizeOptionalIdentifier(req.TraceID),
778			CausationID: normalizeOptionalIdentifier(req.CausationID),
779			TS:          now.Unix(),
780			ExpiresAt:   cloneInt64Ptr(req.ExpiresAt),
781			Body:        cloneRawMessage(req.Body),
782			Ext:         cloneExtensionMap(req.Ext),
783		}
784		if isConversationKind(envelope.Kind) &&
785			envelope.Surface != nil &&
786			*envelope.Surface == SurfaceDirect &&
787			envelope.To != nil {
788			directID, _, _, err := DirectRoomIdentity(envelope.WorkspaceID, channel, envelope.From, *envelope.To)
789			if err != nil {
790				return SendResult{}, err
791			}
792			envelope.DirectID = ptrString(directID)
793		}
794		if envelope.IsDirected() && !m.peers.HasPresence(envelope.WorkspaceID, envelope.Channel, *envelope.To, now) {
795			return SendResult{}, fmt.Errorf(
796				"%w: peer_id=%q channel=%q",
797				ErrTargetPeerNotFound,
798				*envelope.To,
799				envelope.Channel,
800			)
801		}
802		if err := ValidateEnvelope(envelope, ValidateOptions{Now: now, MaxReplayAge: m.router.maxReplayAge}); err != nil {
803			return SendResult{}, err
804		}
805		subject, err := subjectForEnvelope(envelope)
806		if err != nil {
807			return SendResult{}, err
808		}
809		return SendResult{ID: envelope.ID, Subject: subject, Envelope: envelope}, nil
810	}
