812	func (m *Manager) startAuditedHeartbeat(sessionID string, summary string) (*Heartbeat, error) {
813		if m == nil || m.router == nil || m.peers == nil {
814			return nil, errors.New("network: manager heartbeat dependencies are required")
815		}
816	
817		interval := m.peers.GreetInterval()
818		if interval <= 0 {
819			return nil, fmt.Errorf("%w: greet interval must be positive", ErrInvalidField)
820		}
821		if err := m.publishGreetWithAudit(m.lifecycleCtx, sessionID, summary); err != nil {
822			return nil, err
823		}
824	
825		heartbeat := &Heartbeat{
826			stop: make(chan struct{}),
827			done: make(chan struct{}),
828		}
829	
830		go func() {
831			defer close(heartbeat.done)
832	
833			ticker := time.NewTicker(interval)
834			defer ticker.Stop()
835	
836			for {
837				select {
838				case <-heartbeat.stop:
839					return
840				case <-m.lifecycleCtx.Done():
841					return
842				case <-ticker.C:
843					m.sweepExpiredRemotePeers(m.lifecycleCtx, m.now())
844					if err := m.publishGreetWithAudit(m.lifecycleCtx, sessionID, summary); err != nil {
845						switch {
846						case errors.Is(err, context.Canceled), errors.Is(err, ErrLocalPeerNotFound):
847							return
848						default:
849							m.logger.Warn("network.peer.heartbeat_failed", "session_id", sessionID, "error", err)
850						}
851					}
852				}
853			}
854		}()
855	
856		return heartbeat, nil
857	}
