859	func (m *Manager) publishGreetWithAudit(ctx context.Context, sessionID string, summary string) error {
860		if m == nil || m.router == nil {
861			return errors.New("network: manager router is required")
862		}
863	
864		result, err := m.router.PublishGreet(ctx, sessionID, summary)
865		if err != nil {
866			return err
867		}
868		if _, _, err := m.writeConversationMessage(ctx, sessionID, AuditDirectionSent, result.Envelope); err != nil {
869			return fmt.Errorf("network: persist greet presence: %w", err)
870		}
871		m.recordAuditSent(ctx, sessionID, result.Envelope)
872		return nil
873	}
