1022	// Shutdown drains all background work and stops the owned transport.
1023	func (m *Manager) Shutdown(ctx context.Context) error {
1024		if ctx == nil {
1025			return errors.New("network: shutdown context is required")
1026		}
1027		if m == nil {
1028			return nil
1029		}
1030	
1031		m.mu.Lock()
1032		if m.closed {
1033			m.mu.Unlock()
1034			return nil
1035		}
1036		m.closed = true
1037	
1038		sessions := make([]*managedSession, 0, len(m.sessions))
1039		for _, runtime := range m.sessions {
1040			sessions = append(sessions, runtime)
1041		}
1042		channels := make([]*managedChannel, 0, len(m.channels))
1043		for _, runtime := range m.channels {
1044			channels = append(channels, runtime)
1045		}
1046		m.sessions = make(map[string]*managedSession)
1047		m.channels = make(map[string]*managedChannel)
1048		m.mu.Unlock()
1049	
1050		deliveryStats := m.deliveries.stats()
1051		m.cancel()
1052	
1053		var errs []error
1054		for _, runtime := range sessions {
1055			if runtime == nil {
1056				continue
1057			}
1058			m.deliveries.dropSession(runtime.sessionID)
1059			if runtime.heartbeat != nil {
1060				runtime.heartbeat.Stop()
1061			}
1062			if runtime.directSub != nil {
1063				if err := runtime.directSub.Unsubscribe(); err != nil && !errors.Is(err, nats.ErrConnectionClosed) {
1064					errs = append(
1065						errs,
1066						fmt.Errorf("network: unsubscribe direct subject for %q: %w", runtime.sessionID, err),
1067					)
1068				}
1069			}
1070			m.router.Leave(runtime.sessionID)
1071		}
1072		for _, runtime := range channels {
1073			if runtime == nil || runtime.broadcastSub == nil {
1074				continue
1075			}
1076			if err := runtime.broadcastSub.Unsubscribe(); err != nil && !errors.Is(err, nats.ErrConnectionClosed) {
1077				errs = append(errs, fmt.Errorf("network: unsubscribe broadcast subject for %q: %w", runtime.channel, err))
1078			}
1079		}
1080	
1081		m.deliveries.wait()
1082		if m.transport != nil {
1083			if err := m.transport.Shutdown(ctx); err != nil {
1084				errs = append(errs, err)
1085			}
1086		}
1087		m.logger.Info(
1088			"network.stopped",
1089			"pending_messages", deliveryStats.QueuedMessages+deliveryStats.InFlightMessages,
1090			"queued_messages", deliveryStats.QueuedMessages,
1091			"inflight_messages", deliveryStats.InFlightMessages,
1092			"delivery_workers", deliveryStats.DeliveryWorkers,
1093		)
1094	
1095		return errors.Join(errs...)
1096	}
