1098	func (m *Manager) handleInboundMessage(payload []byte) {
1099		if m == nil || m.router == nil {
1100			return
1101		}
1102		if err := m.lifecycleCtx.Err(); err != nil {
1103			return
1104		}
1105	
1106		result, err := m.router.Receive(m.lifecycleCtx, payload)
1107		if err != nil {
1108			m.logger.Warn("network.message.receive_failed", "error", err)
1109			return
1110		}
1111		m.dispatchNetworkPeerLifecycleHooks(m.lifecycleCtx, result.PeerEvents)
1112		persisted, err := m.writeInboundConversationMessages(m.lifecycleCtx, result)
1113		if err != nil {
1114			m.logger.Warn("network.message.persist_failed", "error", err)
1115			if result.Envelope != nil {
1116				m.recordAuditRejected(
1117					m.lifecycleCtx,
1118					inboundRejectedSessionID(m, *result.Envelope),
1119					*result.Envelope,
1120					conversationPersistenceReason(err),
1121				)
1122			}
1123			return
1124		}
1125		if persisted.Duplicate {
1126			m.logger.Info("network.message.receive_duplicate_store", "message_id", persisted.MessageID)
1127			return
1128		}
1129		m.recordInboundAudit(result, persisted.MessageIDs)
1130	
1131		if len(result.Deliveries) == 0 {
1132			return
1133		}
1134		deliveries, err := m.applyDeliverySubscriptions(m.lifecycleCtx, result.Deliveries)
1135		if err != nil {
1136			m.logger.Warn("network.message.subscription_filter_failed", "error", err)
1137			return
1138		}
1139		if len(deliveries) == 0 {
1140			return
1141		}
1142		if err := m.deliveries.accept(m.lifecycleCtx, deliveries); err != nil {
1143			m.logger.Warn("network.message.accept_failed", "error", err)
1144		}
1145	}
