1147	func (m *Manager) applyDeliverySubscriptions(ctx context.Context, deliveries []Delivery) ([]Delivery, error) {
1148		if len(deliveries) == 0 {
1149			return nil, nil
1150		}
1151		subscriptions := networkSubscriptionStoreFromCandidate(m.conversations)
1152		filtered := make([]Delivery, 0, len(deliveries))
1153		for _, delivery := range deliveries {
1154			next := delivery
1155			next.Mode = store.NetworkSubscriptionModeFull
1156			if subscriptions != nil {
1157				mode, err := deliverySubscriptionMode(ctx, subscriptions, delivery)
1158				if err != nil {
1159					return nil, err
1160				}
1161				if mode == store.NetworkSubscriptionModeMute {
1162					continue
1163				}
1164				next.Mode = mode
1165			}
1166			filtered = append(filtered, next)
1167		}
1168		return filtered, nil
1169	}
