1179	func deliverySubscriptionMode(
1180		ctx context.Context,
1181		subscriptions networkSubscriptionStore,
1182		delivery Delivery,
1183	) (string, error) {
1184		if subscriptions == nil {
1185			return store.NetworkSubscriptionModeFull, nil
1186		}
1187		if deliveryMentionsPeer(delivery.Envelope, delivery.PeerID) {
1188			return store.NetworkSubscriptionModeFull, nil
1189		}
1190		workspaceID := strings.TrimSpace(delivery.Envelope.WorkspaceID)
1191		channel := strings.TrimSpace(delivery.Envelope.Channel)
1192		peerID := strings.TrimSpace(delivery.PeerID)
1193		if workspaceID == "" || channel == "" || peerID == "" {
1194			return store.NetworkSubscriptionModeFull, nil
1195		}
1196		if delivery.Envelope.ThreadID != nil {
1197			threadID := strings.TrimSpace(*delivery.Envelope.ThreadID)
1198			if threadID != "" {
1199				threadEntry, ok, err := firstApplicableSubscription(
1200					ctx,
1201					subscriptions,
1202					store.NetworkSubscriptionQuery{
1203						WorkspaceID: workspaceID,
1204						Channel:     channel,
1205						ThreadID:    threadID,
1206						PeerID:      peerID,
1207						Limit:       10,
1208					},
1209					threadID,
1210					delivery.Envelope,
1211				)
1212				if err != nil {
1213					return "", err
1214				}
1215				if ok {
1216					return normalizedDeliverySubscriptionMode(threadEntry.Mode), nil
1217				}
1218			}
1219		}
1220		channelEntry, ok, err := firstApplicableSubscription(
1221			ctx,
1222			subscriptions,
1223			store.NetworkSubscriptionQuery{
1224				WorkspaceID: workspaceID,
1225				Channel:     channel,
1226				PeerID:      peerID,
1227				Limit:       50,
1228			},
1229			"",
1230			delivery.Envelope,
1231		)
1232		if err != nil {
1233			return "", err
1234		}
1235		if ok {
1236			return normalizedDeliverySubscriptionMode(channelEntry.Mode), nil
1237		}
1238		return store.NetworkSubscriptionModeFull, nil
1239	}
1240	
1241	func firstApplicableSubscription(
1242		ctx context.Context,
1243		subscriptions networkSubscriptionStore,
1244		query store.NetworkSubscriptionQuery,
1245		threadID string,
1246		envelope Envelope,
1247	) (store.NetworkSubscriptionEntry, bool, error) {
1248		entries, err := subscriptions.ListNetworkSubscriptions(ctx, query)
1249		if err != nil {
1250			return store.NetworkSubscriptionEntry{}, false, fmt.Errorf("network: list delivery subscriptions: %w", err)
1251		}
1252		for _, entry := range entries {
1253			if strings.TrimSpace(entry.ThreadID) != strings.TrimSpace(threadID) {
1254				continue
1255			}
1256			if !subscriptionKeywordFiltersMatch(entry.KeywordFilters, envelope) {
1257				continue
1258			}
1259			return entry, true, nil
1260		}
1261		return store.NetworkSubscriptionEntry{}, false, nil
1262	}
1263	
1264	func subscriptionKeywordFiltersMatch(filters []string, envelope Envelope) bool {
1265		normalizedFilters := normalizeSubscriptionKeywordFilters(filters)
1266		if len(normalizedFilters) == 0 {
1267			return true
1268		}
1269		text := strings.ToLower(deliverySubscriptionSearchText(envelope))
1270		if text == "" {
1271			return false
1272		}
1273		for _, filter := range normalizedFilters {
1274			if strings.Contains(text, strings.ToLower(filter)) {
1275				return true
1276			}
1277		}
1278		return false
1279	}
