1335	) (conversationPersistenceSummary, error) {
1336		summary := conversationPersistenceSummary{MessageIDs: make(map[string]struct{})}
1337		if m == nil || m.conversations == nil {
1338			return summary, nil
1339		}
1340		if result.Envelope != nil && !result.Rejected && !result.Ignored && len(result.Deliveries) > 0 {
1341			writeResult, wrote, err := m.writeConversationMessage(
1342				ctx,
1343				result.Deliveries[0].SessionID,
1344				AuditDirectionReceived,
1345				*result.Envelope,
1346			)
1347			if err != nil {
1348				return conversationPersistenceSummary{}, err
1349			}
1350			if wrote {
1351				if writeResult.Duplicate {
1352					if m.isLocalEnvelopeSender(*result.Envelope) {
1353						summary.MessageIDs[result.Envelope.ID] = struct{}{}
1354						return summary, nil
1355					}
1356					summary.Duplicate = true
1357					summary.MessageID = writeResult.MessageID
1358					return summary, nil
1359				}
1360				summary.MessageIDs[result.Envelope.ID] = struct{}{}
1361			}
1362		}
1363	
1364		for _, envelope := range result.Generated {
1365			local, ok := m.peers.LocalByPeer(envelope.WorkspaceID, envelope.Channel, envelope.From)
1366			if !ok {
1367				continue
1368			}
1369			writeResult, wrote, err := m.writeConversationMessage(ctx, local.SessionID, AuditDirectionSent, envelope)
1370			if err != nil {
1371				return conversationPersistenceSummary{}, err
1372			}
1373			if wrote && !writeResult.Duplicate {
1374				summary.MessageIDs[envelope.ID] = struct{}{}
1375			}
1376		}
1377		return summary, nil
1378	}
