548		}
549		if normalized.Timestamp.IsZero() {
550			normalized.Timestamp = g.now()
551		}
552		normalized.Timestamp = normalized.Timestamp.UTC()
553		if err := normalized.Validate(); err != nil {
554			return store.NetworkConversationMessage{}, fmt.Errorf("store: validate network conversation message: %w", err)
555		}
556		if strings.TrimSpace(normalized.SessionID) == "" {
557			return store.NetworkConversationMessage{}, fmt.Errorf(
558				"store: network conversation message session_id is required",
559			)
560		}
561		return normalized, nil
562	}
