815	func applyNetworkWorkMutation(
816		ctx context.Context,
817		exec networkSQLExecutor,
818		entry store.NetworkConversationMessage,
819	) (networkWorkMutation, error) {
820		if strings.TrimSpace(entry.WorkID) == "" {
821			return networkWorkMutation{}, nil
822		}
823	
824		current, err := getNetworkWorkWithExecutor(ctx, exec, entry.WorkspaceID, entry.WorkID)
825		if err != nil {
826			if errors.Is(err, sql.ErrNoRows) {
827				return openNetworkWorkWithExecutor(ctx, exec, entry)
828			}
829			return networkWorkMutation{}, err
830		}
831		if !networkWorkMatchesMessage(current, entry) {
832			return networkWorkMutation{}, fmt.Errorf("%w: work_id=%q", store.ErrNetworkWorkContainerMismatch, entry.WorkID)
833		}
834		if networkWorkStateIsTerminal(current.State) {
835			return networkWorkMutation{}, fmt.Errorf("%w: work_id=%q", store.ErrNetworkWorkClosed, entry.WorkID)
836		}
837	
838		next, transitioned, err := nextNetworkWorkState(current.State, entry)
839		if err != nil {
840			return networkWorkMutation{}, err
841		}
842		if !transitioned {
843			return networkWorkMutation{state: current.State}, nil
844		}
845	
846		var terminalAt any
847		if networkWorkStateIsTerminal(next) {
848			terminalAt = store.FormatTimestamp(entry.Timestamp)
849		}
850		if _, err := exec.ExecContext(
851			ctx,
852			`UPDATE network_work
853			SET state = ?, last_activity_at = ?, terminal_at = ?
854			WHERE workspace_id = ? AND work_id = ?`,
855			next,
856			store.FormatTimestamp(entry.Timestamp),
857			terminalAt,
858			entry.WorkspaceID,
859			entry.WorkID,
860		); err != nil {
861			return networkWorkMutation{}, fmt.Errorf("store: update network work: %w", err)
862		}
863		return networkWorkMutation{transitioned: true, state: next}, nil
864	}
