924	func networkWorkMatchesMessage(work store.NetworkWorkEntry, entry store.NetworkConversationMessage) bool {
925		return work.WorkspaceID == entry.WorkspaceID &&
926			work.Channel == entry.Channel &&
927			work.Surface == entry.Surface &&
