931	
932	func nextNetworkWorkState(current string, entry store.NetworkConversationMessage) (string, bool, error) {
933		switch entry.Kind {
934		case store.NetworkKindSay, store.NetworkKindCapability:
935			if current == store.NetworkWorkStateNeedsInput {
936				return store.NetworkWorkStateWorking, true, nil
937			}
938			return current, false, nil
939		case store.NetworkKindReceipt:
940			return nextNetworkWorkStateFromReceipt(current, entry.Body)
941		case store.NetworkKindTrace:
942			return nextNetworkWorkStateFromTrace(current, entry.Body)
943		default:
944			return current, false, nil
945		}
946	}
947	
948	func nextNetworkWorkStateFromReceipt(current string, body json.RawMessage) (string, bool, error) {
949		var receipt struct {
950			Status string `json:"status"`
951		}
952		if err := json.Unmarshal(body, &receipt); err != nil {
953			return "", false, fmt.Errorf("store: decode network receipt body: %w", err)
954		}
955		switch strings.TrimSpace(receipt.Status) {
956		case "accepted", "duplicate", "expired", "unsupported":
957			return current, false, nil
958		case globalDBNetworkConversationsRejectedKey:
959			return store.NetworkWorkStateFailed, true, nil
960		case "canceled":
961			return store.NetworkWorkStateCanceled, true, nil
962		default:
963			return "", false, fmt.Errorf("store: unsupported network receipt status %q", receipt.Status)
964		}
965	}
966	
967	func nextNetworkWorkStateFromTrace(current string, body json.RawMessage) (string, bool, error) {
968		var trace struct {
969			State string `json:"state"`
970		}
971		if err := json.Unmarshal(body, &trace); err != nil {
972			return "", false, fmt.Errorf("store: decode network trace body: %w", err)
973		}
974		next := strings.TrimSpace(trace.State)
975		if !canAdvanceNetworkWorkState(current, next) {
976			return "", false, fmt.Errorf("store: invalid network work transition %s -> %s", current, next)
977		}
978		return next, true, nil
979	}
980	
981	func canAdvanceNetworkWorkState(current string, next string) bool {
982		if networkWorkStateIsTerminal(current) {
983			return false
984		}
985		switch current {
986		case store.NetworkWorkStateSubmitted, store.NetworkWorkStateWorking, store.NetworkWorkStateNeedsInput:
987		default:
988			return false
989		}
990		switch next {
991		case store.NetworkWorkStateWorking,
992			store.NetworkWorkStateNeedsInput,
993			store.NetworkWorkStateCompleted,
994			store.NetworkWorkStateFailed,
995			store.NetworkWorkStateCanceled:
996			return true
997		default:
998			return false
999		}
1000	}
1001	
1002	func networkWorkStateIsTerminal(state string) bool {
1003		switch state {
1004		case store.NetworkWorkStateCompleted, store.NetworkWorkStateFailed, store.NetworkWorkStateCanceled:
1005			return true
1006		default:
1007			return false
1008		}
1009	}
