48		var result taskpkg.ClaimResult
49		if err := g.withTaskImmediateTransaction(ctx, "claim next task run", func(exec taskSQLExecutor) error {
50			if err := g.ensureClaimerHasNoActiveLease(ctx, exec, normalized); err != nil {
51				return err
52			}
53			runID, err := g.selectClaimableRunID(ctx, exec, normalized)
54			if err != nil {
55				return err
56			}
57			if runID == "" {
58				return taskpkg.ErrNoClaimableRun
59			}
60	
61			claimToken, err := taskpkg.NewClaimToken()
62			if err != nil {
63				return err
64			}
65			claimHash, err := taskpkg.ClaimTokenHash(claimToken)
66			if err != nil {
67				return err
68			}
69			leaseUntil := normalized.Now.Add(normalized.LeaseDuration).UTC()
70			if err := claimRunWithExecutor(ctx, exec, runID, normalized, claimToken, claimHash, leaseUntil); err != nil {
71				return err
72			}
73			if err := setTaskCurrentRunProjectionForRun(ctx, exec, runID); err != nil {
74				return err
75			}
76	
77			run, err := g.getTaskRunWithExecutor(ctx, exec, runID)
78			if err != nil {
79				return err
80			}
81			taskRecord, err := g.getTaskWithExecutor(ctx, exec, run.TaskID)
82			if err != nil {
83				return err
84			}
85			channel, err := g.coordinationChannelMetadata(ctx, exec, taskRecord, run)
86			if err != nil {
87				return err
88			}
89			result = taskpkg.ClaimResult{
90				Task:                taskRecord,
91				Run:                 run,
92				ClaimToken:          claimToken,
93				LeaseUntil:          leaseUntil,
94				CoordinationChannel: channel,
95			}
96			return nil
97		}); err != nil {
98			return taskpkg.ClaimResult{}, err
99		}
100	
101		return taskpkg.ClaimResult{
102			Task:                result.Task,
103			Run:                 result.Run,
104			ClaimToken:          result.ClaimToken,
105			LeaseUntil:          result.LeaseUntil,
106			CoordinationChannel: result.CoordinationChannel,
107		}, nil
108	}
