405	// RecoverExpiredRunLeases requeues stale active leases without issuing new ownership.
406	func (g *GlobalDB) RecoverExpiredRunLeases(
407		ctx context.Context,
408		recovery taskpkg.ExpiredLeaseRecovery,
409	) ([]taskpkg.ExpiredLeaseRecoveryResult, error) {
410		if err := g.checkReady(ctx, "recover expired task run leases"); err != nil {
411			return nil, err
412		}
413		normalized, err := recovery.Normalize(g.now())
414		if err != nil {
415			return nil, err
416		}
417	
418		recovered := make([]taskpkg.ExpiredLeaseRecoveryResult, 0)
419		if err := g.withTaskImmediateTransaction(ctx, "recover expired task run leases", func(exec taskSQLExecutor) error {
420			runIDs, err := expiredLeaseRunIDs(ctx, exec, normalized)
421			if err != nil {
422				return err
423			}
424			for _, runID := range runIDs {
425				current, err := g.getTaskRunWithExecutor(ctx, exec, runID)
426				if err != nil {
427					return err
428				}
429				if current.LeaseUntil.IsZero() || current.LeaseUntil.After(normalized.Now) {
430					continue
431				}
432				snapshot := taskRunLeaseSnapshot{
433					status:         current.Status,
434					sessionID:      current.SessionID,
435					leaseUntil:     current.LeaseUntil,
436					claimTokenHash: current.ClaimTokenHash,
437				}
438				if err := requeueExpiredLease(ctx, exec, current, snapshot); err != nil {
439					return err
440				}
441				if err := clearTaskCurrentRunProjection(ctx, exec, current.TaskID, current.ID); err != nil {
442					return err
443				}
444				updated, err := g.getTaskRunWithExecutor(ctx, exec, current.ID)
445				if err != nil {
446					return err
447				}
448				recovered = append(recovered, taskpkg.ExpiredLeaseRecoveryResult{
449					Run:                    updated,
450					PreviousRunStatus:      snapshot.status,
451					PreviousSessionID:      snapshot.sessionID,
452					PreviousLeaseUntil:     snapshot.leaseUntil,
453					PreviousClaimTokenHash: snapshot.claimTokenHash,
454					Reason:                 normalized.Reason,
455				})
456			}
457			return nil
458		}); err != nil {
459			return nil, err
460		}
461	
462		return recovered, nil
463	}
