465	func (g *GlobalDB) ensureClaimerHasNoActiveLease(
466		ctx context.Context,
467		exec taskSQLExecutor,
468		criteria taskpkg.ClaimCriteria,
469	) error {
470		var count int
471		if err := exec.QueryRowContext(
472			ctx,
473			`SELECT COUNT(1)
474			 FROM task_runs
475			 WHERE session_id = ?
476			   AND status IN (?, ?, ?)
477			   AND (lease_until IS NULL OR lease_until > ?)`,
478			criteria.ClaimerSessionID,
479			string(taskpkg.TaskRunStatusClaimed),
480			string(taskpkg.TaskRunStatusStarting),
481			string(taskpkg.TaskRunStatusRunning),
482			store.FormatTimestamp(criteria.Now),
483		).Scan(&count); err != nil {
484			return fmt.Errorf("store: count active task-run leases for %q: %w", criteria.ClaimerSessionID, err)
485		}
486		if count > 0 {
487			return fmt.Errorf(
488				"%w: session %q already owns an active task-run lease",
489				taskpkg.ErrActiveRunLease,
490				criteria.ClaimerSessionID,
491			)
492		}
493		return nil
494	}
