496	func (g *GlobalDB) selectClaimableRunID(
497		ctx context.Context,
498		exec taskSQLExecutor,
499		criteria taskpkg.ClaimCriteria,
500	) (string, error) {
501		where := []string{
502			"tr.status = ?",
503			"COALESCE(t.paused, 0) = 0",
504			`NOT EXISTS (SELECT 1 FROM scheduler_pause sp WHERE sp.id = 1 AND sp.paused = 1)`,
505			`NOT EXISTS (
506				WITH RECURSIVE ancestors(id, parent_task_id, paused) AS (
507					SELECT parent.id, parent.parent_task_id, parent.paused
508					  FROM tasks parent
509					 WHERE parent.id = t.parent_task_id
510					UNION ALL
511					SELECT parent.id, parent.parent_task_id, parent.paused
512					  FROM tasks parent
513					  JOIN ancestors a ON parent.id = a.parent_task_id
514				)
515				SELECT 1 FROM ancestors WHERE COALESCE(paused, 0) = 1
516			)`,
517			"t.status NOT IN (?, ?, ?)",
518			taskPriorityValueSQL + " >= ?",
519			`NOT EXISTS (
520				SELECT 1
521				  FROM task_run_required_capabilities req
522				 WHERE req.run_id = tr.id` + missingCapabilityPredicate(criteria.RequiredCapabilities) + `
523			)`,
524		}
525		args := []any{
526			string(taskpkg.TaskRunStatusQueued),
527			string(taskpkg.TaskStatusDraft),
528			string(taskpkg.TaskStatusBlocked),
529			string(taskpkg.TaskStatusCanceled),
530			criteria.PriorityMin,
531		}
532		args = append(args, missingCapabilityArgs(criteria.RequiredCapabilities)...)
533		if criteria.Scope == taskpkg.ScopeWorkspace {
534			where = append(where, "t.scope = ?", "t.workspace_id = ?")
535			args = append(args, string(taskpkg.ScopeWorkspace), criteria.WorkspaceID)
536		} else {
537			where = append(where, "t.scope = ?")
538			args = append(args, string(taskpkg.ScopeGlobal))
539		}
540		if strings.TrimSpace(criteria.CoordinationChannelID) != "" {
541			where = append(where, "tr.coordination_channel_id = ?")
542			args = append(args, criteria.CoordinationChannelID)
543		}
544		where, args = appendProfileClaimFilters(where, args, criteria)
545		where, args = appendClaimOwnerPredicate(where, args, criteria)
546		args = append(args, preferredCapabilityArgs(criteria.RequiredCapabilities)...)
547	
548		query := `SELECT tr.id
549			FROM task_runs tr
550			JOIN tasks t ON t.id = tr.task_id
551			WHERE ` + strings.Join(where, " AND ") + `
552			ORDER BY ` + taskPriorityValueSQL + ` DESC,
553			         ` + preferredCapabilityOrder(criteria.RequiredCapabilities) + `
554			         tr.queued_at ASC,
555			         tr.id ASC
556			LIMIT 1`
557	
558		var runID string
559		if err := exec.QueryRowContext(ctx, query, args...).Scan(&runID); err != nil {
560			if errors.Is(err, sql.ErrNoRows) {
561				return "", nil
562			}
563			return "", fmt.Errorf("store: select claimable task run: %w", err)
564		}
565		return runID, nil
566	}
567	
568	func appendProfileClaimFilters(
569		where []string,
570		args []any,
571		criteria taskpkg.ClaimCriteria,
572	) ([]string, []any) {
573		where, args = appendProfileRequiredCapabilityFilter(
574			where,
575			args,
576			profileRoleWorker,
577			criteria.RequiredCapabilities,
578		)
579		where, args = appendProfileRequiredCapabilityFilter(
580			where,
581			args,
582			profileRoleParticipant,
583			criteria.RequiredCapabilities,
584		)
585		agentName := strings.TrimSpace(criteria.AgentName)
586		where = append(where, `NOT EXISTS (
587				SELECT 1
588				  FROM task_execution_profiles tep
589				 WHERE tep.task_id = t.id
590				   AND COALESCE(tep.worker_agent_name, '') <> ''
591				   AND tep.worker_agent_name <> ?
592			)`)
593		args = append(args, agentName)
594		where, args = appendProfileAllowedAgentFilter(where, args, profileRoleWorker, agentName)
595		return appendProfileAllowedAgentFilter(where, args, profileRoleParticipant, agentName)
596	}
597	
598	func appendProfileRequiredCapabilityFilter(
599		where []string,
600		args []any,
601		role string,
602		capabilities []string,
603	) ([]string, []any) {
604		where = append(where, `NOT EXISTS (
605				SELECT 1
606				  FROM task_profile_capabilities pc
607				 WHERE pc.task_id = t.id
608				   AND pc.role = ?
609				   AND pc.preference = ?`+missingCapabilityPredicateFor("pc.capability_id", capabilities)+`
610			)`)
611		args = append(args, role, profilePreferenceRequired)
612		args = append(args, missingCapabilityArgs(capabilities)...)
613		return where, args
614	}
615	
616	func appendProfileAllowedAgentFilter(
617		where []string,
618		args []any,
619		role string,
620		agentName string,
621	) ([]string, []any) {
622		where = append(where, `(NOT EXISTS (
623				SELECT 1
624				  FROM task_profile_agents pa_all
625				 WHERE pa_all.task_id = t.id
626				   AND pa_all.role = ?
627				   AND pa_all.preference = ?
628			) OR EXISTS (
629				SELECT 1
630				  FROM task_profile_agents pa_match
631				 WHERE pa_match.task_id = t.id
632				   AND pa_match.role = ?
633				   AND pa_match.preference = ?
634				   AND pa_match.agent_name = ?
635			))`)
636		args = append(args, role, profilePreferenceAllowed, role, profilePreferenceAllowed, agentName)
637		return where, args
638	}
639	
640	func appendClaimOwnerPredicate(
641		where []string,
642		args []any,
643		criteria taskpkg.ClaimCriteria,
644	) ([]string, []any) {
645		clauses := []string{"COALESCE(t.owner_kind, '') = ''"}
646		if agentName := strings.TrimSpace(criteria.AgentName); agentName != "" {
647			clauses = append(clauses, "(t.owner_kind = ? AND t.owner_ref = ?)")
648			args = append(args, string(taskpkg.OwnerKindPool), agentName)
649		}
650		if sessionID := strings.TrimSpace(criteria.ClaimerSessionID); sessionID != "" {
651			clauses = append(clauses, "(t.owner_kind = ? AND t.owner_ref = ?)")
652			args = append(args, string(taskpkg.OwnerKindAgentSession), sessionID)
653		}
654		where = append(where, "("+strings.Join(clauses, " OR ")+")")
