619		ctx context.Context,
620		taskID string,
621		runID string,
622		idempotencyKey string,
623		origin taskpkg.Origin,
624		requestedChannel string,
625		metadata json.RawMessage,
626		queuedAt time.Time,
627		designationGroupID ...string,
628	) (taskpkg.Task, taskpkg.Run, bool, error) {
629		if err := g.checkReady(ctx, "reserve queued task run"); err != nil {
630			return taskpkg.Task{}, taskpkg.Run{}, false, err
631		}
632	
633		input, err := g.normalizeQueuedRunReservationInput(
634			taskID,
635			runID,
636			idempotencyKey,
637			origin,
638			requestedChannel,
639			metadata,
640			queuedAt,
641			designationGroupID...,
642		)
643		if err != nil {
644			return taskpkg.Task{}, taskpkg.Run{}, false, err
645		}
646	
647		var reservedTask taskpkg.Task
648		var reservedRun taskpkg.Run
649		var existing bool
650		if err := g.withTaskImmediateTransaction(ctx, "reserve queued task run", func(exec taskSQLExecutor) error {
651			taskRecord, runRecord, alreadyExists, err := g.reserveQueuedRunWithExecutor(ctx, exec, input)
652			if err != nil {
653				return err
654			}
655			reservedTask = taskRecord
656			reservedRun = runRecord
657			existing = alreadyExists
658			return nil
659		}); err != nil {
660			return taskpkg.Task{}, taskpkg.Run{}, false, err
661		}
662	
663		return reservedTask, reservedRun, existing, nil
664	}
