666	func (g *GlobalDB) normalizeQueuedRunReservationInput(
667		taskID string,
668		runID string,
669		idempotencyKey string,
670		origin taskpkg.Origin,
671		requestedChannel string,
672		metadata json.RawMessage,
673		queuedAt time.Time,
674		designationGroupID ...string,
675	) (queuedRunReservationInput, error) {
676		trimmedTaskID, err := requireTaskValue(taskID, "task id")
677		if err != nil {
678			return queuedRunReservationInput{}, err
679		}
680		trimmedRunID, err := requireTaskValue(runID, "task run id")
681		if err != nil {
682			return queuedRunReservationInput{}, err
683		}
684		normalizedOrigin := taskpkg.Origin{
685			Kind: origin.Kind.Normalize(),
686			Ref:  strings.TrimSpace(origin.Ref),
687		}
688		if err := normalizedOrigin.Validate("task_run.origin"); err != nil {
689			return queuedRunReservationInput{}, err
690		}
691		trimmedKey := strings.TrimSpace(idempotencyKey)
692		normalizedMetadata := normalizeTaskJSON(metadata)
693		if err := taskpkg.ValidateMetadataSize(normalizedMetadata, "enqueue_run.metadata"); err != nil {
694			return queuedRunReservationInput{}, err
695		}
696		normalizedQueuedAt := queuedAt.UTC()
697		if normalizedQueuedAt.IsZero() {
698			normalizedQueuedAt = g.now()
699		}
700		return queuedRunReservationInput{
701			taskID:             trimmedTaskID,
702			runID:              trimmedRunID,
703			idempotencyKey:     trimmedKey,
704			origin:             normalizedOrigin,
705			requestedChannel:   strings.TrimSpace(requestedChannel),
706			designationGroupID: firstQueuedRunDesignationGroupID(designationGroupID),
707			metadata:           normalizedMetadata,
708			queuedAt:           normalizedQueuedAt,
709		}, nil
710	}
