721	func (g *GlobalDB) reserveQueuedRunWithExecutor(
722		ctx context.Context,
723		exec taskSQLExecutor,
724		input queuedRunReservationInput,
725	) (taskpkg.Task, taskpkg.Run, bool, error) {
726		taskRecord, err := g.getTaskWithExecutor(ctx, exec, input.taskID)
727		if err != nil {
728			return taskpkg.Task{}, taskpkg.Run{}, false, err
729		}
730		if err := validateTaskForQueuedRunReservation(taskRecord); err != nil {
731			return taskpkg.Task{}, taskpkg.Run{}, false, err
732		}
733	
734		runRecord, exists, err := g.lookupQueuedRunReservationByIdempotency(
735			ctx,
736			exec,
737			taskRecord,
738			input.idempotencyKey,
739			input.origin,
740		)
741		if err != nil {
742			return taskpkg.Task{}, taskpkg.Run{}, false, err
743		}
744		if exists {
745			return taskRecord, runRecord, true, nil
746		}
747	
748		openRunID, err := g.findOpenRunIDForQueuedRunReservation(ctx, exec, taskRecord.ID)
749		if err != nil {
750			return taskpkg.Task{}, taskpkg.Run{}, false, err
751		}
752		if openRunID != "" {
753			return taskpkg.Task{}, taskpkg.Run{}, false, fmt.Errorf(
754				"%w: task %q has open run %q; finish or cancel it before enqueueing another run",
755				taskpkg.ErrInvalidStatusTransition,
756				taskRecord.ID,
757				openRunID,
758			)
759		}
760	
761		runRecord, err = g.createQueuedRunWithExecutor(ctx, exec, taskRecord, input)
762		if err != nil {
763			return taskpkg.Task{}, taskpkg.Run{}, false, err
764		}
765		return taskRecord, runRecord, false, nil
766	}
