768	func (g *GlobalDB) lookupQueuedRunReservationByIdempotency(
769		ctx context.Context,
770		exec taskSQLExecutor,
771		taskRecord taskpkg.Task,
772		idempotencyKey string,
773		origin taskpkg.Origin,
774	) (taskpkg.Run, bool, error) {
775		if idempotencyKey == "" {
776			return taskpkg.Run{}, false, nil
777		}
778	
779		current, err := getTaskRunIdempotencyRecord(ctx, exec, idempotencyKey, origin)
780		switch {
781		case errors.Is(err, taskpkg.ErrTaskRunIdempotencyNotFound):
782			return taskpkg.Run{}, false, nil
783		case err != nil:
784			return taskpkg.Run{}, false, err
785		}
786	
787		run, err := g.getTaskRunWithExecutor(ctx, exec, current.RunID)
788		if err != nil {
789			return taskpkg.Run{}, false, err
790		}
791		if strings.TrimSpace(run.TaskID) != taskRecord.ID {
792			return taskpkg.Run{}, false, fmt.Errorf(
793				"%w: idempotency key %q is already bound to task %q",
794				taskpkg.ErrValidation,
795				idempotencyKey,
796				run.TaskID,
797			)
798		}
799		return run, true, nil
800	}
