814		coordinationChannelID := coordinationChannelIDForQueuedRun(taskRecord, networkChannel, input.runID)
815		if err := ensureQueuedRunCoordinationChannel(
816			ctx,
817			exec,
818			taskRecord,
819			coordinationChannelID,
820			input.origin,
821			input.queuedAt,
822		); err != nil {
823			return taskpkg.Run{}, err
824		}
825		run := taskpkg.Run{
826			ID:                    input.runID,
827			TaskID:                taskRecord.ID,
828			Status:                taskpkg.TaskRunStatusQueued,
829			Attempt:               nextAttempt,
830			Origin:                input.origin,
831			IdempotencyKey:        input.idempotencyKey,
832			NetworkChannel:        networkChannel,
833			DesignationGroupID:    input.designationGroupID,
834			CoordinationChannelID: coordinationChannelID,
