860	
861	func ensureQueuedRunCoordinationChannel(
862		ctx context.Context,
863		exec taskSQLExecutor,
864		taskRecord taskpkg.Task,
865		channelID string,
866		origin taskpkg.Origin,
867		queuedAt time.Time,
868	) error {
869		trimmedChannelID := strings.TrimSpace(channelID)
870		if trimmedChannelID == "" {
871			return nil
872		}
873		trimmedWorkspaceID := strings.TrimSpace(taskRecord.WorkspaceID)
874		if trimmedWorkspaceID == "" {
875			return fmt.Errorf(
876				"%w: workspace task %q requires workspace_id for coordination channel",
877				taskpkg.ErrValidation,
878				taskRecord.ID,
879			)
880		}
881	
882		entry, err := networkChannelEntry(ctx, exec, trimmedChannelID)
883		switch {
884		case err == nil:
885			if strings.TrimSpace(entry.WorkspaceID) != trimmedWorkspaceID {
886				return fmt.Errorf(
887					"%w: coordination channel %q belongs to workspace %q, not %q",
888					taskpkg.ErrValidation,
889					trimmedChannelID,
890					entry.WorkspaceID,
891					trimmedWorkspaceID,
892				)
893			}
894			return nil
895		case errors.Is(err, sql.ErrNoRows):
896		default:
897			return err
898		}
899	
900		timestamp := queuedAt.UTC()
901		if timestamp.IsZero() {
902			timestamp = time.Now().UTC()
903		}
904		_, err = exec.ExecContext(
905			ctx,
906			`INSERT INTO network_channels (
907				channel,
908				workspace_id,
909				purpose,
910				created_by,
911				created_at,
912				updated_at
913			) VALUES (?, ?, ?, ?, ?, ?)`,
914			trimmedChannelID,
915			trimmedWorkspaceID,
916			"task_run_coordination",
917			coordinationChannelCreatedBy(origin),
918			store.FormatTimestamp(timestamp),
919			store.FormatTimestamp(timestamp),
920		)
921		if err != nil {
922			return fmt.Errorf("store: create task-run coordination channel %q: %w", trimmedChannelID, err)
923		}
924		return nil
925	}
926	
927	func derivedRunCoordinationChannelID(runID string) string {
928		seed := strings.ToLower(strings.TrimSpace(runID))
929		cleaned := make([]rune, 0, len(seed))
930		lastDash := false
931		for _, r := range seed {
932			switch {
933			case r >= 'a' && r <= 'z', r >= '0' && r <= '9', r == '_':
934				cleaned = append(cleaned, r)
935				lastDash = false
936			case r == '-':
937				if len(cleaned) > 0 && !lastDash {
938					cleaned = append(cleaned, r)
939					lastDash = true
940				}
941			default:
942				if len(cleaned) > 0 && !lastDash {
943					cleaned = append(cleaned, '-')
944					lastDash = true
945				}
946			}
947			if len(cleaned) >= 58 {
948				break
949			}
950		}
951		value := strings.Trim(string(cleaned), "-_")
952		if value == "" || !validCoordinationChannelStart(value[0]) {
953			sum := sha256.Sum256([]byte(seed))
954			value = fmt.Sprintf("run-%x", sum[:6])
955		}
956		return "coord-" + value
957	}
958	
959	func validCoordinationChannelStart(value byte) bool {
960		return (value >= 'a' && value <= 'z') || (value >= '0' && value <= '9')
961	}
962	
963	func coordinationChannelCreatedBy(origin taskpkg.Origin) string {
964		kind := strings.TrimSpace(string(origin.Kind.Normalize()))
965		ref := strings.TrimSpace(origin.Ref)
966		if kind == "" {
967			return ref
968		}
969		if ref == "" {
970			return kind
971		}
972		return kind + ":" + ref
973	}
