1203	func (g *GlobalDB) withTaskImmediateTransaction(
1204		ctx context.Context,
1205		action string,
1206		run func(exec taskSQLExecutor) error,
1207	) (err error) {
1208		conn, err := g.db.Conn(ctx)
1209		if err != nil {
1210			return fmt.Errorf("store: open connection for %s: %w", action, err)
1211		}
1212		defer func() {
1213			_ = conn.Close()
1214		}()
1215	
1216		rollbackCtx := context.WithoutCancel(ctx)
1217		if _, err := conn.ExecContext(ctx, "BEGIN IMMEDIATE"); err != nil {
1218			return fmt.Errorf("store: begin immediate %s transaction: %w", action, err)
1219		}
1220	
1221		finished := false
1222		defer func() {
1223			if !finished {
1224				joinCleanupError(&err, rollbackImmediate(rollbackCtx, conn, action))
1225			}
1226		}()
1227	
1228		if err := run(conn); err != nil {
1229			return err
1230		}
1231	
1232		if _, err = conn.ExecContext(ctx, "COMMIT"); err != nil {
1233			return fmt.Errorf("store: commit %s transaction: %w", action, err)
1234		}
1235	
1236		finished = true
1237		return nil
1238	}
