782			if _, err := globalDB.db.ExecContext(ctx, healSchedulerPauseUpdatedAtSQL); err != nil {
783				t.Fatalf("first heal error = %v", err)
784			}
785			first := schedulerPauseUpdatedAtFromDB(ctx, t, globalDB)
786			if _, err := globalDB.db.ExecContext(ctx, healSchedulerPauseUpdatedAtSQL); err != nil {
787				t.Fatalf("second heal error = %v", err)
788			}
789			second := schedulerPauseUpdatedAtFromDB(ctx, t, globalDB)
790			if first != second {
791				t.Fatalf("heal is not idempotent: first %q, second %q", first, second)
792			}
793			if want := "2026-05-28T15:50:25.000000000Z"; second != want {
794				t.Fatalf("healed updated_at = %q, want %q", second, want)
795			}
796			if _, parseErr := store.ParseTimestamp(second); parseErr != nil {
