138		tree, err := m.collectTaskTree(ctx, trimmedTaskID)
139		if err != nil {
140			return nil, err
141		}
142		if len(tree) == 0 {
143			return nil, ErrTaskNotFound
144		}
145	
146		nodes, err := m.buildTreeNodes(ctx, tree)
147		if err != nil {
148			return nil, err
149		}
150		view := splitTreeView(trimmedTaskID, nodes)
151		return &view, nil
152	}
