154	func (m *Service) buildTreeNodes(ctx context.Context, tree []Task) ([]TreeNode, error) {
155		depthByID := make(map[string]int, len(tree))
156		depthByID[tree[0].ID] = 0
157		childCountByID := make(map[string]int, len(tree))
158		for _, record := range tree[1:] {
159			childCountByID[record.ParentTaskID]++
160		}
161	
162		nodes := make([]TreeNode, 0, len(tree))
163		for _, record := range tree {
164			node, err := m.buildTreeNode(ctx, record, depthByID, childCountByID)
165			if err != nil {
166				return nil, err
167			}
168			nodes = append(nodes, node)
169		}
170	
171		sort.SliceStable(nodes, func(i, j int) bool {
172			if nodes[i].Depth != nodes[j].Depth {
173				return nodes[i].Depth < nodes[j].Depth
174			}
175			if !nodes[i].LastActivityAt.Equal(nodes[j].LastActivityAt) {
176				return nodes[i].LastActivityAt.After(nodes[j].LastActivityAt)
177			}
178			return nodes[i].Task.ID < nodes[j].Task.ID
179		})
180		return nodes, nil
181	}
