220	func splitTreeView(rootTaskID string, nodes []TreeNode) TreeView {
221		rootIndex := 0
222		for idx := range nodes {
223			if nodes[idx].Task.ID == rootTaskID {
224				rootIndex = idx
225				break
226			}
227		}
228	
229		root := nodes[rootIndex]
230		descendants := make([]TreeNode, 0, len(nodes)-1)
231		for idx, node := range nodes {
232			if idx == rootIndex {
233				continue
234			}
235			descendants = append(descendants, node)
236		}
237		return TreeView{Root: root, Descendants: descendants}
238	}
