484	func summarizeSessionEvents(events []store.SessionEvent) RunOperationalSummary {
485		sorted := append([]store.SessionEvent(nil), events...)
486		sort.SliceStable(sorted, func(i, j int) bool {
487			if sorted[i].Sequence != sorted[j].Sequence {
488				return sorted[i].Sequence < sorted[j].Sequence
489			}
490			if !sorted[i].Timestamp.Equal(sorted[j].Timestamp) {
491				return sorted[i].Timestamp.Before(sorted[j].Timestamp)
492			}
493			return sorted[i].ID < sorted[j].ID
494		})
495	
496		summary := RunOperationalSummary{}
497		toolCalls := make(map[string]struct{})
498		for _, event := range sorted {
499			if event.Timestamp.After(summary.LastActivityAt) {
500				summary.LastActivityAt = event.Timestamp
501				summary.LastEventType = event.Type
502			}
503			if event.Type != sessionEventTypeToolCall && event.Type != sessionEventTypeToolResult {
504				continue
505			}
506	
507			decoded := struct {
508				ToolCallIDSnake string `json:"tool_call_id"`
509				ToolCallIDCamel string `json:"toolCallId"`
510			}{}
511			if err := json.Unmarshal([]byte(event.Content), &decoded); err == nil {
512				toolCallID := strings.TrimSpace(decoded.ToolCallIDSnake)
513				if toolCallID == "" {
514					toolCallID = strings.TrimSpace(decoded.ToolCallIDCamel)
515				}
516				if toolCallID != "" {
517					toolCalls[toolCallID] = struct{}{}
518					continue
519				}
520			}
521	
522			fallbackID := strings.TrimSpace(event.TurnID) + ":" + event.ID
523			if fallbackID != ":" {
524				toolCalls[fallbackID] = struct{}{}
525				continue
526			}
527			toolCalls[event.ID] = struct{}{}
528		}
529	
530		if len(toolCalls) > 0 {
531			count := int64(len(toolCalls))
532			summary.ToolCallCount = &count
533		}
534		return summary
535	}
