615	func (m *Service) runTaskStreamSubscriber(
616		ctx context.Context,
617		subscriber *taskStreamSubscriber,
618		afterSequence int64,
619		backlog []StreamEvent,
620	) {
621		defer func() {
622			m.unregisterTaskSubscriber(subscriber.id)
623			subscriber.stop()
624			close(subscriber.out)
625		}()
626	
627		nextSequence := afterSequence
628		emit := func(event StreamEvent) bool {
629			if event.Sequence <= nextSequence {
630				return true
631			}
632			select {
633			case <-ctx.Done():
634				return false
635			case subscriber.out <- event:
636				nextSequence = event.Sequence
637				return true
638			}
639		}
640	
641		for _, event := range backlog {
642			if !emit(event) {
643				return
644			}
645		}
646	
647		for {
648			select {
649			case <-ctx.Done():
650				return
651			case <-subscriber.done:
652				return
653			case event := <-subscriber.deliver:
654				if !emit(event) {
655					return
656				}
657			}
658		}
659	}
