211	// NewManager constructs one task-domain manager with the supplied dependencies.
212	func NewManager(opts ...Option) (*Service, error) {
213		options := managerOptions{
214			profileValidation: DefaultExecutionProfileValidationOptions(),
215			forceRecovery: ForceRecoveryOptions{
216				AllowAgentForce:    true,
217				RateLimitPerMinute: DefaultForceRunRateLimitPerMinute,
218			},
219			now: func() time.Time {
220				return time.Now().UTC()
221			},
222			newID:         store.NewID,
223			starvationAge: DefaultTaskStarvationAge,
224		}
225		for _, opt := range opts {
226			if opt != nil {
227				opt(&options)
228			}
229		}
230		if options.starvationAge <= 0 {
231			options.starvationAge = DefaultTaskStarvationAge
232		}
233		if options.store == nil {
234			return nil, fmt.Errorf("task: manager store is required")
235		}
236		if options.now == nil {
237			return nil, fmt.Errorf("task: manager clock is required")
238		}
239		if options.newID == nil {
240			return nil, fmt.Errorf("task: manager id generator is required")
241		}
242		if options.cancelGracePeriod < 0 {
243			return nil, fmt.Errorf("task: manager cancel grace period must be zero or positive")
244		}
245	
246		return &Service{
247			store:             options.store,
248			sessions:          options.sessions,
249			runtimeViews:      options.runtimeViews,
250			inspectReader:     options.inspectReader,
251			eventObserver:     options.eventObserver,
252			reviewObserver:    options.reviewObserver,
253			taskHooks:         defaultTaskRunHooks(options.taskHooks),
254			channelValidator:  options.channelValidator,
255			profileValidation: options.profileValidation,
256			forceRecovery:     normalizeForceRecoveryOptions(options.forceRecovery),
257			now:               options.now,
258			newID:             options.newID,
259			cancelGracePeriod: options.cancelGracePeriod,
260			starvationAge:     options.starvationAge,
261			forceRateLimiter:  newForceRunRateLimiter(),
262			liveSubscribers:   make(map[uint64]*taskStreamSubscriber),
