266	// CreateTask derives one canonical task record from trusted actor context and
267	// persists the corresponding immutable audit event.
268	func (m *Service) CreateTask(ctx context.Context, spec CreateTask, actor ActorContext) (*Task, error) {
269		if err := requireCreateAuthority(actor, spec.Scope); err != nil {
270			return nil, err
271		}
272	
273		normalizedSpec, err := normalizeCreateTaskSpec(spec)
274		if err != nil {
275			return nil, err
276		}
277		if err := m.validateParentConstraints(ctx, normalizedSpec); err != nil {
278			return nil, err
279		}
280		if err := m.validateNetworkChannel("create_task.network_channel", normalizedSpec.NetworkChannel); err != nil {
281			return nil, err
282		}
283	
284		now := m.now().UTC()
285		record := Task{
286			ID:                 normalizedSpec.ID,
287			Identifier:         normalizedSpec.Identifier,
288			Scope:              normalizedSpec.Scope,
289			WorkspaceID:        normalizedSpec.WorkspaceID,
290			ParentTaskID:       normalizedSpec.ParentTaskID,
291			NetworkChannel:     normalizedSpec.NetworkChannel,
292			Title:              normalizedSpec.Title,
293			Description:        normalizedSpec.Description,
294			Priority:           normalizedSpec.Priority,
295			MaxAttempts:        createTaskMaxAttempts(normalizedSpec),
296			AutoEnqueueOnReady: normalizedSpec.AutoEnqueueOnReady,
297			Status:             createdTaskStatus(normalizedSpec),
298			ApprovalPolicy:     normalizedSpec.ApprovalPolicy,
299			ApprovalState:      defaultApprovalStateForPolicy(normalizedSpec.ApprovalPolicy),
300			Owner:              cloneOwnership(normalizedSpec.Owner),
301			CreatedBy:          actor.Actor,
302			Origin:             actor.Origin,
303			CreatedAt:          now,
304			UpdatedAt:          now,
305			Metadata:           cloneRawJSON(normalizedSpec.Metadata),
306		}
307		if strings.TrimSpace(record.ID) == "" {
308			record.ID = m.newID("task")
309		}
310		if err := record.Validate(); err != nil {
311			return nil, err
312		}
313		if err := m.store.CreateTask(ctx, record); err != nil {
314			return nil, err
315		}
316		if err := m.recordTaskEvent(ctx, record.ID, "", taskEventCreated, actor, createdTaskPayload{
317			Scope:          record.Scope,
318			WorkspaceID:    record.WorkspaceID,
319			ParentTaskID:   record.ParentTaskID,
320			Status:         record.Status,
321			NetworkChannel: record.NetworkChannel,
322			Owner:          cloneOwnership(record.Owner),
323		}); err != nil {
324			return nil, err
325		}
326	
327		return &record, nil
328	}
