361	// DeleteTask removes one task after verifying it is not still in use by child
362	// tasks or non-terminal runs, then reconciles any dependents unblocked by the
363	// cascade-deleted dependency edges.
364	func (m *Service) DeleteTask(ctx context.Context, id string, actor ActorContext) error {
365		if err := requireWriteAuthority(actor); err != nil {
366			return err
367		}
368	
369		trimmedID := strings.TrimSpace(id)
370		if trimmedID == "" {
371			return fmt.Errorf("%w: task id is required", ErrValidation)
372		}
373	
374		if txStore, ok := m.store.(DeleteTaskTransactionStore); ok {
375			return txStore.WithDeleteTaskTransaction(ctx, func(store DeleteTaskMutationStore) error {
376				return m.deleteTaskWithStore(ctx, store, trimmedID)
377			})
378		}
379	
380		return m.deleteTaskWithStore(ctx, m.store, trimmedID)
381	}
382	
383	func (m *Service) deleteTaskWithStore(
384		ctx context.Context,
385		store DeleteTaskMutationStore,
386		trimmedID string,
387	) error {
388		record, err := store.GetTask(ctx, trimmedID)
389		if err != nil {
390			return fmt.Errorf("task: load task %q for delete: %w", trimmedID, err)
391		}
392		if err := m.ensureTaskDeleteAllowedWithStore(ctx, store, record); err != nil {
393			return err
394		}
395	
396		dependents, err := store.ListDependents(ctx, trimmedID)
397		if err != nil {
398			return fmt.Errorf("task: list dependents for task %q delete: %w", trimmedID, err)
399		}
400		dependentIDs := uniqueDependentTaskIDs(dependents)
401	
402		if err := store.DeleteTask(ctx, trimmedID); err != nil {
403			return fmt.Errorf("task: delete task %q: %w", trimmedID, err)
404		}
405	
406		for _, dependentID := range dependentIDs {
407			if _, err := m.reconcileTaskCascadeWithStore(ctx, store, dependentID); err != nil {
408				return fmt.Errorf(
409					"task: reconcile dependent task %q after deleting %q: %w",
410					dependentID,
411					trimmedID,
412					err,
413				)
414			}
415		}
416	
417		return nil
418	}
