420	// UpdateTask applies one mutable patch while preserving immutable identity and
421	// structural fields under manager control.
422	func (m *Service) UpdateTask(ctx context.Context, id string, patch Patch, actor ActorContext) (*Task, error) {
423		if err := requireWriteAuthority(actor); err != nil {
424			return nil, err
425		}
426	
427		trimmedID := strings.TrimSpace(id)
428		if trimmedID == "" {
429			return nil, fmt.Errorf("%w: task id is required", ErrValidation)
430		}
431		normalizedPatch, err := normalizeTaskPatch(patch)
432		if err != nil {
433			return nil, err
434		}
435		if normalizedPatch.NetworkChannel != nil {
436			if err := m.validateNetworkChannel("task_patch.network_channel", *normalizedPatch.NetworkChannel); err != nil {
437				return nil, err
438			}
439		}
440	
441		current, err := m.store.GetTask(ctx, trimmedID)
442		if err != nil {
443			return nil, err
444		}
445	
446		updated, changedFields := applyTaskPatch(current, normalizedPatch)
447		if len(changedFields) == 0 {
448			return &current, nil
449		}
450	
451		dependencies, err := m.store.ListDependencies(ctx, trimmedID)
452		if err != nil {
453			return nil, err
454		}
455		runs, err := m.store.ListTaskRuns(ctx, RunQuery{TaskID: trimmedID})
456		if err != nil {
457			return nil, err
458		}
459	
460		canonicalStatus, err := m.canonicalTaskStatus(ctx, updated, dependencies, runs)
461		if err != nil {
462			return nil, err
463		}
464		updated.Status = canonicalStatus
465		updated.UpdatedAt = m.now().UTC()
466		if err := m.store.UpdateTask(ctx, updated); err != nil {
467			return nil, err
468		}
469		if err := m.recordTaskEvent(ctx, updated.ID, "", taskEventUpdated, actor, updatedTaskPayload{
470			ChangedFields: append([]string(nil), changedFields...),
471			Status:        updated.Status,
472		}); err != nil {
473			return nil, err
474		}
475	
476		return &updated, nil
477	}
