479	// CancelTask propagates manager-owned cancellation through the target task,
480	// affected runs, and all non-terminal descendants.
481	func (m *Service) CancelTask(ctx context.Context, id string, req CancelTask, actor ActorContext) (*Task, error) {
482		if err := requireWriteAuthority(actor); err != nil {
483			return nil, err
484		}
485	
486		trimmedID := strings.TrimSpace(id)
487		if trimmedID == "" {
488			return nil, fmt.Errorf("%w: task id is required", ErrValidation)
489		}
490		normalizedReq, err := normalizeCancelTask(req)
491		if err != nil {
492			return nil, err
493		}
494	
495		tree, root, err := m.loadCancellationTree(ctx, trimmedID)
496		if err != nil {
497			return nil, err
498		}
499		if err := m.ensureTaskCancelable(ctx, root); err != nil {
500			return nil, err
501		}
502	
503		cancelledRoot := root
504		for idx, record := range tree {
505			record, err = m.cancelTaskTreeRecord(ctx, trimmedID, idx, record, normalizedReq, actor)
506			if err != nil {
507				return nil, err
508			}
509			if record.ID == trimmedID {
510				cancelledRoot = record
511			}
512		}
513	
514		return &cancelledRoot, nil
515	}
516	
517	func applyTaskPatch(current Task, patch Patch) (Task, []string) {
518		updated := current
519		changedFields := make([]string, 0, len(MutableTaskFields()))
520	
521		if patch.Title != nil && updated.Title != *patch.Title {
522			updated.Title = *patch.Title
523			changedFields = append(changedFields, TaskFieldTitle)
524		}
525		if patch.Description != nil && updated.Description != *patch.Description {
526			updated.Description = *patch.Description
527			changedFields = append(changedFields, TaskFieldDescription)
528		}
529		if patch.Priority != nil && updated.Priority != *patch.Priority {
530			updated.Priority = *patch.Priority
531			changedFields = append(changedFields, TaskFieldPriority)
532		}
533		if patch.MaxAttempts != nil && updated.MaxAttempts != *patch.MaxAttempts {
534			updated.MaxAttempts = *patch.MaxAttempts
535			changedFields = append(changedFields, TaskFieldMaxAttempts)
536		}
537		if patch.AutoEnqueueOnReady != nil && updated.AutoEnqueueOnReady != *patch.AutoEnqueueOnReady {
538			updated.AutoEnqueueOnReady = *patch.AutoEnqueueOnReady
539			changedFields = append(changedFields, TaskFieldAutoEnqueueOnReady)
540		}
541		if patch.ApprovalPolicy != nil && updated.ApprovalPolicy != *patch.ApprovalPolicy {
542			updated.ApprovalPolicy = *patch.ApprovalPolicy
543			updated.ApprovalState = defaultApprovalStateForPolicy(*patch.ApprovalPolicy)
544			changedFields = append(changedFields, TaskFieldApprovalPolicy)
545		}
546		return applyTaskPatchReferences(updated, patch, changedFields)
547	}
548	
549	func applyTaskPatchReferences(updated Task, patch Patch, changedFields []string) (Task, []string) {
550		if patch.Metadata != nil && !sameRawJSON(updated.Metadata, *patch.Metadata) {
551			updated.Metadata = cloneRawJSON(*patch.Metadata)
552			changedFields = append(changedFields, TaskFieldMetadata)
553		}
554		if patch.NetworkChannel != nil && updated.NetworkChannel != *patch.NetworkChannel {
555			updated.NetworkChannel = *patch.NetworkChannel
556			changedFields = append(changedFields, TaskFieldNetworkChannel)
557		}
558		if patch.Owner != nil && !sameOwnership(updated.Owner, patch.Owner) {
559			updated.Owner = cloneOwnership(patch.Owner)
560			changedFields = append(changedFields, TaskFieldOwner)
561		}
562		if patch.ClearOwner && updated.Owner != nil {
563			updated.Owner = nil
564			changedFields = append(changedFields, TaskFieldOwner)
565		}
566	
567		return updated, changedFields
568	}
