577	func createdTaskStatus(spec CreateTask) Status {
578		if spec.Draft {
579			return TaskStatusDraft
580		}
581		if approvalStateBlocksExecution(
582			normalizeApprovalPolicyOrDefault(spec.ApprovalPolicy),
583			defaultApprovalStateForPolicy(spec.ApprovalPolicy),
584		) {
585			return TaskStatusBlocked
586		}
587		return TaskStatusReady
588	}
