628	func (m *Service) executeTaskBoundary(
629		ctx context.Context,
630		id string,
631		req ExecutionRequest,
632		action ExecutionAction,
633		actor ActorContext,
634	) (*Execution, error) {
635		if err := requireWriteAuthority(actor); err != nil {
636			return nil, err
637		}
638		trimmedID := strings.TrimSpace(id)
639		if trimmedID == "" {
640			return nil, fmt.Errorf("%w: task id is required", ErrValidation)
641		}
642		normalizedReq, err := normalizeTaskExecutionRequest(req)
643		if err != nil {
644			return nil, err
645		}
646		if err := m.validateNetworkChannel("task_execution.network_channel", normalizedReq.NetworkChannel); err != nil {
647			return nil, err
648		}
649		idempotencyKey := taskExecutionIdempotencyKey(trimmedID, action, normalizedReq.IdempotencyKey)
650		if existing, ok, err := m.taskExecutionFromIdempotency(ctx, trimmedID, idempotencyKey, action, actor); err != nil {
651			return nil, err
652		} else if ok {
653			return existing, nil
654		}
655	
656		switch action {
657		case ExecutionActionPublish:
658			if _, err := m.publishTaskIntent(ctx, trimmedID, actor); err != nil {
659				return nil, err
660			}
661		case ExecutionActionApproval:
662			if _, err := m.transitionTaskApproval(
663				ctx,
664				trimmedID,
665				ApprovalStateApproved,
666				taskEventApproved,
667				actor,
668			); err != nil {
669				return nil, err
670			}
671		case ExecutionActionStart:
672			taskRecord, err := m.store.GetTask(ctx, trimmedID)
673			if err != nil {
674				return nil, err
675			}
676			if err := m.ensureTaskExecutable(ctx, taskRecord); err != nil {
677				return nil, err
678			}
679		default:
680			return nil, fmt.Errorf("%w: unsupported task execution action %q", ErrValidation, action)
681		}
682	
683		run, err := m.EnqueueRun(ctx, EnqueueRun{
684			TaskID:         trimmedID,
685			IdempotencyKey: idempotencyKey,
686			NetworkChannel: normalizedReq.NetworkChannel,
687			Metadata:       normalizedReq.Metadata,
688		}, actor)
689		if err != nil {
690			return nil, err
691		}
692		taskRecord, err := m.store.GetTask(ctx, run.TaskID)
693		if err != nil {
694			return nil, err
695		}
696		return &Execution{
697			Task:   taskRecord,
698			Run:    *run,
699			Action: action,
700		}, nil
701	}
702	
703	func (m *Service) taskExecutionFromIdempotency(
704		ctx context.Context,
705		taskID string,
706		idempotencyKey string,
707		action ExecutionAction,
708		actor ActorContext,
709	) (*Execution, bool, error) {
710		run, err := m.store.GetTaskRunByIdempotencyKey(ctx, idempotencyKey, actor.Origin)
711		switch {
712		case errors.Is(err, ErrTaskRunIdempotencyNotFound):
713			return nil, false, nil
714		case err != nil:
715			return nil, false, err
716		}
717		if strings.TrimSpace(run.TaskID) != taskID {
718			return nil, false, fmt.Errorf(
719				"%w: idempotency key %q is already bound to task %q",
720				ErrValidation,
721				idempotencyKey,
722				run.TaskID,
723			)
724		}
725		taskRecord, err := m.store.GetTask(ctx, run.TaskID)
726		if err != nil {
727			return nil, false, err
728		}
729		return &Execution{
730			Task:        taskRecord,
731			Run:         run,
732			Action:      action,
733			ExistingRun: true,
734		}, true, nil
735	}
