963	func (m *Service) cancelTaskTreeRecord(
964		ctx context.Context,
965		rootTaskID string,
966		idx int,
967		record Task,
968		req CancelTask,
969		actor ActorContext,
970	) (Task, error) {
971		runs, status, err := m.loadTaskRuntimeState(ctx, record)
972		if err != nil {
973			return Task{}, err
974		}
975		record.Status = status
976		if idx > 0 && isTerminalTaskStatus(status) {
977			return record, nil
978		}
979	
980		propagatedFromTaskID := cancellationPropagationRoot(rootTaskID, idx)
981		cancelledRunIDs, err := m.cancelOpenTaskRuns(ctx, record, runs, req, actor, propagatedFromTaskID)
982		if err != nil {
983			return Task{}, err
984		}
985		if status.Normalize() == TaskStatusCanceled && len(cancelledRunIDs) == 0 {
986			return record, nil
987		}
988		return m.persistCancelledTask(ctx, record, req, actor, propagatedFromTaskID, cancelledRunIDs)
989	}
