1017	func (m *Service) cancelOpenTaskRuns(
1018		ctx context.Context,
1019		record Task,
1020		runs []Run,
1021		req CancelTask,
1022		actor ActorContext,
1023		propagatedFromTaskID string,
1024	) ([]string, error) {
1025		cancelledRunIDs := make([]string, 0)
1026		for _, run := range runs {
1027			if isTerminalRunStatus(run.Status) {
1028				continue
1029			}
1030			cancelledRun, err := m.cancelRunRecord(ctx, record, run, CancelRun(req), actor, cancelRunOptions{
1031				propagatedFromTaskID: propagatedFromTaskID,
1032				reconcileTask:        false,
1033			})
1034			if err != nil {
1035				return nil, err
1036			}
1037			cancelledRunIDs = append(cancelledRunIDs, cancelledRun.ID)
1038		}
1039		return cancelledRunIDs, nil
1040	}
