1072		ctx context.Context,
1073		taskRecord Task,
1074		run Run,
1075		actor ActorContext,
1076	) (Run, *Run, error) {
1077		if err := m.requireSessionExecutor("start run"); err != nil {
1078			return Run{}, nil, err
1079		}
1080	
1081		run.Status = TaskRunStatusStarting
1082		if err := m.store.UpdateTaskRun(ctx, run); err != nil {
1083			return Run{}, nil, err
1084		}
1085	
1086		lifecycleCtx := taskRunLifecycleContext(ctx)
1087		startingTask, err := m.reconcileTaskCascade(lifecycleCtx, run.TaskID)
1088		if err != nil {
1089			return Run{}, nil, err
1090		}
1091		if err := m.recordTaskEvent(lifecycleCtx, run.TaskID, run.ID, taskEventRunStarting, actor, runTransitionPayload{
1092			Status:     run.Status,
1093			TaskStatus: startingTask.Status,
1094			SessionID:  run.SessionID,
1095		}); err != nil {
1096			return Run{}, nil, err
1097		}
1098	
1099		sessionID, failedRun, err := m.startRunSession(lifecycleCtx, taskRecord, startingTask, run, actor)
1100		if err != nil {
1101			return Run{}, failedRun, err
1102		}
1103		run.SessionID = sessionID
1104		if err := m.store.UpdateTaskRun(lifecycleCtx, run); err != nil {
1105			stopErr := m.stopUnboundStartedTaskSession(lifecycleCtx, sessionID)
1106			return Run{}, nil, errorsJoin(err, stopErr)
1107		}
1108	
1109		boundTask, err := m.reconcileTaskCascade(lifecycleCtx, run.TaskID)
1110		if err != nil {
1111			return Run{}, nil, err
1112		}
1113		if err := m.recordTaskEvent(lifecycleCtx, run.TaskID, run.ID, taskEventRunSessionBound, actor, runTransitionPayload{
1114			Status:     run.Status,
1115			TaskStatus: boundTask.Status,
1116			SessionID:  run.SessionID,
1117		}); err != nil {
1118			return Run{}, nil, err
1119		}
1120		return run, nil, nil
1121	}
