1123	func (m *Service) startRunSession(
1124		ctx context.Context,
1125		taskRecord Task,
1126		startingTask Task,
1127		run Run,
1128		actor ActorContext,
1129	) (string, *Run, error) {
1130		profile, err := m.startTaskExecutionProfile(ctx, startingTask.ID)
1131		if err != nil {
1132			message := fmt.Sprintf("load execution profile: %v", err)
1133			failedRun, failErr := m.failRunAfterSessionStartError(ctx, taskRecord, run, actor, message)
1134			if failErr != nil {
1135				return "", nil, errorsJoin(err, failErr)
1136			}
1137			return "", failedRun, fmt.Errorf("task: load execution profile for run %q: %w", run.ID, err)
1138		}
1139		sessionRef, err := m.sessions.StartTaskSession(ctx, &StartTaskSession{
1140			Task:             startingTask,
1141			Run:              run,
1142			ExecutionProfile: &profile,
1143			Actor:            actor,
1144		})
1145		if err != nil {
1146			message := fmt.Sprintf("start task session: %v", err)
1147			failedRun, failErr := m.failRunAfterSessionStartError(ctx, taskRecord, run, actor, message)
1148			if failErr != nil {
1149				return "", nil, errorsJoin(err, failErr)
1150			}
1151			return "", failedRun, fmt.Errorf("task: start task session for run %q: %w", run.ID, err)
1152		}
1153		if sessionRef == nil {
1154			failedRun, failErr := m.failRunAfterSessionStartError(
1155				ctx,
1156				taskRecord,
1157				run,
1158				actor,
1159				"start task session: nil session reference",
1160			)
1161			if failErr != nil {
1162				return "", nil, failErr
1163			}
1164			return "", failedRun, fmt.Errorf("%w: start_task_session returned nil session reference", ErrValidation)
1165		}
1166		if err := sessionRef.Validate(); err != nil {
1167			message := fmt.Sprintf("start task session: %v", err)
1168			failedRun, failErr := m.failRunAfterSessionStartError(ctx, taskRecord, run, actor, message)
1169			if failErr != nil {
1170				return "", nil, errorsJoin(err, failErr)
1171			}
1172			return "", failedRun, err
1173		}
1174		return strings.TrimSpace(sessionRef.SessionID), nil, nil
1175	}
