279	func (o *networkTaskStatusObserver) designationRollup(
280		ctx context.Context,
281		event taskpkg.Event,
282		run taskpkg.Run,
283	) (taskDesignationRollupStatus, error) {
284		groupID := strings.TrimSpace(run.DesignationGroupID)
285		runs, err := o.tasks.ListTaskRuns(ctx, taskpkg.RunQuery{
286			TaskID:             strings.TrimSpace(run.TaskID),
287			DesignationGroupID: groupID,
288		})
289		if err != nil {
290			return taskDesignationRollupStatus{}, fmt.Errorf("list designated task runs: %w", err)
291		}
292		rollup := taskDesignationRollupStatus{
293			DesignationGroupID: groupID,
294			TaskID:             strings.TrimSpace(run.TaskID),
295			RunIDs:             make([]string, 0, len(runs)),
296			Statuses:           make(map[string]int),
297			UpdatedAt:          o.now().UTC().Format(time.RFC3339Nano),
298			LatestEvent:        strings.TrimSpace(event.EventType),
299			LatestEventID:      strings.TrimSpace(event.ID),
300		}
301		for _, item := range runs {
302			runID := strings.TrimSpace(item.ID)
303			if runID != "" {
304				rollup.RunIDs = append(rollup.RunIDs, runID)
305			}
306			status := item.Status.Normalize()
307			statusKey := string(status)
308			rollup.Statuses[statusKey]++
309			switch status {
310			case taskpkg.TaskRunStatusCompleted:
311				rollup.Completed++
312				rollup.TerminalCount++
313			case taskpkg.TaskRunStatusFailed:
314				rollup.Failed++
315				rollup.TerminalCount++
316			case taskpkg.TaskRunStatusCanceled:
317				rollup.Canceled++
318				rollup.TerminalCount++
319			case taskpkg.TaskRunStatusQueued:
320				rollup.Queued++
321			case taskpkg.TaskRunStatusNeedsAttention:
322				rollup.NeedsAttention++
323			default:
324				rollup.Running++
325			}
326		}
327		slices.Sort(rollup.RunIDs)
328		rollup.Total = len(rollup.RunIDs)
329		rollup.Complete = rollup.Total > 0 && rollup.TerminalCount == rollup.Total
330		return rollup, nil
331	}
