46	func (f *taskEventObserverFanout) OnTaskEvent(ctx context.Context, record taskpkg.EventRecord) {
47		if f == nil {
48			return
49		}
50		for _, observer := range f.observers {
51			if observer == nil {
52				continue
53			}
54			func(target taskpkg.EventObserver) {
55				defer func() {
56					if recovered := recover(); recovered != nil {
57						logger := f.logger
58						if logger == nil {
59							logger = slog.Default()
60						}
61						logger.Error(
62							"daemon: task event observer panicked during fanout",
63							"panic", recovered,
64							"event_id", record.Event.ID,
65							"task_id", record.Event.TaskID,
66							"run_id", record.Event.RunID,
67							"event_type", record.Event.EventType,
68						)
69					}
70				}()
71				target.OnTaskEvent(ctx, record)
72			}(observer)
73		}
