134	func newBridgeTerminalTaskNotificationObserver(
135		subscriptions bridgepkg.BridgeTaskSubscriptionStore,
136		taskEvents bridgepkg.TerminalTaskEventReader,
137		instances bridgepkg.BridgeInstanceReader,
138		cursors notifications.CursorStore,
139		transport bridgepkg.DeliveryTransport,
140		presets notificationPresetDispatcher,
141		logger *slog.Logger,
142		now func() time.Time,
143		timeout time.Duration,
