145		if taskEvents == nil || cursors == nil || transport == nil {
146			return nil
147		}
148		if timeout <= 0 {
149			timeout = 10 * time.Second
150		}
151		ctx, cancel := context.WithCancel(context.Background())
152		observer := &bridgeTerminalTaskNotificationObserver{
153			logger:  logger,
154			timeout: timeout,
155			tasks:   taskEvents,
156			ctx:     ctx,
157			cancel:  cancel,
158			pending: make(map[string]struct{}),
159			queue: make(
