161				defaultBridgeTerminalNotificationQueueSize,
162			),
163		}
164		if subscriptions != nil && instances != nil {
165			observer.notifier = bridgepkg.NewTerminalTaskNotifier(bridgepkg.TerminalTaskNotifierConfig{
