215	func (o *bridgeTerminalTaskNotificationObserver) start() {
216		if o == nil {
217			return
218		}
219		o.wg.Go(func() {
220			for {
221				select {
222				case <-o.ctx.Done():
223					return
224				case wake := <-o.queue:
225					o.processWake(wake)
226				}
227			}
228		})
