231	func (o *bridgeTerminalTaskNotificationObserver) enqueue(record taskpkg.EventRecord) {
232		if o == nil {
233			return
234		}
235		wake := bridgeTerminalTaskNotificationWake{
236			taskID:    strings.TrimSpace(record.Event.TaskID),
237			eventID:   strings.TrimSpace(record.Event.ID),
238			runID:     strings.TrimSpace(record.Event.RunID),
239			eventType: strings.TrimSpace(record.Event.EventType),
240			record:    record,
241		}
242		if wake.taskID == "" {
243			return
244		}
245		wake.pendingKey = wake.taskID
246		if o.presets != nil {
247			wake.pendingKey = wake.eventID
248			if wake.pendingKey == "" {
249				wake.pendingKey = strings.Join([]string{wake.taskID, wake.runID, wake.eventType}, ":")
250			}
251		}
252		if wake.pendingKey == "" {
253			return
254		}
255		o.mu.Lock()
256		if _, exists := o.pending[wake.pendingKey]; exists {
257			o.mu.Unlock()
258			return
259		}
260		o.pending[wake.pendingKey] = struct{}{}
261		o.backlog = append(o.backlog, wake)
262		o.mu.Unlock()
263		o.drainQueue()
264	}
265	
266	func (o *bridgeTerminalTaskNotificationObserver) drainQueue() {
267		if o == nil {
268			return
269		}
270		for {
271			o.mu.Lock()
272			if len(o.backlog) == 0 {
273				o.mu.Unlock()
274				return
275			}
276			wake := o.backlog[0]
277			select {
278			case o.queue <- wake:
279				o.backlog = o.backlog[1:]
280				o.mu.Unlock()
281			default:
282				o.mu.Unlock()
283				return
284			}
285		}
286	}
