288	func (o *bridgeTerminalTaskNotificationObserver) processWake(
289		wake bridgeTerminalTaskNotificationWake,
290	) {
291		defer func() {
292			o.mu.Lock()
293			delete(o.pending, wake.pendingKey)
294			o.mu.Unlock()
295			o.drainQueue()
296		}()
297	
298		notifyCtx := context.Background()
299		cancel := func() {}
300		if o.timeout > 0 {
301			notifyCtx, cancel = context.WithTimeout(notifyCtx, o.timeout)
302		}
303		defer cancel()
304	
305		if o.notifier != nil && isBridgeTerminalNotificationWake(wake.eventType) {
306			o.processTerminalWake(notifyCtx, wake)
307		}
308		if o.presets != nil {
309			o.processPresetWake(notifyCtx, wake)
310		}
311	}
