318			ctx,
319			bridgepkg.BridgeTaskSubscriptionQuery{TaskID: wake.taskID},
320		)
321		if err != nil {
322			o.logTerminalWakeFailure(wake, sweep, err)
323			return
324		}
325		if sweep.Delivered > 0 || sweep.Suppressed > 0 || sweep.Deferred > 0 || sweep.Failed > 0 {
326			o.logTerminalWakeSuccess(wake, sweep)
327		}
328	}
