462	func isBridgeTerminalNotificationWake(eventType string) bool {
463		switch strings.TrimSpace(eventType) {
464		case harnessTaskEventRunCompleted,
465			"task.run_failed",
466			"task.run_canceled",
467			"task.run_review_approved",
468			"task.canceled":
469			return true
470		default:
471			return false
472		}
473	}
