137		}
138		if c.SpawnFailureLimit <= 0 {
139			return fmt.Errorf("%s.spawn_failure_limit must be positive: %d", path, c.SpawnFailureLimit)
140		}
141		if c.SchedulerBadTickThreshold <= 0 {
142			return fmt.Errorf(
143				"%s.scheduler_bad_tick_threshold must be positive: %d",
144				path,
145				c.SchedulerBadTickThreshold,
146			)
147		}
148		if err := validateWholeSecondDuration(
149			path+".scheduler_bad_tick_cooldown",
150			c.SchedulerBadTickCooldown,
151			false,
152		); err != nil {
153			return err
154		}
155		if err := validateWholeSecondDuration(path+".default_max_runtime", c.DefaultMaxRuntime, true); err != nil {
156			return err
157		}
158		if c.DefaultMaxRuntime > MaxTaskOrchestrationRuntime {
159			return fmt.Errorf(
160				"%s.default_max_runtime must be <= %s: %s",
161				path,
162				MaxTaskOrchestrationRuntime,
163				c.DefaultMaxRuntime,
164			)
165		}
166		if err := validateWholeSecondDuration(
167			path+".bridge_notification_timeout",
168			c.BridgeNotificationTimeout,
169			false,
170		); err != nil {
171			return err
172		}
173		if c.DesignatedRunMax <= 0 || c.DesignatedRunMax > 5 {
174			return fmt.Errorf("%s.designated_run_max must be between 1 and 5: %d", path, c.DesignatedRunMax)
175		}
176		if err := c.Profile.Validate(path + ".profile"); err != nil {
177			return err
178		}
