218		case TaskReviewPolicyNone, TaskReviewPolicyOnSuccess, TaskReviewPolicyOnFailure, TaskReviewPolicyAlways:
219		default:
220			return fmt.Errorf("%s.default_policy is invalid: %q", path, c.DefaultPolicy)
221		}
222		if c.MaxRounds <= 0 {
223			return fmt.Errorf("%s.max_rounds must be positive: %d", path, c.MaxRounds)
224		}
225		if c.MaxReviewAttempts <= 0 {
226			return fmt.Errorf("%s.max_review_attempts must be positive: %d", path, c.MaxReviewAttempts)
227		}
228		if err := validateWholeSecondDuration(path+".timeout", c.Timeout, false); err != nil {
229			return err
230		}
231		if err := validateWholeSecondDuration(path+".rapid_terminal_window", c.RapidTerminalWindow, false); err != nil {
232			return err
233		}
234		if c.RapidTerminalLimit <= 0 {
235			return fmt.Errorf("%s.rapid_terminal_limit must be positive: %d", path, c.RapidTerminalLimit)
236		}
237		if c.MissingWorkMaxItems <= 0 {
238			return fmt.Errorf("%s.missing_work_max_items must be positive: %d", path, c.MissingWorkMaxItems)
239		}
240		if c.MissingWorkItemMaxBytes <= 0 {
241			return fmt.Errorf("%s.missing_work_item_max_bytes must be positive: %d", path, c.MissingWorkItemMaxBytes)
242		}
243		if c.ReasonMaxBytes <= 0 {
244			return fmt.Errorf("%s.reason_max_bytes must be positive: %d", path, c.ReasonMaxBytes)
245		}
246		if c.ReviewTextMaxBytes <= 0 {
247			return fmt.Errorf("%s.review_text_max_bytes must be positive: %d", path, c.ReviewTextMaxBytes)
248		}
249		if c.NextRoundGuidanceMaxBytes <= 0 {
250			return fmt.Errorf("%s.next_round_guidance_max_bytes must be positive: %d", path, c.NextRoundGuidanceMaxBytes)
251		}
252		switch c.FailurePolicy {
253		case TaskReviewFailureBlockTask, TaskReviewFailureFailTask:
254		default:
255			return fmt.Errorf("%s.failure_policy is invalid: %q", path, c.FailurePolicy)
256		}
257		return nil
258	}
259	
260	func validateWholeSecondDuration(path string, value time.Duration, allowZero bool) error {
261		if value < 0 {
262			return fmt.Errorf("%s must be >= 0: %s", path, value)
263		}
264		if value == 0 {
265			if allowZero {
266				return nil
267			}
268			return fmt.Errorf("%s must be positive: %s", path, value)
269		}
270		if value%time.Second != 0 {
271			return fmt.Errorf("%s must use whole-second precision: %s", path, value)
272		}
273		return nil
274	}
