2946		if len(input.Designations) == 0 {
2947			return toolspkg.ToolResult{}, nativeRequiredInputError(req.ToolID, "designations")
2948		}
2949		if len(input.Designations) > maxDesignations {
2950			return toolspkg.ToolResult{}, nativeNetworkInputError(
2951				req.ToolID,
2952				fmt.Errorf("designations cannot exceed %d", maxDesignations),
2953			)
2954		}
2955		actor, err := actorContextFromScope(scope)
2956		if err != nil {
2957			return toolspkg.ToolResult{}, err
2958		}
2959		groupID := store.NewID("tdg")
2960		runs := make([]taskpkg.Run, 0, len(input.Designations))
