2992	func nativeNetworkThreadPromotionDigest(
2993		messages []store.NetworkConversationMessage,
2994		originMessageID string,
2995	) (string, []string, bool) {
2996		target := strings.TrimSpace(originMessageID)
2997		sourceIDs := make([]string, 0, len(messages))
2998		var builder strings.Builder
2999		found := false
3000		for _, message := range messages {
3001			messageID := strings.TrimSpace(message.MessageID)
3002			if messageID == "" {
3003				continue
3004			}
3005			sourceIDs = append(sourceIDs, messageID)
3006			if messageID == target {
3007				found = true
3008			}
3009			line := nativeNetworkThreadPromotionMessageLine(message)
3010			if line == "" {
3011				continue
3012			}
3013			if builder.Len() > 0 {
3014				builder.WriteByte('\n')
3015			}
3016			builder.WriteString(line)
3017			if builder.Len() >= 4000 {
3018				break
3019			}
3020		}
3021		digest := strings.TrimSpace(builder.String())
3022		if len(digest) > 4000 {
3023			digest = strings.TrimSpace(digest[:4000])
3024		}
3025		return digest, sourceIDs, found
3026	}
