3028	func nativeNetworkThreadPromotionMessageLine(message store.NetworkConversationMessage) string {
3029		preview := strings.TrimSpace(message.PreviewText)
3030		if preview == "" {
3031			preview = strings.TrimSpace(message.Text)
3032		}
3033		if preview == "" {
3034			return ""
3035		}
3036		peer := firstNonEmpty(strings.TrimSpace(message.PeerFrom), strings.TrimSpace(message.SessionID), "unknown")
3037		return peer + ": " + preview
3038	}
