516	func sortNetworkPeerPayloads(peers []contract.NetworkPeerPayload) {
517		sort.Slice(peers, func(i int, j int) bool {
518			if peers[i].Local != peers[j].Local {
519				return peers[i].Local
520			}
521	
522			left := networkPeerSortTimestamp(peers[i])
523			right := networkPeerSortTimestamp(peers[j])
524			switch {
525			case left != nil && right != nil && !left.Equal(*right):
526				return left.After(*right)
527			case left != nil && right == nil:
528				return true
529			case left == nil && right != nil:
530				return false
531			}
532	
533			leftName := networkPeerSortName(peers[i])
534			rightName := networkPeerSortName(peers[j])
535			if leftName != rightName {
536				return leftName < rightName
537			}
538			if peers[i].PeerID != peers[j].PeerID {
539				return peers[i].PeerID < peers[j].PeerID
540			}
541			return peers[i].Channel < peers[j].Channel
542		})
543	}
