169	func (h *BaseHandlers) networkThreadPromotionSource(
170		ctx context.Context,
171		workspaceID string,
172		channel string,
173		threadID string,
174		originMessageID string,
175	) (networkThreadPromotionSource, error) {
176		ref := store.NetworkConversationRef{
177			WorkspaceID: workspaceID,
178			Channel:     channel,
179			Surface:     store.NetworkSurfaceThread,
180			ThreadID:    threadID,
181		}
182		messages, err := h.NetworkStore.ListConversationMessages(
183			ctx,
184			ref,
185			store.NetworkConversationMessageQuery{Limit: 200},
186		)
187		if err != nil {
188			return networkThreadPromotionSource{}, err
189		}
190		digest, sourceMessageIDs, found := networkThreadPromotionDigest(messages, originMessageID)
191		if !found {
192			return networkThreadPromotionSource{}, NewNetworkValidationError(
193				fmt.Errorf("origin_message_id %q is not part of thread %q", originMessageID, threadID),
194			)
195		}
196		channelRef := store.NetworkChannelRef{WorkspaceID: workspaceID, Channel: channel}
197		thread, err := h.NetworkStore.GetThread(ctx, channelRef, threadID)
198		if err != nil {
199			return networkThreadPromotionSource{}, err
200		}
201		return networkThreadPromotionSource{
202			workspaceID:      workspaceID,
203			channel:          channel,
204			threadID:         threadID,
205			originMessageID:  originMessageID,
206			digest:           digest,
207			sourceMessageIDs: sourceMessageIDs,
208			thread:           thread,
209		}, nil
210	}
