497	// ResolveNetworkDirectRoom creates or returns a deterministic two-party direct room.
498	func (h *BaseHandlers) ResolveNetworkDirectRoom(c *gin.Context) {
499		service, ok := h.requireNetworkReadDependencies(c)
500		if !ok {
501			return
502		}
503		channel, err := normalizeNetworkChannel(c.Param("channel"))
504		if err != nil {
505			h.respondError(c, StatusForNetworkError(err), err)
506			return
507		}
508		scope, ok := h.resolveWorkspaceScope(c)
509		if !ok {
510			return
511		}
512	
513		var req contract.NetworkDirectResolveRequest
514		if err := c.ShouldBindJSON(&req); err != nil {
515			h.respondError(
516				c,
517				http.StatusBadRequest,
518				fmt.Errorf("%s: decode network direct resolve request: %w", h.transportName(), err),
519			)
520			return
521		}
522		sessionID := strings.TrimSpace(req.SessionID)
523		peerID := strings.TrimSpace(req.PeerID)
524		if sessionID == "" {
525			h.respondError(c, http.StatusBadRequest, NewNetworkValidationError(errors.New("session_id is required")))
526			return
527		}
528		if err := network.ValidatePeerID(peerID); err != nil {
529			h.respondError(c, http.StatusBadRequest, NewNetworkValidationError(err))
530			return
531		}
532	
533		localPeer, remotePeer, err := h.resolveDirectRoomPeers(
534			c.Request.Context(),
535			service,
536			scope.NetworkWorkspaceID(),
537			channel,
538			sessionID,
539			peerID,
540		)
541		if err != nil {
542			h.respondError(c, StatusForNetworkError(err), err)
543			return
544		}
545		networkWorkspaceID := scope.NetworkWorkspaceID()
546		directID, peerA, peerB, err := network.DirectRoomIdentity(
547			networkWorkspaceID,
548			channel,
549			localPeer.PeerID,
550			remotePeer.PeerID,
551		)
552		if err != nil {
553			h.respondError(c, StatusForNetworkError(err), err)
554			return
555		}
556		now := h.nowUTC()
557		direct, err := h.NetworkStore.ResolveDirectRoom(c.Request.Context(), store.NetworkDirectRoomEntry{
558			WorkspaceID:    networkWorkspaceID,
559			Channel:        channel,
560			DirectID:       directID,
561			PeerA:          peerA,
562			PeerB:          peerB,
563			OpenedAt:       now,
564			LastActivityAt: now,
565		})
566		if err != nil {
567			h.respondError(c, StatusForNetworkError(err), err)
568			return
569		}
570		c.JSON(http.StatusOK, contract.NetworkDirectRoomResponse{
571			Direct: NetworkDirectRoomPayloadFromStore(direct),
572		})
573	}
