690	func (h *BaseHandlers) resolveDirectRoomPeers(
691		ctx context.Context,
692		service NetworkService,
693		workspaceID string,
694		channel string,
695		sessionID string,
696		peerID string,
697	) (network.PeerInfo, network.PeerInfo, error) {
698		peers, err := service.ListPeers(ctx, workspaceID, channel)
699		if err != nil {
700			return network.PeerInfo{}, network.PeerInfo{}, err
701		}
702		var local network.PeerInfo
703		localFound := false
704		remote, remoteFound := findPeerInfo(peers, peerID)
705		for _, peer := range peers {
706			if peer.SessionID == nil || strings.TrimSpace(*peer.SessionID) != sessionID {
707				continue
708			}
709			if !peer.Local {
710				continue
711			}
712			local = peer
713			localFound = true
714			break
715		}
716		if !localFound {
717			return network.PeerInfo{}, network.PeerInfo{}, fmt.Errorf(
718				"%w: session=%q channel=%q",
719				network.ErrLocalPeerNotFound,
720				sessionID,
721				channel,
722			)
723		}
724		if !remoteFound {
725			return network.PeerInfo{}, network.PeerInfo{}, fmt.Errorf(
726				"%w: peer_id=%q channel=%q",
727				network.ErrTargetPeerNotFound,
728				peerID,
729				channel,
730			)
731		}
732		return local, remote, nil
733	}
