784	func networkThreadPromotionDigest(
785		messages []store.NetworkConversationMessage,
786		originMessageID string,
787	) (string, []string, bool) {
788		target := strings.TrimSpace(originMessageID)
789		sourceIDs := make([]string, 0, len(messages))
790		var builder strings.Builder
791		found := false
792		for _, message := range messages {
793			messageID := strings.TrimSpace(message.MessageID)
794			if messageID == "" {
795				continue
796			}
797			sourceIDs = append(sourceIDs, messageID)
798			if messageID == target {
799				found = true
800			}
801			line := networkThreadPromotionMessageLine(message)
802			if line == "" {
803				continue
804			}
805			if builder.Len() > 0 {
806				builder.WriteByte('\n')
807			}
808			builder.WriteString(line)
809			if builder.Len() >= 4000 {
810				break
811			}
812		}
813		digest := strings.TrimSpace(builder.String())
814		if len(digest) > 4000 {
815			digest = strings.TrimSpace(digest[:4000])
816		}
817		return digest, sourceIDs, found
818	}
819	
820	func networkThreadPromotionMessageLine(message store.NetworkConversationMessage) string {
821		preview := strings.TrimSpace(message.PreviewText)
822		if preview == "" {
823			preview = strings.TrimSpace(message.Text)
824		}
825		if preview == "" {
826			return ""
827		}
828		peer := firstNonEmpty(strings.TrimSpace(message.PeerFrom), strings.TrimSpace(message.SessionID), "unknown")
829		return peer + ": " + preview
830	}
