438			return
439		}
440		messages, err := h.loadVisiblePeerMessages(c.Request.Context(), networkStore, query)
441		if err != nil {
442			h.respondNetworkMessageError(c, err)
443			return
444		}
445	
446		sessionByID := sessionInfoMapByID(sessions)
447		peerByID := peerInfoMapByID(peers)
448		payload, err := networkTimelinePayloads(
449			messages,
450			sessionByID,
451			peerByID,
452			query,
453			h.networkPresenceWindow(),
454		)
455		if err != nil {
456			h.respondNetworkMessageError(c, err)
457			return
458		}
459	
460		c.JSON(http.StatusOK, contract.NetworkPeerMessagesResponse{Messages: payload})
461	}
