518	func (h *BaseHandlers) resolveCreateNetworkChannelRequest(
519		ctx context.Context,
520		req contract.CreateNetworkChannelRequest,
521		resolved *workspacepkg.ResolvedWorkspace,
522	) (string, string, []string, error) {
523		_ = ctx
524		if resolved == nil {
525			return "", "", nil, NewNetworkValidationError(
526				errors.New("workspace is required"),
527			)
528		}
529		channel, err := normalizeNetworkChannel(req.Channel)
530		if err != nil {
531			return "", "", nil, err
532		}
533		purpose, err := normalizeNetworkChannelPurpose(req.Purpose)
534		if err != nil {
535			return "", "", nil, err
536		}
537	
538		workspaceID := strings.TrimSpace(resolved.ID)
539		if workspaceID == "" {
540			return "", "", nil, NewNetworkValidationError(
541				errors.New("workspace_id is required"),
542			)
543		}
544	
545		agentNames, err := normalizeNetworkAgentNames(req.AgentNames)
546		if err != nil {
547			return "", "", nil, err
548		}
549		available := make(map[string]struct{}, len(resolved.Agents))
550		for _, agent := range resolved.Agents {
551			available[strings.TrimSpace(agent.Name)] = struct{}{}
552		}
553		for _, agentName := range agentNames {
554			if _, ok := available[agentName]; ok {
555				continue
556			}
557			return "", "", nil, fmt.Errorf(
558				"%w: %s",
559				workspacepkg.ErrAgentNotAvailable,
560				agentName,
561			)
562		}
563	
564		return channel, purpose, agentNames, nil
565	}
