568		trimmed := strings.TrimSpace(channel)
569		if trimmed == "" {
570			return "", NewNetworkValidationError(errors.New("channel is required"))
571		}
572		if err := network.ValidateChannel(trimmed); err != nil {
573			return "", err
574		}
