578	func normalizeNetworkAgentNames(agentNames []string) ([]string, error) {
579		if len(agentNames) == 0 {
580			return nil, NewNetworkValidationError(errors.New("agent_names is required"))
581		}
582	
583		normalized := make([]string, 0, len(agentNames))
584		seen := make(map[string]struct{}, len(agentNames))
585		for _, raw := range agentNames {
586			name := strings.TrimSpace(raw)
587			if name == "" {
588				return nil, NewNetworkValidationError(errors.New("agent_names entries are required"))
589			}
590			if _, ok := seen[name]; ok {
591				return nil, NewNetworkValidationError(fmt.Errorf("agent_names contains duplicate entry %q", name))
592			}
593			seen[name] = struct{}{}
594			normalized = append(normalized, name)
595		}
596		return normalized, nil
597	}
