651	// networkChannelAggregates merges live peers with persisted channel/session/message state for one projection pass.
652	func networkChannelAggregates(
653		ctx context.Context,
654		service NetworkService,
655		sessionsManager SessionManager,
656		networkStore NetworkStore,
657		workspaceID string,
658	) (map[string]*networkChannelAggregate, error) {
659		if service == nil {
660			return nil, errors.New("api: network service is required")
661		}
662		if networkStore == nil {
663			return nil, errors.New("api: network store is required")
664		}
665		if sessionsManager == nil {
666			return nil, errors.New("api: sessions are required")
667		}
668		trimmedWorkspaceID := strings.TrimSpace(workspaceID)
669		if trimmedWorkspaceID == "" {
670			return nil, errors.New("api: network workspace_id is required")
671		}
672		runtimePeers, err := service.ListPeers(ctx, trimmedWorkspaceID, "")
673		if err != nil {
674			return nil, fmt.Errorf("api: list network peers: %w", err)
675		}
676		sessions, err := sessionsManager.ListAll(ctx)
677		if err != nil {
678			return nil, fmt.Errorf("api: list sessions: %w", err)
679		}
680		channelMetadata, err := networkStore.ListNetworkChannels(
681			ctx,
682			store.NetworkChannelQuery{WorkspaceID: trimmedWorkspaceID},
683		)
684		if err != nil {
685			return nil, fmt.Errorf("api: list network channels: %w", err)
686		}
687		messages, err := networkStore.ListNetworkMessages(ctx, store.NetworkMessageQuery{WorkspaceID: trimmedWorkspaceID})
688		if err != nil {
689			return nil, fmt.Errorf("api: list network messages: %w", err)
690		}
691	
692		aggregates := make(map[string]*networkChannelAggregate)
693		applyNetworkChannelMetadata(aggregates, trimmedWorkspaceID, channelMetadata)
694		applyNetworkChannelSessions(aggregates, trimmedWorkspaceID, sessions)
695		applyNetworkChannelPeers(aggregates, runtimePeers)
696		applyNetworkChannelMessages(aggregates, messages)
697		return aggregates, nil
698	}
699	
700	func sortedNetworkChannelPayloads(
701		aggregates map[string]*networkChannelAggregate,
702	) []contract.NetworkChannelPayload {
703		channels := make([]contract.NetworkChannelPayload, 0, len(aggregates))
704		for _, aggregate := range aggregates {
705			if aggregate == nil {
706				continue
707			}
708			channels = append(channels, networkChannelPayloadFromAggregate(aggregate))
709		}
710		sort.Slice(channels, func(i int, j int) bool {
711			left := networkChannelSortTimestamp(channels[i])
712			right := networkChannelSortTimestamp(channels[j])
713			switch {
714			case left != nil && right != nil && !left.Equal(*right):
715				return left.After(*right)
716			case left != nil && right == nil:
717				return true
718			case left == nil && right != nil:
719				return false
720			case channels[i].MessageCount != channels[j].MessageCount:
721				return channels[i].MessageCount > channels[j].MessageCount
722			default:
723				return channels[i].Channel < channels[j].Channel
724			}
725		})
726		return channels
727	}
728	
729	func networkChannelSortTimestamp(channel contract.NetworkChannelPayload) *time.Time {
730		switch {
731		case channel.LastActivityAt == nil:
732			return channel.LastPresenceAt
733		case channel.LastPresenceAt == nil:
734			return channel.LastActivityAt
735		case channel.LastPresenceAt.After(*channel.LastActivityAt):
736			return channel.LastPresenceAt
737		default:
738			return channel.LastActivityAt
739		}
740	}
741	
742	func applyNetworkChannelMetadata(
743		aggregates map[string]*networkChannelAggregate,
744		workspaceID string,
745		metadataEntries []store.NetworkChannelEntry,
746	) {
747		for _, metadata := range metadataEntries {
748			metadataCopy := metadata
749			aggregate := ensureNetworkChannelAggregate(aggregates, workspaceID, metadata.Channel)
750			aggregate.metadata = &metadataCopy
751		}
752	}
753	
754	func applyNetworkChannelSessions(
755		aggregates map[string]*networkChannelAggregate,
756		workspaceID string,
757		sessions []*session.Info,
758	) {
759		for _, info := range sessions {
760			if !networkChannelSessionVisible(info) || strings.TrimSpace(info.WorkspaceID) != workspaceID {
761				continue
762			}
763			aggregate := ensureNetworkChannelAggregate(aggregates, workspaceID, info.Channel)
764			aggregate.sessionCount++
765		}
766	}
767	
768	func applyNetworkChannelPeers(
769		aggregates map[string]*networkChannelAggregate,
770		peers []network.PeerInfo,
771	) {
772		for _, peer := range peers {
773			aggregate := ensureNetworkChannelAggregate(aggregates, peer.WorkspaceID, peer.Channel)
774			aggregate.peerCount++
775			if peer.Local {
776				aggregate.localPeerCount++
777				continue
778			}
779			aggregate.remotePeerCount++
780		}
781	}
782	
783	func applyNetworkChannelMessages(
784		aggregates map[string]*networkChannelAggregate,
785		messages []store.NetworkMessageEntry,
786	) {
787		for _, message := range messages {
788			aggregate := ensureNetworkChannelAggregate(aggregates, message.WorkspaceID, message.Channel)
789			aggregate.recordHistoricalParticipant(message.PeerFrom)
790			aggregate.recordHistoricalParticipant(message.PeerTo)
791			for _, peerID := range message.Mentions {
792				aggregate.recordHistoricalParticipant(peerID)
793			}
794			if !isPublicChannelTimelineMessage(message) {
795				continue
796			}
797			if isPresenceMessage(message) {
798				aggregate.presenceCount++
799				aggregate.lastPresenceAt = laterTimePtr(aggregate.lastPresenceAt, message.Timestamp)
800				continue
801			}
802			aggregate.messageCount++
803			aggregate.lastActivityAt = laterTimePtr(aggregate.lastActivityAt, message.Timestamp)
804			aggregate.lastMessageAt = laterTimePtr(aggregate.lastMessageAt, message.Timestamp)
805			if preview := networkMessagePreview(message); preview != "" && aggregateMessageIsLatest(aggregate, message) {
806				aggregate.lastMessagePreview = preview
807			}
808		}
809	}
810	
811	func (a *networkChannelAggregate) recordHistoricalParticipant(peerID string) {
812		if a == nil {
813			return
814		}
815		trimmed := strings.TrimSpace(peerID)
816		if trimmed == "" {
817			return
818		}
819		if a.historicalParticipants == nil {
820			a.historicalParticipants = make(map[string]struct{})
821		}
822		if _, exists := a.historicalParticipants[trimmed]; exists {
823			return
824		}
825		a.historicalParticipants[trimmed] = struct{}{}
826		a.historicalParticipantCount = len(a.historicalParticipants)
827	}
828	
829	func aggregateMessageIsLatest(
830		aggregate *networkChannelAggregate,
831		message store.NetworkMessageEntry,
832	) bool {
833		return aggregate != nil &&
834			aggregate.lastMessageAt != nil &&
835			message.Timestamp.Equal(aggregate.lastMessageAt.UTC())
836	}
