838	func statusForCreateNetworkChannelError(err error) int {
839		switch {
840		case errors.Is(err, workspacepkg.ErrWorkspaceNotFound),
841			errors.Is(err, workspacepkg.ErrWorkspaceRootMissing):
842			return StatusForWorkspaceError(err)
843		case errors.Is(err, workspacepkg.ErrAgentNotAvailable):
844			return StatusForSessionError(err)
845		case errors.Is(err, network.ErrInvalidField):
846			return StatusForNetworkError(err)
847		default:
848			return http.StatusBadRequest
849		}
850	}
