852	func (h *BaseHandlers) createNetworkChannelSessions(
853		ctx context.Context,
854		channel string,
855		workspaceID string,
856		agentNames []string,
857	) ([]string, error) {
858		createdIDs := make([]string, 0, len(agentNames))
859		for _, agentName := range agentNames {
860			sess, err := h.Sessions.Create(ctx, session.CreateOpts{
861				AgentName: agentName,
862				Provider:  "",
863				Workspace: workspaceID,
864				Channel:   channel,
865				Type:      session.SessionTypeUser,
866			})
867			if err != nil {
868				if rollbackErr := rollbackCreatedNetworkSessions(ctx, h.Sessions, createdIDs); rollbackErr != nil {
869					err = errors.Join(err, rollbackErr)
870				}
871				return nil, err
872			}
873			if sess != nil && sess.Info() != nil {
874				createdIDs = append(createdIDs, sess.Info().ID)
875			}
876		}
877		return createdIDs, nil
878	}
