940	func (h *BaseHandlers) networkChannelDetailPayload(
941		ctx context.Context,
942		service NetworkService,
943		workspaceID string,
944		channel string,
945	) (contract.NetworkChannelDetailPayload, error) {
946		networkStore, err := h.networkStoreRequired()
947		if err != nil {
948			return contract.NetworkChannelDetailPayload{}, err
949		}
950		trimmedWorkspaceID := strings.TrimSpace(workspaceID)
951		if trimmedWorkspaceID == "" {
952			return contract.NetworkChannelDetailPayload{}, errors.New("api: network workspace_id is required")
953		}
954		peers, err := service.ListPeers(ctx, trimmedWorkspaceID, channel)
955		if err != nil {
956			return contract.NetworkChannelDetailPayload{}, err
957		}
958		sessions, err := h.Sessions.ListAll(ctx)
959		if err != nil {
960			return contract.NetworkChannelDetailPayload{}, err
961		}
962	
963		filteredSessions := sessionsForChannel(sessions, trimmedWorkspaceID, channel)
964		metadata, err := h.loadNetworkChannelMetadata(ctx, networkStore, store.NetworkChannelRef{
965			WorkspaceID: trimmedWorkspaceID,
966			Channel:     channel,
967		})
968		if err != nil {
969			return contract.NetworkChannelDetailPayload{}, err
970		}
971		messages, err := networkStore.ListNetworkMessages(ctx, store.NetworkMessageQuery{
972			WorkspaceID: trimmedWorkspaceID,
973			Channel:     channel,
974		})
975		if err != nil {
976			return contract.NetworkChannelDetailPayload{}, err
977		}
978		history := summarizeNetworkMessageHistory(filterPublicChannelTimelineMessages(messages), h.networkPresenceWindow())
979		messageCount := len(history.conversation)
980		if len(filteredSessions) == 0 && len(peers) == 0 && len(messages) == 0 && metadata == nil {
981			return contract.NetworkChannelDetailPayload{}, fmt.Errorf("%w: %s", errNetworkChannelNotFound, channel)
982		}
983	
984		payloadPeers, localPeerCount := networkChannelPeerPayloads(peers, filteredSessions)
985	
986		metadataFields := networkChannelMetadataPayloadFields(metadata)
987		var (
988			lastActivityAt     *time.Time
989			lastPresenceAt     *time.Time
990			lastMessagePreview string
991		)
992		kindCounts := summarizeNetworkChannelKindCounts(history.conversation)
993		if messageCount > 0 {
994			lastActivityAt = laterTimePtr(lastActivityAt, history.conversation[messageCount-1].Timestamp)
995			lastMessagePreview = networkMessagePreview(history.conversation[messageCount-1])
996		}
997		lastPresenceAt = cloneTimePtr(history.lastPresenceAt)
998	
999		return contract.NetworkChannelDetailPayload{
1000			Channel:                    channel,
1001			WorkspaceID:                firstNonEmpty(metadataFields.workspaceID, trimmedWorkspaceID),
1002			Purpose:                    metadataFields.purpose,
1003			FanoutPolicy:               metadataFields.fanoutPolicy,
1004			CoordinatorPeerID:          metadataFields.coordinatorPeerID,
1005			CreatedBy:                  metadataFields.createdBy,
1006			CreatedAt:                  metadataFields.createdAt,
1007			PeerCount:                  len(peers),
1008			LocalPeerCount:             localPeerCount,
1009			RemotePeerCount:            len(peers) - localPeerCount,
1010			SessionCount:               len(filteredSessions),
1011			MessageCount:               messageCount,
1012			PresenceCount:              history.presenceCount,
1013			HistoricalParticipantCount: summarizeHistoricalParticipantCount(messages),
1014			LastActivityAt:             cloneTimePtr(lastActivityAt),
1015			LastPresenceAt:             lastPresenceAt,
1016			LastMessagePreview:         lastMessagePreview,
1017			KindCounts:                 kindCounts,
1018			Sessions:                   SessionPayloadsFromInfos(filteredSessions),
1019			Peers:                      payloadPeers,
1020		}, nil
1021	}
