1023	func networkChannelPeerPayloads(
1024		peers []network.PeerInfo,
1025		sessions []*session.Info,
1026	) ([]contract.NetworkPeerPayload, int) {
1027		sessionByID := sessionInfoMapByID(sessions)
1028		payloads := make([]contract.NetworkPeerPayload, 0, len(peers))
1029		localPeerCount := 0
1030		for _, peer := range peers {
1031			if peer.Local {
1032				localPeerCount++
1033			}
1034			payloads = append(payloads, networkPeerPayloadFromInfoWithSessions(peer, sessionByID))
1035		}
1036		sortNetworkPeerPayloads(payloads)
1037		return payloads, localPeerCount
1038	}
