1410	func summarizeNetworkMessageHistory(
1411		messages []store.NetworkMessageEntry,
1412		presenceWindow time.Duration,
1413	) networkMessageHistorySummary {
1414		summary := networkMessageHistorySummary{
1415			conversation:     make([]store.NetworkMessageEntry, 0, len(messages)),
1416			presenceEpisodes: make([]networkTimelineMessageView, 0),
1417		}
1418		if len(messages) == 0 {
1419			return summary
1420		}
1421	
1422		participants := make(map[string]struct{})
1423		openEpisodes := make(map[networkPresenceEpisodeKey]int)
1424	
1425		for _, message := range messages {
1426			recordHistoricalParticipant(participants, message.PeerFrom)
1427			recordHistoricalParticipant(participants, message.PeerTo)
1428			for _, peerID := range message.Mentions {
1429				recordHistoricalParticipant(participants, peerID)
1430			}
1431			if isPresenceMessage(message) {
1432				summary.presenceCount++
1433				summary.lastPresenceAt = laterTimePtr(summary.lastPresenceAt, message.Timestamp)
1434				key := networkPresenceEpisodeKeyForMessage(message)
1435				if index, ok := openEpisodes[key]; ok &&
1436					canExtendPresenceEpisode(summary.presenceEpisodes[index], message, presenceWindow) {
1437					extendPresenceEpisode(&summary.presenceEpisodes[index], message)
1438					continue
1439				}
1440				currentEpisode := networkTimelineMessageView{
1441					entry: cloneNetworkMessageEntry(message),
1442				}
1443				startedAt := message.Timestamp.UTC()
1444				lastSeenAt := message.Timestamp.UTC()
1445				currentEpisode.presenceCount = 1
1446				currentEpisode.presenceStartedAt = &startedAt
1447				currentEpisode.presenceLastSeenAt = &lastSeenAt
1448				currentEpisode.entry.PreviewText = networkMessagePreview(currentEpisode.entry)
1449				summary.presenceEpisodes = append(summary.presenceEpisodes, currentEpisode)
1450				openEpisodes[key] = len(summary.presenceEpisodes) - 1
1451				continue
1452			}
1453	
1454			summary.conversation = append(summary.conversation, cloneNetworkMessageEntry(message))
1455		}
1456		summary.historicalParticipantCount = len(participants)
1457		return summary
1458	}
