345	func (m *Manager) resolveTaskPeerContext(
346		ctx context.Context,
347		ingress TaskIngressContext,
348		action string,
349	) (resolvedTaskPeerContext, error) {
350		if ctx == nil {
351			return resolvedTaskPeerContext{}, errors.New("network: task ingress context is required")
352		}
353		if m == nil {
354			return resolvedTaskPeerContext{}, errors.New("network: manager is required")
355		}
356		if err := ingress.Validate(); err != nil {
357			return resolvedTaskPeerContext{}, err
358		}
359		if m.tasks == nil {
360			return resolvedTaskPeerContext{}, m.rejectTaskIngress(ctx, ingress, action, ErrTaskIngressUnavailable, nil)
361		}
362		if m.peers == nil {
363			return resolvedTaskPeerContext{}, m.rejectTaskIngress(ctx, ingress, action, ErrTaskIngressPeerNotFound, nil)
364		}
365		ingress.WorkspaceID = strings.TrimSpace(ingress.WorkspaceID)
366		ingress.Channel = strings.TrimSpace(ingress.Channel)
367		ingress.PeerID = strings.TrimSpace(ingress.PeerID)
368	
369		peer, ok := m.peers.RemoteByPeer(ingress.WorkspaceID, ingress.Channel, ingress.PeerID, m.now().UTC())
370		if !ok {
371			return resolvedTaskPeerContext{}, m.rejectTaskIngress(ctx, ingress, action, ErrTaskIngressPeerNotFound, nil)
372		}
373		if !containsString(peer.PeerCard.Capabilities, networkTaskWriteCapability) {
374			return resolvedTaskPeerContext{}, m.rejectTaskIngress(ctx, ingress, action, ErrTaskIngressCapabilityDenied, nil)
375		}
376	
377		actor, err := taskpkg.DeriveNetworkPeerActorContext(
378			strings.TrimSpace(ingress.PeerID),
379			networkTaskOriginRef(ingress),
380		)
381		if err != nil {
382			return resolvedTaskPeerContext{}, m.rejectTaskIngress(ctx, ingress, action, err, nil)
383		}
384		return resolvedTaskPeerContext{
385			ingress: ingress,
386			peer:    peer,
387			actor:   actor,
388		}, nil
389	}
