529	func networkRunMetadataValues(ingress TaskIngressContext) (map[string]string, error) {
530		workID := strings.TrimSpace(ingress.WorkID)
531		if workID == "" {
532			return nil, fmt.Errorf("%w: network work_id is required", ErrMissingField)
533		}
534		values := map[string]string{
535			"network_workspace_id": strings.TrimSpace(ingress.WorkspaceID),
536			"network_work_id":      workID,
537			"network_message_id":   strings.TrimSpace(ingress.RequestID),
538			tasksNetworkChannelKey: strings.TrimSpace(ingress.Channel),
539			"network_surface":      strings.TrimSpace(string(ingress.Surface)),
540			"network_reply_to":     strings.TrimSpace(ingress.ReplyTo),
541			"network_trace_id":     strings.TrimSpace(ingress.TraceID),
542			"network_causation_id": strings.TrimSpace(ingress.CausationID),
543		}
544		switch ingress.Surface {
545		case SurfaceThread:
546			values["network_thread_id"] = strings.TrimSpace(ingress.ThreadID)
547		case SurfaceDirect:
548			values["network_direct_id"] = strings.TrimSpace(ingress.DirectID)
549		}
550		return values, nil
551	}
552	
553	func mergeTrustedNetworkMetadata(raw json.RawMessage, values map[string]string) (json.RawMessage, error) {
554		metadata := make(map[string]any)
555		if len(raw) > 0 && strings.TrimSpace(string(raw)) != "" {
556			if err := json.Unmarshal(raw, &metadata); err != nil {
557				return nil, fmt.Errorf("%w: task run metadata must be a JSON object: %w", ErrInvalidField, err)
558			}
559			if metadata == nil {
560				metadata = make(map[string]any)
561			}
562		}
563		for key, value := range values {
564			value = strings.TrimSpace(value)
565			if value == "" {
566				continue
567			}
568			if existing, ok := metadata[key]; ok {
569				existingValue, ok := existing.(string)
570				if !ok || strings.TrimSpace(existingValue) != value {
571					return nil, fmt.Errorf("%w: %s is server-derived network metadata", ErrInvalidField, key)
572				}
573			}
574			metadata[key] = value
575		}
576		if len(metadata) == 0 {
577			return nil, nil
578		}
579		payload, err := json.Marshal(metadata)
580		if err != nil {
581			return nil, fmt.Errorf("network: marshal task run metadata: %w", err)
582		}
583		return payload, nil
584	}
585	
586	func taskIngressReason(err error) string {
587		switch {
588		case err == nil:
589			return ""
590		case errors.Is(err, ErrTaskChannelMismatch):
591			return taskIngressReasonChannelMismatch
592		case errors.Is(err, ErrTaskChannelStale):
593			return taskIngressReasonStaleChannel
594		case errors.Is(err, ErrTaskIngressCapabilityDenied):
595			return tasksCapabilityDeniedKey
596		case errors.Is(err, ErrTaskIngressPeerNotFound):
597			return "peer_not_found"
598		case errors.Is(err, ErrTaskIngressUnavailable):
599			return "task_ingress_unavailable"
600		case errors.Is(err, taskpkg.ErrTaskNotFound):
601			return "task_not_found"
602		case errors.Is(err, taskpkg.ErrValidation):
603			return "validation_failed"
604		case errors.Is(err, taskpkg.ErrPermissionDenied):
605			return "permission_denied"
606		case errors.Is(err, taskpkg.ErrStaleNetworkChannel):
607			return taskIngressReasonStaleChannel
608		case errors.Is(err, ErrMissingField), errors.Is(err, ErrInvalidField):
609			return "invalid_request"
610		default:
611			return "task_ingress_failed"
612		}
613	}
