298	// ListAutonomyLeaseHandles returns internal-only lease handles for one session.
299	// Public task-run read projections keep claim_token masked.
300	func (g *GlobalDB) ListAutonomyLeaseHandles(
301		ctx context.Context,
302		sessionID string,
303	) (handles []taskpkg.AutonomyLeaseHandle, err error) {
304		if err := g.checkReady(ctx, "list autonomy lease handles"); err != nil {
305			return nil, err
306		}
307		trimmedSessionID := strings.TrimSpace(sessionID)
308		if trimmedSessionID == "" {
309			return nil, fmt.Errorf("%w: session_id is required", taskpkg.ErrValidation)
310		}
311	
312		rows, err := g.db.QueryContext(
313			ctx,
314			`SELECT tr.id, tr.task_id, COALESCE(t.workspace_id, ''), tr.status,
315			        COALESCE(tr.session_id, ''), tr.claimed_by_kind, tr.claimed_by_ref,
316			        COALESCE(tr.claim_token, ''), COALESCE(tr.claim_token_hash, ''),
317			        tr.lease_until, tr.heartbeat_at
318			   FROM task_runs tr
319			   JOIN tasks t ON t.id = tr.task_id
320			  WHERE tr.session_id = ?
321			    AND COALESCE(tr.claim_token_hash, '') <> ''
322			  ORDER BY COALESCE(tr.lease_until, '') DESC, tr.id ASC`,
323			trimmedSessionID,
324		)
325		if err != nil {
326			return nil, fmt.Errorf("store: list autonomy lease handles for session %q: %w", trimmedSessionID, err)
327		}
328		defer func() {
329			if closeErr := rows.Close(); closeErr != nil && err == nil {
330				err = fmt.Errorf("store: close autonomy lease handle rows: %w", closeErr)
331			}
332		}()
333	
334		handles = make([]taskpkg.AutonomyLeaseHandle, 0)
335		for rows.Next() {
336			handle, scanErr := scanAutonomyLeaseHandle(rows)
337			if scanErr != nil {
338				return nil, scanErr
339			}
340			handles = append(handles, handle)
341		}
342		if err := rows.Err(); err != nil {
343			return nil, fmt.Errorf("store: iterate autonomy lease handles: %w", err)
344		}
345		return handles, nil
346	}
