707	func (m *Manager) SendFromRuntimePeer(ctx context.Context, req RuntimeSendRequest) (string, error) {
708		if ctx == nil {
709			return "", errors.New("network: runtime send context is required")
710		}
711		if m == nil || m.router == nil {
712			return "", errors.New("network: manager router is required")
713		}
714		m.sweepExpiredRemotePeers(ctx, m.now())
715	
716		prepared, err := m.prepareRuntimeSend(req)
717		if err != nil {
718			return "", err
719		}
720		writeResult, wrote, err := m.writeConversationMessage(
721			ctx,
722			runtimePeerSessionID,
723			AuditDirectionSent,
724			prepared.Envelope,
725		)
726		if err != nil {
727			m.recordAuditRejected(ctx, runtimePeerSessionID, prepared.Envelope, conversationPersistenceReason(err))
728			return "", err
729		}
730		if wrote && writeResult.Duplicate {
731			m.logger.Info(
732				"network.runtime_message.send_duplicate",
733				networkLogFields(prepared.Envelope, "session_id", runtimePeerSessionID)...)
734			return prepared.ID, nil
735		}
736	
737		result, err := m.router.PublishPrepared(ctx, prepared)
738		if err != nil {
739			m.recordAuditRejected(ctx, runtimePeerSessionID, prepared.Envelope, "publish_failed")
740			return "", err
741		}
742		m.recordSentDelivery(ctx, runtimePeerSessionID, result.Envelope, wrote)
743		return result.ID, nil
744	}
