487	// respondToolError serializes stable tool errors without backend error text.
488	func (h *BaseHandlers) respondToolError(c *gin.Context, err error) {
489		status := StatusForToolError(err)
490		var toolErr *toolspkg.ToolError
491		payload := contract.ToolErrorPayload{
492			Code:    toolspkg.ErrorCodeBackendFailed,
493			Message: http.StatusText(status),
494		}
495		switch {
496		case errors.As(err, &toolErr):
497			payload.Code = toolErr.Code
498			payload.Message = safeToolErrorMessage(status, toolErr.Code)
499			payload.ToolID = toolErr.ToolID
500			payload.ReasonCodes = append([]toolspkg.ReasonCode(nil), toolErr.ReasonCodes...)
501			payload.Layer = toolErrorLayer(toolErr.ReasonCodes)
502		case err != nil:
503			payload.Code = toolErrorCodeForStatus(status)
504			payload.Message = safeToolErrorMessage(status, payload.Code)
505			if reason, ok := toolspkg.ReasonOf(err); ok {
506				payload.ReasonCodes = []toolspkg.ReasonCode{reason}
507				payload.Layer = toolErrorLayer(payload.ReasonCodes)
508			}
509		default:
510			payload.Code = toolErrorCodeForStatus(status)
511			payload.Message = http.StatusText(status)
512		}
513		if h.MaskInternalErrors && status >= http.StatusInternalServerError {
514			payload.Message = http.StatusText(status)
515		}
516		if strings.TrimSpace(payload.Message) == "" {
517			payload.Message = http.StatusText(status)
518		}
519		c.JSON(status, contract.ToolErrorResponse{Error: payload})
520	}
521	
522	// safeToolErrorMessage maps internal failures to client-safe contract messages.
523	func safeToolErrorMessage(status int, code toolspkg.ErrorCode) string {
524		switch code {
525		case toolspkg.ErrorCodeNotFound:
526			return "tool not found"
527		case toolspkg.ErrorCodeConflict:
528			return "tool conflict"
529		case toolspkg.ErrorCodeUnavailable:
530			return "tool unavailable"
531		case toolspkg.ErrorCodeDenied:
532			return "tool invocation denied"
533		case toolspkg.ErrorCodeApprovalRequired:
534			return "tool approval required"
535		case toolspkg.ErrorCodeInvalidInput:
536			return "invalid tool request"
537		case toolspkg.ErrorCodeResultTooLarge:
538			return "tool result too large"
539		case toolspkg.ErrorCodeCanceled:
540			return "tool call canceled"
541		case toolspkg.ErrorCodeTimedOut:
542			return "tool call timed out"
543		case toolspkg.ErrorCodeBackendFailed:
544			return "tool backend failed"
545		default:
546			message := http.StatusText(status)
547			if strings.TrimSpace(message) == "" {
548				return "tool request failed"
549			}
550			return message
551		}
552	}
553	
554	// toolErrorCodeForStatus keeps non-tool errors compatible with tool error payloads.
555	func toolErrorCodeForStatus(status int) toolspkg.ErrorCode {
556		switch status {
557		case http.StatusBadRequest:
558			return toolspkg.ErrorCodeInvalidInput
559		case http.StatusNotFound:
560			return toolspkg.ErrorCodeNotFound
561		case http.StatusForbidden:
562			return toolspkg.ErrorCodeDenied
563		case http.StatusAccepted:
564			return toolspkg.ErrorCodeApprovalRequired
565		case http.StatusConflict:
566			return toolspkg.ErrorCodeConflict
567		case http.StatusUnprocessableEntity:
568			return toolspkg.ErrorCodeUnavailable
569		default:
570			return toolspkg.ErrorCodeBackendFailed
571		}
572	}
573	
574	// toolErrorLayer groups registry reasons into stable transport-facing layers.
575	func toolErrorLayer(reasons []toolspkg.ReasonCode) string {
576		for _, reason := range reasons {
577			switch reason {
578			case toolspkg.ReasonSourceDisabled,
579				toolspkg.ReasonMCPAuthUnconfigured,
580				toolspkg.ReasonMCPAuthRequired,
581				toolspkg.ReasonMCPAuthExpired,
582				toolspkg.ReasonMCPAuthInvalid,
583				toolspkg.ReasonMCPAuthRefreshFailed:
584				return "source_policy"
585			case toolspkg.ReasonSessionDenied:
586				return "session_lineage"
587			case toolspkg.ReasonPolicyDenied, toolspkg.ReasonVisibilityDenied:
588				return "registry_policy"
589			case toolspkg.ReasonHookDenied:
590				return "hook"
591			case toolspkg.ReasonApprovalRequired,
592				toolspkg.ReasonApprovalUnreachable,
593				toolspkg.ReasonApprovalTimedOut,
594				toolspkg.ReasonApprovalCanceled,
595				toolspkg.ReasonApprovalTokenMissing,
596				toolspkg.ReasonApprovalTokenExpired,
597				toolspkg.ReasonApprovalTokenMismatch,
598				toolspkg.ReasonApprovalTokenReplayed:
599				return "approval"
600			case toolspkg.ReasonBackendUnhealthy,
601				toolspkg.ReasonBackendNotExecutable,
602				toolspkg.ReasonConflictedID,
603				toolspkg.ReasonConflictedSanitizedName:
604				return "availability"
605			}
606		}
607		return ""
608	}
