19	func (s *Service) BundleForActiveLease(
20		ctx context.Context,
21		req taskpkg.ContextRequest,
22	) (taskpkg.ContextBundle, error) {
23		if err := checkContext(ctx); err != nil {
24			return taskpkg.ContextBundle{}, err
25		}
26		store := s.taskStoreValue()
27		if store == nil {
28			return taskpkg.ContextBundle{}, nil
29		}
30		sessionID := strings.TrimSpace(req.SessionID)
31		if sessionID == "" {
32			return taskpkg.ContextBundle{}, fmt.Errorf("%w: session_id is required", taskpkg.ErrPermissionDenied)
33		}
34		run, ok, err := s.activeRunForSession(ctx, sessionID)
35		if err != nil || !ok {
36			return taskpkg.ContextBundle{}, err
37		}
38		if runID := strings.TrimSpace(req.RunID); runID != "" && runID != strings.TrimSpace(run.ID) {
39			return taskpkg.ContextBundle{}, fmt.Errorf(
40				"%w: run %q is not owned by session %q",
41				taskpkg.ErrPermissionDenied,
42				runID,
43				sessionID,
44			)
45		}
46		taskRecord, err := store.GetTask(ctx, run.TaskID)
47		if err != nil {
48			return taskpkg.ContextBundle{}, err
49		}
50		workspaceSnapshot, err := s.resolveWorkspace(ctx, taskRecord.WorkspaceID, "", nil)
51		if err != nil {
52			return taskpkg.ContextBundle{}, err
53		}
54		return s.bundleForRun(ctx, taskRecord, run, workspaceSnapshot, nil)
55	}
