57	func (s *Service) BundleForOperatorTask(
58		ctx context.Context,
59		req taskpkg.OperatorTaskContextRequest,
60	) (taskpkg.ContextBundle, error) {
61		if err := checkContext(ctx); err != nil {
62			return taskpkg.ContextBundle{}, err
63		}
64		store := s.taskStoreValue()
65		if store == nil {
66			return taskpkg.ContextBundle{}, nil
67		}
68		taskID := strings.TrimSpace(req.TaskID)
69		if taskID == "" {
70			return taskpkg.ContextBundle{}, fmt.Errorf("%w: task_id is required", taskpkg.ErrValidation)
71		}
72		taskRecord, err := store.GetTask(ctx, taskID)
73		if err != nil {
74			return taskpkg.ContextBundle{}, err
75		}
76		workspaceSnapshot, err := s.resolveWorkspace(ctx, taskRecord.WorkspaceID, "", nil)
77		if err != nil {
78			return taskpkg.ContextBundle{}, err
79		}
80		runs, err := store.ListTaskRuns(ctx, taskpkg.RunQuery{TaskID: taskID})
