244	func (s *Service) priorRunSummaries(
245		ctx context.Context,
246		taskRecord taskpkg.Task,
247		current taskpkg.Run,
248		limit int,
249	) ([]taskpkg.RunSummary, error) {
250		if limit <= 0 {
251			return []taskpkg.RunSummary{}, nil
252		}
253		store := s.taskStoreValue()
254		if store == nil {
255			return []taskpkg.RunSummary{}, nil
256		}
257		runs, err := store.ListTaskRuns(ctx, taskpkg.RunQuery{TaskID: taskRecord.ID})
258		if err != nil {
259			return nil, err
260		}
261		prior := make([]taskpkg.Run, 0, len(runs))
262		for _, run := range runs {
263			if strings.TrimSpace(run.ID) == strings.TrimSpace(current.ID) {
264				continue
265			}
266			if run.Attempt > 0 && current.Attempt > 0 && run.Attempt >= current.Attempt {
267				continue
268			}
269			prior = append(prior, run)
270		}
271		sortRunsByAttemptAndActivity(prior)
272		summaries := make([]taskpkg.RunSummary, 0, min(len(prior), limit))
273		for _, run := range prior {
274			if len(summaries) == limit {
275				break
276			}
277			summaries = append(summaries, runSummaryFromTaskRun(run, taskRecord.MaxAttempts))
278		}
279		return summaries, nil
280	}
