301		}
302		runs, err := store.ListTaskRuns(ctx, taskpkg.RunQuery{TaskID: taskRecord.ID})
303		if err != nil {
304			return nil, err
305		}
306		runsByID := make(map[string]taskpkg.Run, len(runs))
307		for _, run := range runs {
308			runsByID[strings.TrimSpace(run.ID)] = run
