323			items = append(items, taskpkg.TimelineItem{
324				Sequence:  record.Sequence,
325				EventID:   strings.TrimSpace(event.ID),
326				Task:      taskReference(taskRecord),
327				Run:       runSummary,
328				EventType: strings.TrimSpace(event.EventType),
329				Actor:     event.Actor,
330				Origin:    event.Origin,
331				Payload:   redactedPayload,
