565	func boundedMissingWork(raw json.RawMessage, maxItems int, maxItemBytes int) ([]string, error) {
566		if len(raw) == 0 {
567			return []string{}, nil
568		}
569		var values []string
570		if err := json.Unmarshal(raw, &values); err != nil {
571			return nil, fmt.Errorf("situation: decode review missing work: %w", err)
572		}
573		if maxItems <= 0 || len(values) < maxItems {
574			maxItems = len(values)
575		}
576		result := make([]string, 0, maxItems)
577		for _, value := range values {
578			if len(result) == maxItems {
579				break
580			}
581			trimmed := safeTaskContextText(value, maxItemBytes)
582			if trimmed != "" {
583				result = append(result, trimmed)
584			}
585		}
586		return result, nil
587	}
