600	func selectTaskContextRun(taskRecord taskpkg.Task, runs []taskpkg.Run) (taskpkg.Run, bool) {
601		currentRunID := strings.TrimSpace(taskRecord.CurrentRunID)
602		if currentRunID != "" {
