	payload := fanOutDesignationMetadataPayload{
		Designation: fanOutDesignationMetadataDetail{Index: index, Brief: brief},
		Metadata:    metadata,
	}
	encoded, err := json.Marshal(payload)
	if err != nil {
		return nil, fmt.Errorf("task fan-out metadata: %w", err)
	}
	return encoded, nil
