414	func (s *Service) enforceTaskContextBudget(
415		bundle taskpkg.ContextBundle,
416		maxBytes int,
417	) (taskpkg.ContextBundle, error) {
418		if maxBytes <= 0 {
419			return taskpkg.NormalizeContextBundle(bundle), nil
420		}
421		bundle = taskpkg.NormalizeContextBundle(bundle)
422		for {
423			over, err := taskContextOverBudget(bundle, maxBytes)
424			if err != nil {
425				return taskpkg.ContextBundle{}, err
426			}
427			if !over {
428				return bundle, nil
429			}
430			switch {
431			case len(bundle.RecentEvents) > 0:
432				bundle.RecentEvents = bundle.RecentEvents[1:]
433			case len(bundle.PriorAttempts) > 0:
434				bundle.PriorAttempts = bundle.PriorAttempts[:len(bundle.PriorAttempts)-1]
435			case len(bundle.ReviewHistory) > 0:
436				bundle.ReviewHistory = bundle.ReviewHistory[:len(bundle.ReviewHistory)-1]
437			case strings.TrimSpace(bundle.HandoffSummary) != "":
438				bundle.HandoffSummary = truncateUTF8Bytes(bundle.HandoffSummary, len(bundle.HandoffSummary)/2)
439			case bundle.ReviewContinuation != nil && strings.TrimSpace(bundle.ReviewContinuation.NextRoundGuidance) != "":
440				continuation := *bundle.ReviewContinuation
441				continuation.NextRoundGuidance = truncateUTF8Bytes(
442					continuation.NextRoundGuidance,
443					len(continuation.NextRoundGuidance)/2,
444				)
445				bundle.ReviewContinuation = &continuation
446			default:
447				return taskpkg.ContextBundle{}, fmt.Errorf(
448					"%w: task context bundle exceeds %d bytes after trimming",
449					taskpkg.ErrPayloadTooLarge,
450					maxBytes,
451				)
452			}
453		}
454	}
