600	func selectTaskContextRun(taskRecord taskpkg.Task, runs []taskpkg.Run) (taskpkg.Run, bool) {
601		currentRunID := strings.TrimSpace(taskRecord.CurrentRunID)
602		if currentRunID != "" {
603			for _, run := range runs {
604				if strings.TrimSpace(run.ID) == currentRunID {
605					return run, true
606				}
607			}
608		}
609		if run, ok := selectActiveRun(runs); ok {
610			return run, true
611		}
612		if len(runs) == 0 {
613			return taskpkg.Run{}, false
614		}
615		sorted := append([]taskpkg.Run(nil), runs...)
616		sortRunsByAttemptAndActivity(sorted)
617		return sorted[0], true
618	}
