620	func sortRunsByAttemptAndActivity(runs []taskpkg.Run) {
621		slices.SortStableFunc(runs, func(left, right taskpkg.Run) int {
622			if left.Attempt != right.Attempt {
623				return right.Attempt - left.Attempt
624			}
625			leftTime := runActivityTime(left)
626			rightTime := runActivityTime(right)
627			if !leftTime.Equal(rightTime) {
628				if leftTime.After(rightTime) {
629					return -1
630				}
631				return 1
632			}
633			return strings.Compare(left.ID, right.ID)
634		})
635	}
