660	func redactTaskContextJSONValue(value any) any {
661		switch typed := value.(type) {
662		case map[string]any:
663			cleaned := make(map[string]any, len(typed))
664			for key, nested := range typed {
665				if isSensitiveTaskContextKey(key) {
666					continue
667				}
668				cleaned[key] = redactTaskContextJSONValue(nested)
669			}
670			return cleaned
671		case []any:
672			cleaned := make([]any, len(typed))
673			for idx, nested := range typed {
674				cleaned[idx] = redactTaskContextJSONValue(nested)
675			}
676			return cleaned
677		case string:
678			return taskpkg.RedactClaimTokens(typed)
679		default:
680			return value
681		}
682	}
683	
684	func isSensitiveTaskContextKey(key string) bool {
685		normalized := strings.ToLower(strings.TrimSpace(key))
686		if normalized == "" {
687			return false
688		}
689		switch normalized {
690		case "claim_token", "mcp_auth_token", "oauth_code", "pkce_verifier", "secret_binding", "secret_bindings":
691			return true
692		}
693		return strings.HasPrefix(normalized, "agh_claim_") || strings.HasSuffix(normalized, "_secret")
694	}
695	
696	func safeTaskContextText(value string, limit int) string {
697		return truncateUTF8Bytes(taskpkg.RedactClaimTokens(singleLine(value)), limit)
698	}
699	
700	func truncateUTF8Bytes(value string, limit int) string {
701		if limit <= 0 {
702			return ""
703		}
704		if len(value) <= limit {
705			return value
706		}
707		if limit <= len("...") {
708			return strings.Repeat(".", limit)
709		}
710		cut := limit - len("...")
711		for cut > 0 && !utf8.ValidString(value[:cut]) {
712			cut--
713		}
714		return strings.TrimSpace(value[:cut]) + "..."
715	}
