14	// ComposedAssembler assembles selected startup prompt sections around the base
15	// agent prompt.
16	type ComposedAssembler struct {
17		selector    *SectionSelector
18		descriptors []PromptSectionDescriptor
19	}
20	
21	// ComposedAssemblerOption customizes the prompt section chain for a
22	// ComposedAssembler.
23	type ComposedAssemblerOption func(*ComposedAssembler)
24	
25	type startupPromptSectionProvider interface {
26		PromptStartupSection(
27			ctx context.Context,
28			startup session.StartupPromptContext,
29			agent aghconfig.AgentDef,
