42	var (
43		_ session.PromptAssembler        = (*ComposedAssembler)(nil)
44		_ session.StartupPromptAssembler = (*ComposedAssembler)(nil)
45	)
46	
47	// NewComposedAssembler constructs a ComposedAssembler from startup section
48	// descriptors.
49	func NewComposedAssembler(opts ...ComposedAssemblerOption) *ComposedAssembler {
50		assembler := &ComposedAssembler{}
51		for _, opt := range opts {
52			if opt == nil {
53				continue
54			}
55			opt(assembler)
56		}
57		return assembler
58	}
59	
60	// WithSectionSelector installs the daemon-owned startup section selector.
61	func WithSectionSelector(selector *SectionSelector) ComposedAssemblerOption {
62		return func(assembler *ComposedAssembler) {
63			if assembler == nil {
64				return
65			}
66			assembler.selector = selector
67		}
68	}
69	
70	// WithPromptSectionDescriptors appends explicit startup prompt section
71	// descriptors to the assembler.
72	func WithPromptSectionDescriptors(descriptors ...PromptSectionDescriptor) ComposedAssemblerOption {
73		copied := append([]PromptSectionDescriptor(nil), descriptors...)
74		return func(assembler *ComposedAssembler) {
75			if assembler == nil || len(copied) == 0 {
76				return
77			}
78			assembler.descriptors = append(assembler.descriptors, copied...)
79		}
80	}
81	
82	// WithPrependPromptProviders preserves the legacy prepend provider option by
83	// wrapping providers in explicit prepend descriptors.
84	func WithPrependPromptProviders(providers ...session.PromptProvider) ComposedAssemblerOption {
85		copied := append([]session.PromptProvider(nil), providers...)
86		return func(assembler *ComposedAssembler) {
87			if assembler == nil || len(copied) == 0 {
88				return
89			}
90			baseOrder := len(assembler.descriptors) * 10
91			for idx, provider := range copied {
92				if provider == nil {
93					continue
94				}
95				assembler.descriptors = append(assembler.descriptors, PromptSectionDescriptor{
96					Name:     fmt.Sprintf("legacy-prepend-%d", baseOrder+idx),
97					Position: PromptSectionPositionPrepend,
98					Order:    baseOrder + idx,
99					Provider: provider,
100				})
101			}
102		}
103	}
104	
105	// WithAppendPromptProviders preserves the legacy append provider option by
106	// wrapping providers in explicit append descriptors.
107	func WithAppendPromptProviders(providers ...session.PromptProvider) ComposedAssemblerOption {
108		copied := append([]session.PromptProvider(nil), providers...)
109		return func(assembler *ComposedAssembler) {
110			if assembler == nil || len(copied) == 0 {
111				return
112			}
113			baseOrder := len(assembler.descriptors) * 10
114			for idx, provider := range copied {
115				if provider == nil {
116					continue
117				}
118				assembler.descriptors = append(assembler.descriptors, PromptSectionDescriptor{
119					Name:     fmt.Sprintf("legacy-append-%d", baseOrder+idx),
120					Position: PromptSectionPositionAppend,
121					Order:    baseOrder + idx,
122					Provider: provider,
123				})
124			}
