128	// Assemble renders the selected startup sections using a baseline startup
129	// context for callers that only know about the legacy assembler seam.
130	func (a *ComposedAssembler) Assemble(
131		ctx context.Context,
132		agent aghconfig.AgentDef,
133		workspace *workspacepkg.ResolvedWorkspace,
134	) (string, error) {
135		return a.AssembleStartup(ctx, session.StartupPromptContext{
136			AgentName:   strings.TrimSpace(agent.Name),
137			SessionType: session.SessionTypeUser,
138		}, agent, workspace)
139	}
140	
141	// AssembleStartup renders eligible prepend sections, the trimmed base prompt,
142	// and eligible append sections into one composed startup system prompt.
143	func (a *ComposedAssembler) AssembleStartup(
144		ctx context.Context,
145		startup session.StartupPromptContext,
146		agent aghconfig.AgentDef,
147		workspace *workspacepkg.ResolvedWorkspace,
148	) (string, error) {
149		basePrompt := strings.TrimSpace(agent.Prompt)
150		if a == nil {
151			return basePrompt, nil
152		}
153	
154		selected, err := a.selectDescriptors(startup)
155		if err != nil {
156			return "", err
157		}
158	
159		prependSections, appendSections, err := gatherPromptSections(ctx, startup, agent, workspace, selected)
160		if err != nil {
161			return "", err
162		}
163	
164		sections := make([]string, 0, len(prependSections)+len(appendSections)+1)
165		sections = append(sections, prependSections...)
166		if basePrompt != "" {
167			sections = append(sections, basePrompt)
168		}
169		sections = append(sections, appendSections...)
170	
171		return strings.Join(sections, "\n\n"), nil
172	}
173	
174	func (a *ComposedAssembler) selectDescriptors(
175		startup session.StartupPromptContext,
176	) ([]PromptSectionDescriptor, error) {
177		if len(a.descriptors) == 0 {
178			return nil, nil
179		}
180		if err := validatePromptSectionDescriptors(a.descriptors); err != nil {
181			return nil, err
182		}
183		if a.selector == nil {
184			return filterPromptDescriptorsForStartup(normalizeAndSortPromptSectionDescriptors(a.descriptors), startup), nil
185		}
186		selected, _, err := a.selector.Select(startup, a.descriptors)
187		return selected, err
188	}
189	
190	func filterPromptDescriptorsForStartup(
191		descriptors []PromptSectionDescriptor,
192		startup session.StartupPromptContext,
193	) []PromptSectionDescriptor {
194		if len(descriptors) == 0 {
195			return nil
196		}
197		filtered := make([]PromptSectionDescriptor, 0, len(descriptors))
198		for _, descriptor := range descriptors {
199			if descriptor.StartupPredicate != nil && !descriptor.StartupPredicate(startup) {
200				continue
201			}
202			filtered = append(filtered, descriptor)
203		}
204		return filtered
205	}
206	
207	func gatherPromptSections(
208		ctx context.Context,
209		startup session.StartupPromptContext,
210		agent aghconfig.AgentDef,
211		workspace *workspacepkg.ResolvedWorkspace,
212		descriptors []PromptSectionDescriptor,
213	) ([]string, []string, error) {
214		prependSections := make([]string, 0, len(descriptors))
215		appendSections := make([]string, 0, len(descriptors))
216	
217		for _, descriptor := range descriptors {
218			if descriptor.Provider == nil {
219				continue
220			}
221	
222			section, err := promptSection(ctx, descriptor.Provider, startup, agent, workspace)
223			if err != nil {
224				return nil, nil, fmt.Errorf(
225					"daemon: %s prompt section %q: %w",
226					descriptor.Position,
227					descriptor.Name,
228					err,
229				)
230			}
231	
232			section = applyPromptSectionBudget(strings.TrimSpace(section), descriptor)
233			if section == "" {
234				continue
235			}
236	
237			switch descriptor.Position {
238			case PromptSectionPositionPrepend:
239				prependSections = append(prependSections, section)
240			case PromptSectionPositionAppend:
241				appendSections = append(appendSections, section)
242			default:
243				return nil, nil, fmt.Errorf(
244					"daemon: invalid prompt section position %q for %q",
245					descriptor.Position,
246					descriptor.Name,
247				)
248			}
249		}
250	
251		return prependSections, appendSections, nil
252	}
253	
254	func promptSection(
255		ctx context.Context,
256		provider session.PromptProvider,
257		startup session.StartupPromptContext,
258		agent aghconfig.AgentDef,
259		workspace *workspacepkg.ResolvedWorkspace,
260	) (string, error) {
261		if startupProvider, ok := provider.(startupPromptSectionProvider); ok {
262			return startupProvider.PromptStartupSection(ctx, startup, agent, workspace)
263		}
264		if agentProvider, ok := provider.(agentPromptSectionProvider); ok {
265			return agentProvider.PromptAgentSection(ctx, agent, workspace)
266		}
267		return provider.PromptSection(ctx, workspace)
268	}
269	
270	func applyPromptSectionBudget(section string, descriptor PromptSectionDescriptor) string {
271		if section == "" || descriptor.Budget <= 0 {
272			return section
273		}
274		if utf8.RuneCountInString(section) <= descriptor.Budget {
275			return section
276		}
277		if descriptor.BudgetBehavior == PromptSectionBudgetBehaviorOmit {
278			return ""
279		}
280		return strings.TrimSpace(trimStringToRunes(section, descriptor.Budget))
281	}
282	
283	func trimStringToRunes(value string, budget int) string {
284		if budget <= 0 || value == "" {
285			return ""
286		}
287	
288		var builder strings.Builder
289		builder.Grow(len(value))
290	
291		count := 0
292		for _, r := range value {
293			if count == budget {
294				break
295			}
296			builder.WriteRune(r)
297			count++
298		}
299		return builder.String()
300	}
