11	)
12	
13	// SectionSelector resolves startup policy and selects eligible startup prompt
14	// sections before final assembly.
15	type SectionSelector struct {
16		resolver *HarnessContextResolver
17		recorder *harnessLifecycleRecorder
18	}
19	
20	// NewSectionSelector constructs a daemon-owned startup section selector.
21	func NewSectionSelector(
22		resolver *HarnessContextResolver,
23		recorder *harnessLifecycleRecorder,
24	) *SectionSelector {
25		if resolver == nil {
26			return nil
27		}
28		return &SectionSelector{resolver: resolver, recorder: recorder}
29	}
30	
31	// Select resolves startup policy for the provided startup context and returns
32	// the eligible startup sections in deterministic order without duplicates.
33	func (s *SectionSelector) Select(
34		startup session.StartupPromptContext,
35		descriptors []PromptSectionDescriptor,
36	) ([]PromptSectionDescriptor, ResolvedHarnessContext, error) {
37		normalized := normalizeAndSortPromptSectionDescriptors(descriptors)
38		resolved := ResolvedHarnessContext{}
39		if s != nil && s.resolver != nil {
40			var err error
41			resolved, err = s.resolver.ResolveStartup(startup)
42			if err != nil {
43				return nil, ResolvedHarnessContext{}, err
44			}
45		}
46		var timestamp time.Time
47		if s != nil && s.recorder != nil && s.resolver != nil {
48			timestamp = s.recorder.timestamp(time.Time{})
49			s.recorder.RecordStartupContextResolved(startup, resolved, timestamp)
50		}
51	
52		selected := make([]PromptSectionDescriptor, 0, len(normalized))
53		seen := make(map[string]struct{}, len(normalized))
54	
55		for _, descriptor := range normalized {
56			if descriptor.Provider == nil {
57				continue
58			}
59			if descriptor.StartupPredicate != nil && !descriptor.StartupPredicate(startup) {
60				continue
61			}
62			if s != nil && s.resolver != nil && descriptor.Predicate != nil && !descriptor.Predicate(resolved.Policy) {
63				continue
64			}
65			if _, exists := seen[descriptor.Name]; exists {
66				continue
67			}
68			seen[descriptor.Name] = struct{}{}
69			selected = append(selected, descriptor)
70		}
71		if s != nil && s.recorder != nil && s.resolver != nil {
72			s.recorder.RecordStartupSectionSelected(startup, resolved, selected, timestamp)
73		}
74	
75		return selected, resolved, nil
76	}
77	
78	func normalizeAndSortPromptSectionDescriptors(
79		descriptors []PromptSectionDescriptor,
80	) []PromptSectionDescriptor {
81		normalized := make([]PromptSectionDescriptor, 0, len(descriptors))
82		for _, descriptor := range descriptors {
83			name := strings.TrimSpace(descriptor.Name)
84			if name == "" {
85				continue
86			}
87	
88			position, ok := normalizePromptSectionPosition(descriptor.Position)
89			if !ok {
90				continue
91			}
92	
93			normalized = append(normalized, PromptSectionDescriptor{
94				Name:             name,
95				Position:         position,
96				Order:            descriptor.Order,
97				Budget:           descriptor.Budget,
98				BudgetBehavior:   normalizePromptSectionBudgetBehavior(descriptor.BudgetBehavior),
99				Provider:         descriptor.Provider,
100				Predicate:        descriptor.Predicate,
101				StartupPredicate: descriptor.StartupPredicate,
102			})
103		}
104	
105		slices.SortStableFunc(normalized, func(left, right PromptSectionDescriptor) int {
106			if cmp := cmp.Compare(
107				promptSectionPositionRank(left.Position),
108				promptSectionPositionRank(right.Position),
109			); cmp != 0 {
110				return cmp
111			}
112			if cmp := cmp.Compare(left.Order, right.Order); cmp != 0 {
113				return cmp
114			}
115			return cmp.Compare(left.Name, right.Name)
116		})
117	
118		return normalized
119	}
120	
121	func normalizePromptSectionPosition(position PromptSectionPosition) (PromptSectionPosition, bool) {
122		switch PromptSectionPosition(strings.TrimSpace(string(position))) {
123		case PromptSectionPositionPrepend:
124			return PromptSectionPositionPrepend, true
125		case "", PromptSectionPositionAppend:
126			return PromptSectionPositionAppend, true
127		default:
128			return "", false
129		}
130	}
131	
132	func normalizePromptSectionBudgetBehavior(
133		behavior PromptSectionBudgetBehavior,
134	) PromptSectionBudgetBehavior {
135		switch PromptSectionBudgetBehavior(strings.TrimSpace(string(behavior))) {
136		case PromptSectionBudgetBehaviorOmit:
137			return PromptSectionBudgetBehaviorOmit
138		case "", PromptSectionBudgetBehaviorTrim:
139			return PromptSectionBudgetBehaviorTrim
140		default:
141			return PromptSectionBudgetBehaviorTrim
142		}
143	}
144	
145	func promptSectionPositionRank(position PromptSectionPosition) int {
146		switch position {
147		case PromptSectionPositionPrepend:
148			return 0
149		case PromptSectionPositionAppend:
150			return 1
151		default:
152			return 2
153		}
154	}
155	
156	func validatePromptSectionDescriptors(descriptors []PromptSectionDescriptor) error {
157		for _, descriptor := range descriptors {
158			if strings.TrimSpace(descriptor.Name) == "" {
159				return fmt.Errorf("daemon: startup prompt section name is required")
160			}
161			if _, ok := normalizePromptSectionPosition(descriptor.Position); !ok {
162				return fmt.Errorf(
163					"daemon: invalid startup prompt section position %q for %q",
164					descriptor.Position,
165					descriptor.Name,
166				)
167			}
168		}
169		return nil
170	}
