314	export function useSendNetworkMessage(): UseSendNetworkMessageResult {
315	  const queryClient = useQueryClient();
316	  const { activeWorkspaceId } = useActiveWorkspace();
317	
318	  const mutation = useMutation<SendNetworkMessageResult, Error, ScopedSendNetworkMessageInput>({
319	    mutationFn: async (input: ScopedSendNetworkMessageInput) => {
320	      const clientMessageId = input.clientMessageId ?? generateClientMessageId();
321	      const isRetry = input.clientMessageId != null;
322	      const timestamp = new Date().toISOString();
323	      const optimistic = buildOptimisticMessage(input, clientMessageId, timestamp);
324	
325	      if (isRetry) {
326	        // The retry path already has the optimistic placeholder in cache; flip
327	        // it back to "pending" so the danger-tint and inline retry/discard
328	        // disappear while the second attempt is in flight.
329	        queryClient.setQueriesData<NetworkConversationMessage[] | undefined>(
330	          { queryKey: activeContainerKey(input.workspaceId, input) },
331	          previous => {
332	            if (!previous) {
333	              return previous;
334	            }
335	            return previous.map(message => {
336	              if (message.message_id !== clientMessageId) {
337	                return message;
338	              }
339	              return { ...optimistic, message_id: clientMessageId };
340	            });
341	          }
342	        );
343	      } else {
344	        applyOptimistic(queryClient, input, optimistic);
345	      }
346	
347	      try {
348	        const request = buildSendRequest(input, clientMessageId, input.workspaceId);
349	        const response = await sendNetworkMessage(input.workspaceId, request);
350	        replaceOptimisticOnSuccess(queryClient, input, clientMessageId, timestamp);
351	        return { clientMessageId, response };
352	      } catch (error) {
353	        markOptimisticFailed(queryClient, input, clientMessageId);
354	        throw error;
355	      }
356	    },
357	    onSettled: (_data, _error, variables) => {
358	      void invalidateContainerQueries(queryClient, variables);
359	      void queryClient.invalidateQueries({ queryKey: sessionKeys.lists() });
360	    },
361	  });
362	
363	  const send = useCallback(
364	    (input: SendNetworkMessageInput) => {
365	      if (!activeWorkspaceId) {
366	        return Promise.reject(new NetworkApiError("No active workspace selected", 400));
367	      }
368	      return mutation.mutateAsync({ ...input, workspaceId: activeWorkspaceId });
369	    },
370	    [activeWorkspaceId, mutation]
371	  );
372	  const retry = useCallback(
373	    (input: SendNetworkMessageInput, clientMessageId: string) =>
374	      activeWorkspaceId
375	        ? mutation.mutateAsync({ ...input, clientMessageId, workspaceId: activeWorkspaceId })
376	        : Promise.reject(new NetworkApiError("No active workspace selected", 400)),
377	    [activeWorkspaceId, mutation]
378	  );
379	  const discard = useCallback(
380	    (input: SendNetworkMessageInput, clientMessageId: string) => {
381	      if (!activeWorkspaceId) {
382	        return;
383	      }
384	      discardOptimistic(queryClient, { ...input, workspaceId: activeWorkspaceId }, clientMessageId);
385	    },
386	    [activeWorkspaceId, queryClient]
387	  );
388	
389	  return useMemo(
390	    () => ({
391	      send,
392	      retry,
393	      discard,
394	      isSending: mutation.isPending,
395	    }),
396	    [send, retry, discard, mutation.isPending]
397	  );
398	}
