471	    CreateNetworkThreadInput & { workspaceId: string }
472	  >({
473	    mutationFn: async input => {
474	      const firstAttemptThreadId = `thread_${generateClientMessageId().replace(/-/g, "")}`;
475	      try {
476	        return await attemptCreateThread(queryClient, { ...input, threadId: firstAttemptThreadId });
477	      } catch (firstError) {
478	        // Exactly one silent retry, then surface the toast.
479	        const secondAttemptThreadId = `thread_${generateClientMessageId().replace(/-/g, "")}`;
480	        try {
481	          return await attemptCreateThread(queryClient, {
482	            ...input,
483	            threadId: secondAttemptThreadId,
484	          });
485	        } catch (secondError) {
486	          toast.error(THREAD_COLLISION_TOAST);
487	          throw secondError instanceof Error ? secondError : firstError;
488	        }
489	      }
490	    },
491	    onSettled: (_data, _error, variables) => {
492	      void queryClient.invalidateQueries({
493	        queryKey: networkKeys.threadsList(variables.workspaceId, variables.channel),
494	      });
495	      void queryClient.invalidateQueries({
496	        queryKey: networkKeys.channelDetail(variables.workspaceId, variables.channel),
497	      });
498	    },
499	  });
500	
501	  return useMemo(
502	    () => ({
503	      createThread: (input: CreateNetworkThreadInput) => {
504	        if (!workspaceId) {
505	          return Promise.reject(new NetworkApiError("No active workspace selected", 400));
506	        }
507	        return mutation.mutateAsync({ ...input, workspaceId });
508	      },
509	      isCreating: mutation.isPending,
510	    }),
511	    [workspaceId, mutation]
512	  );
513	}
