20	  directId: string;
21	  sessionId: string;
22	  peerFrom: string;
23	  peerTo?: string;
24	  /** Other party label for the placeholder + Send target hint. */
25	  peerLabel?: string;
26	  displayName?: string;
27	  disabledReason?: string;
28	}
29	
30	export type DetailComposerProps = DetailComposerThreadProps | DetailComposerDirectProps;
31	
32	function buildSendInput(
33	  props: DetailComposerProps,
34	  text: string,
35	  mentions: string[] = []
36	): SendNetworkMessageInput {
37	  if (props.surface === "thread") {
38	    return {
39	      surface: "thread",
40	      channel: props.channel,
41	      threadId: props.threadId,
42	      sessionId: props.sessionId,
43	      peerFrom: props.peerFrom,
44	      text,
45	      mentions,
46	      displayName: props.displayName,
47	    };
48	  }
49	  return {
50	    surface: "direct",
51	    channel: props.channel,
52	    directId: props.directId,
53	    sessionId: props.sessionId,
54	    peerFrom: props.peerFrom,
55	    peerTo: props.peerTo,
56	    text,
57	    mentions,
58	    displayName: props.displayName,
59	  };
60	}
61	
62	export function DetailComposer(props: DetailComposerProps) {
63	  const { send, isSending } = useSendNetworkMessage();
64	  const disabled = props.disabledReason != null;
65	
66	  const placeholder =
67	    props.surface === "thread" ? "Reply..." : `Message ${props.peerLabel ?? "@peer"}...`;
68	  const sendLabel =
69	    props.surface === "thread"
70	      ? `Send to #${props.channel}`
71	      : `Send to ${props.peerLabel ?? "@peer"}`;
72	
73	  const handleSubmit = async ({
74	    text,
75	    mentions,
76	    reset,
77	  }: {
78	    text: string;
79	    mentions: string[];
80	    reset: () => void;
81	  }) => {
82	    try {
83	      await send(buildSendInput(props, text, mentions));
84	      reset();
85	    } catch {
86	      // The optimistic message remains visible with retry/discard inline per
87	      // `_design.md` §7.3.
88	      reset();
89	    }
90	  };
91	
92	  return (
93	    <Composer
94	      disabled={disabled}
95	      disabledReason={props.disabledReason}
96	      isSending={isSending}
97	      onSubmit={handleSubmit}
98	      placeholder={placeholder}
99	      sendLabel={sendLabel}
100	      testIdSuffix={props.surface === "thread" ? "thread" : "direct"}
101	    />
102	  );
103	}
