1	import { useCallback, useEffect, useRef, useState, type RefObject } from "react";
2	
3	import type { SlashCommandEntry } from "./composer-slash-popover";
4	
5	const SLASH_PREFIX = /(^|\s)\/([\w-]*)$/u;
6	const MENTION_PATTERN = /(^|\s)@([A-Za-z0-9_.:-]+)/gu;
7	
8	export interface ComposerSubmitArgs {
9	  text: string;
10	  mentions: string[];
11	  /** Reset the textarea after a successful send. */
12	  reset: () => void;
13	  /** Restore the textarea to the value the user typed (used when the send fails). */
14	  restore: () => void;
15	}
16	
17	export interface UseComposerStateArgs {
18	  disabled: boolean;
19	  isSending: boolean;
20	  onSubmit: (args: ComposerSubmitArgs) => void;
21	}
22	
23	export interface UseComposerStateResult {
24	  value: string;
25	  trimmed: string;
26	  mentions: string[];
27	  slashOpen: boolean;
28	  slashFilter: string;
29	  textareaRef: RefObject<HTMLTextAreaElement | null>;
30	  sendDisabled: boolean;
31	  handleChange: (event: React.ChangeEvent<HTMLTextAreaElement>) => void;
32	  handleSubmit: (event: React.FormEvent<HTMLFormElement>) => void;
33	  handleKeyDown: (event: React.KeyboardEvent<HTMLTextAreaElement>) => void;
34	  handleSlashSelect: (entry: SlashCommandEntry) => void;
35	  handleToolbarSlash: () => void;
36	  handleSlashClose: () => void;
37	}
38	
39	export function parseMentions(value: string): string[] {
40	  const mentions = new Set<string>();
41	  for (const match of value.matchAll(MENTION_PATTERN)) {
42	    const peerId = match[2]?.trim();
43	    if (peerId) {
44	      mentions.add(peerId);
45	    }
46	  }
47	  return [...mentions];
48	}
49	
50	/**
51	 * Drives composer textarea state, slash command detection, and Cmd/Ctrl+Enter
52	 * submission. Extracted from `<Composer>` so it stays under the
53	 * `compozy-react(max-component-complexity)` cap and can be re-used by future
54	 * composer variants.
55	 */
56	export function useComposerState({
57	  disabled,
58	  isSending,
59	  onSubmit,
60	}: UseComposerStateArgs): UseComposerStateResult {
61	  const [value, setValue] = useState("");
62	  const [slashOpen, setSlashOpen] = useState(false);
63	  const [slashFilter, setSlashFilter] = useState("");
64	  const textareaRef = useRef<HTMLTextAreaElement | null>(null);
65	
66	  const reset = useCallback(() => {
67	    setValue("");
68	    setSlashOpen(false);
69	    setSlashFilter("");
70	  }, []);
71	
72	  const restore = useCallback(() => {
73	    // Caller invokes after a failed send if the optimistic message was
74	    // discarded. Currently a no-op since we keep the textarea contents in
75	    // `value` so the user can retry without retyping.
76	  }, []);
77	
78	  useEffect(() => {
79	    if (disabled) {
80	      reset();
81	    }
82	  }, [disabled, reset]);
83	
84	  const updateSlashState = useCallback((next: string) => {
85	    const match = SLASH_PREFIX.exec(next);
86	    if (match == null) {
87	      setSlashOpen(false);
88	      setSlashFilter("");
89	      return;
90	    }
91	    setSlashOpen(true);
92	    setSlashFilter(match[2] ?? "");
93	  }, []);
94	
95	  const handleChange = useCallback(
96	    (event: React.ChangeEvent<HTMLTextAreaElement>) => {
97	      const next = event.target.value;
98	      setValue(next);
99	      updateSlashState(next);
100	    },
101	    [updateSlashState]
102	  );
103	
104	  const submitInternal = useCallback(
105	    (text: string) => {
106	      onSubmit({ text, mentions: parseMentions(text), reset, restore });
107	    },
108	    [onSubmit, reset, restore]
109	  );
110	
111	  const handleSubmit = useCallback(
112	    (event: React.FormEvent<HTMLFormElement>) => {
113	      event.preventDefault();
114	      if (disabled || isSending) {
115	        return;
116	      }
117	      const text = value.trim();
118	      if (text.length === 0) {
119	        return;
120	      }
121	      submitInternal(text);
122	    },
123	    [disabled, isSending, submitInternal, value]
124	  );
125	
126	  const handleKeyDown = useCallback(
127	    (event: React.KeyboardEvent<HTMLTextAreaElement>) => {
128	      if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) {
129	        event.preventDefault();
130	        const text = value.trim();
131	        if (text.length === 0 || disabled || isSending) {
132	          return;
133	        }
134	        submitInternal(text);
135	      }
136	    },
137	    [disabled, isSending, submitInternal, value]
138	  );
139	
140	  const handleSlashSelect = useCallback((entry: SlashCommandEntry) => {
141	    setValue(prev =>
142	      prev.replace(SLASH_PREFIX, (_match, leading: string) => `${leading}/${entry.command} `)
143	    );
144	    setSlashOpen(false);
145	    setSlashFilter("");
146	    textareaRef.current?.focus();
147	  }, []);
148	
149	  const handleToolbarSlash = useCallback(() => {
150	    setSlashOpen(true);
151	    setSlashFilter("");
152	    textareaRef.current?.focus();
153	  }, []);
154	
155	  const handleSlashClose = useCallback(() => {
156	    setSlashOpen(false);
157	  }, []);
158	
159	  const trimmed = value.trim();
160	  const mentions = parseMentions(trimmed);
161	  const sendDisabled = disabled || isSending || trimmed.length === 0;
162	
163	  return {
164	    value,
165	    trimmed,
166	    mentions,
167	    slashOpen,
168	    slashFilter,
169	    textareaRef,
170	    sendDisabled,
171	    handleChange,
172	    handleSubmit,
173	    handleKeyDown,
174	    handleSlashSelect,
175	    handleToolbarSlash,
176	    handleSlashClose,
177	  };
178	}
179	
