53	  if (totalCount > 0) {
54	    if (agentCount > 0) {
55	      segments.push(`${agentCount} ${agentCount === 1 ? "agent" : "agents"}`);
56	    }
57	    if (humanCount > 0) {
58	      segments.push(`${humanCount} ${humanCount === 1 ? "human" : "humans"}`);
59	    }
60	  } else if (fallbackPeerCount > 0) {
61	    segments.push(`${fallbackPeerCount} ${fallbackPeerCount === 1 ? "peer" : "peers"}`);
62	  } else {
63	    segments.push("no peers yet");
64	  }
65	
66	  if (openWorkCount > 0) {
67	    segments.push(`${openWorkCount} active work`);
68	  }
69	
70	  const purpose = detail?.purpose?.trim() || channel.purpose?.trim();
71	  if (purpose) {
72	    segments.push(purpose);
