13	import {
14	  useDeleteNetworkSubscription,
15	  useUpsertNetworkSubscription,
16	} from "../../hooks/use-network-actions";
17	import { networkSubscriptionsOptions } from "../../lib/query-options";
18	import type { NetworkSubscriptionMode } from "../../types";
19	
20	const MODES: ReadonlyArray<{
21	  value: NetworkSubscriptionMode;
22	  label: string;
23	}> = [
24	  { value: "full", label: "Full delivery" },
25	  { value: "digest", label: "Digest" },
26	  { value: "mute", label: "Mute" },
27	];
28	
29	interface ThreadSubscriptionControlProps {
30	  workspaceId: string;
31	  channel: string;
32	  threadId: string;
33	  peerId?: string | null;
34	}
35	
36	function modeLabel(mode?: string | null): string {
37	  switch (mode) {
38	    case "full":
39	      return "Full";
40	    case "digest":
41	      return "Digest";
42	    case "mute":
43	      return "Muted";
44	    default:
45	      return "Default";
46	  }
47	}
48	
49	export function ThreadSubscriptionControl({
50	  workspaceId,
51	  channel,
52	  threadId,
53	  peerId,
54	}: ThreadSubscriptionControlProps) {
55	  const enabled = workspaceId !== "" && channel !== "" && threadId !== "" && Boolean(peerId);
56	  const subscriptions = useQuery(
57	    networkSubscriptionsOptions(
58	      workspaceId,
59	      channel,
60	      { peer_id: peerId ?? undefined, thread_id: threadId },
61	      enabled
62	    )
63	  );
64	  const upsert = useUpsertNetworkSubscription();
65	  const remove = useDeleteNetworkSubscription();
66	  const current = subscriptions.data?.[0] ?? null;
67	  const isBusy = upsert.isPending || remove.isPending || subscriptions.isFetching;
68	  const label = modeLabel(current?.mode);
69	  const Icon = current?.mode === "mute" ? BellOff : Bell;
70	
71	  const setMode = (mode: NetworkSubscriptionMode) => {
72	    if (!peerId) {
73	      return;
74	    }
75	    void upsert.mutateAsync({
76	      workspaceId,
77	      channel,
78	      data: {
79	        peer_id: peerId,
80	        thread_id: threadId,
81	        mode,
82	      },
83	    });
84	  };
85	
86	  const resetMode = () => {
87	    if (!peerId) {
88	      return;
89	    }
90	    void remove.mutateAsync({ workspaceId, channel, peerId, threadId });
91	  };
92	
93	  return (
94	    <DropdownMenu>
95	      <DropdownMenuTrigger
96	        render={
97	          <Button
98	            aria-label="Thread delivery mode"
99	            data-testid="network-thread-subscription-trigger"
100	            disabled={!enabled || isBusy}
101	            size="sm"
102	            type="button"
103	            variant="ghost"
104	          />
105	        }
106	      >
107	        {isBusy ? (
108	          <Spinner aria-hidden="true" className="size-3" />
109	        ) : (
110	          <Icon aria-hidden="true" className="size-3" />
111	        )}
112	        {label}
113	        <ChevronDown aria-hidden="true" className="size-3 text-subtle" />
114	      </DropdownMenuTrigger>
115	      <DropdownMenuContent align="end">
116	        {MODES.map(mode => (
117	          <DropdownMenuItem
118	            data-testid={`network-thread-subscription-${mode.value}`}
119	            key={mode.value}
120	            onSelect={event => {
121	              event.preventDefault();
122	              setMode(mode.value);
123	            }}
124	          >
125	            {mode.label}
126	          </DropdownMenuItem>
127	        ))}
128	        <DropdownMenuItem
129	          data-testid="network-thread-subscription-default"
130	          onSelect={event => {
131	            event.preventDefault();
132	            resetMode();
133	          }}
134	        >
135	          Default routing
136	        </DropdownMenuItem>
137	      </DropdownMenuContent>
138	    </DropdownMenu>
139	  );
140	}
