1	import { useCallback } from "react";
2	
3	import { useActiveNetworkSession, type ActiveNetworkSession } from "../../hooks/use-active-session";
4	import {
5	  useSendNetworkMessage,
6	  type SendNetworkMessageThreadInput,
7	} from "../../hooks/use-network-actions";
8	import { useThreadOverlay, type UseThreadOverlayResult } from "../../hooks/use-thread-overlay";
9	import { useOpenWork, type UseOpenWorkResult } from "../../hooks/use-work";
10	import type { NetworkConversationMessage } from "../../types";
11	
12	export interface UseThreadOverlayViewArgs {
13	  workspaceId: string;
14	  channel: string;
15	  threadId: string;
16	  fullPage: boolean;
17	}
18	
19	export interface UseThreadOverlayViewResult {
20	  overlay: UseThreadOverlayResult;
21	  session: ActiveNetworkSession | null;
22	  disabledReason: string | null;
23	  openWork: UseOpenWorkResult;
24	  handleRetry: (message: NetworkConversationMessage) => void;
25	  handleDiscard: (message: NetworkConversationMessage) => void;
26	}
27	
28	export function useThreadOverlayView({
29	  workspaceId,
30	  channel,
31	  threadId,
32	  fullPage,
33	}: UseThreadOverlayViewArgs): UseThreadOverlayViewResult {
34	  const overlay = useThreadOverlay({ workspaceId, channel, fullPage, threadId });
35	  const session = useActiveNetworkSession(channel, { workspaceId });
36	  const openWork = useOpenWork({ channel, surface: "thread", containerId: threadId });
37	  const { retry, discard } = useSendNetworkMessage();
38	
39	  const buildSendInput = useCallback(
40	    (message: NetworkConversationMessage): SendNetworkMessageThreadInput | null => {
41	      if (!session.session) {
42	        return null;
43	      }
44	      return {
45	        surface: "thread",
46	        channel,
47	        threadId,
48	        sessionId: session.session.sessionId,
49	        peerFrom: session.session.peerId,
50	        text: message.text ?? "",
51	        mentions: message.mentions ?? [],
52	        displayName: session.session.displayName,
53	      };
54	    },
55	    [channel, session.session, threadId]
56	  );
57	
58	  const handleRetry = useCallback(
59	    (message: NetworkConversationMessage) => {
60	      const input = buildSendInput(message);
61	      if (input == null) {
62	        return;
63	      }
64	      void retry(input, message.message_id);
65	    },
66	    [buildSendInput, retry]
67	  );
68	
69	  const handleDiscard = useCallback(
70	    (message: NetworkConversationMessage) => {
71	      const input = buildSendInput(message);
72	      if (input == null) {
73	        return;
74	      }
75	      discard(input, message.message_id);
76	    },
77	    [buildSendInput, discard]
78	  );
79	
80	  return {
81	    overlay,
82	    session: session.session,
83	    disabledReason: session.disabledReason,
84	    openWork,
85	    handleRetry,
86	    handleDiscard,
87	  };
88	}
