137	function invalidateTaskQueries(queryClient: QueryClient, id?: string) {
138	  const pending = [
139	    queryClient.invalidateQueries({ queryKey: tasksKeys.lists() }),
140	    queryClient.invalidateQueries({ queryKey: tasksKeys.runsRoot() }),
141	    queryClient.invalidateQueries({ queryKey: tasksKeys.timelineRoot() }),
142	    queryClient.invalidateQueries({ queryKey: tasksKeys.treeRoot() }),
143	    queryClient.invalidateQueries({ queryKey: tasksKeys.runDetails() }),
144	  ];
145	
146	  if (id) {
147	    pending.push(queryClient.invalidateQueries({ queryKey: tasksKeys.detail(id) }));
148	  }
149	
150	  return Promise.all(pending);
151	}
152	
153	function invalidateAggregateQueries(queryClient: QueryClient) {
154	  return Promise.all([
155	    queryClient.invalidateQueries({ queryKey: [...tasksKeys.all, "dashboard"] }),
156	    queryClient.invalidateQueries({ queryKey: [...tasksKeys.all, "inbox"] }),
157	    queryClient.invalidateQueries({ queryKey: schedulerKeys.all }),
158	  ]);
159	}
