161	function invalidateTriageQueries(queryClient: QueryClient, id?: string) {
162	  return Promise.all([
163	    queryClient.invalidateQueries({ queryKey: tasksKeys.triageRoot() }),
164	    queryClient.invalidateQueries({ queryKey: tasksKeys.lists() }),
165	    ...(id ? [queryClient.invalidateQueries({ queryKey: tasksKeys.detail(id) })] : []),
166	    queryClient.invalidateQueries({ queryKey: [...tasksKeys.all, "inbox"] }),
167	  ]);
168	}
