1	import { useCallback, useEffect, useMemo, useState, type FormEvent } from "react";
2	
3	import type { FanOutTaskRunsRequest, FanOutTaskRunsResponse } from "../types";
4	
5	const DEFAULT_DESIGNATIONS = [
6	  "Investigate runtime data path",
7	  "Validate UI impact",
8	  "Review operator docs",
9	].join("\n");
10	
11	export interface UseTasksFanOutRunsCardParams {
12	  defaultNetworkChannel?: string | null;
13	  onFanOut: (data: FanOutTaskRunsRequest) => Promise<FanOutTaskRunsResponse | void>;
14	}
15	
16	function parseDesignations(value: string): FanOutTaskRunsRequest["designations"] {
17	  return value
18	    .split(/\r?\n/u)
19	    .map(line => line.trim())
20	    .filter(line => line.length > 0)
21	    .map(brief => ({ brief }));
22	}
23	
24	function trimOrUndefined(value: string): string | undefined {
25	  const trimmed = value.trim();
26	  return trimmed === "" ? undefined : trimmed;
27	}
28	
29	export function useTasksFanOutRunsCard({
30	  defaultNetworkChannel,
31	  onFanOut,
32	}: UseTasksFanOutRunsCardParams) {
33	  const [open, setOpen] = useState(false);
34	  const [networkChannel, setNetworkChannel] = useState(defaultNetworkChannel ?? "");
35	  const [designationsText, setDesignationsText] = useState(DEFAULT_DESIGNATIONS);
36	  const [formError, setFormError] = useState<string | null>(null);
37	  const designations = useMemo(() => parseDesignations(designationsText), [designationsText]);
38	
39	  useEffect(() => {
40	    if (open) {
41	      setNetworkChannel(defaultNetworkChannel ?? "");
42	    }
43	  }, [defaultNetworkChannel, open]);
44	
45	  const handleOpenChange = useCallback((nextOpen: boolean) => {
46	    setOpen(nextOpen);
47	    if (!nextOpen) {
48	      setFormError(null);
49	      setDesignationsText(DEFAULT_DESIGNATIONS);
50	    }
51	  }, []);
52	
53	  const openDialog = useCallback(() => handleOpenChange(true), [handleOpenChange]);
54	  const closeDialog = useCallback(() => handleOpenChange(false), [handleOpenChange]);
55	
56	  const handleSubmit = useCallback(
57	    async (event: FormEvent<HTMLFormElement>) => {
58	      event.preventDefault();
59	      setFormError(null);
60	      if (designations.length === 0) {
61	        setFormError("Add at least one assignment.");
62	        return;
63	      }
64	
65	      const payload: FanOutTaskRunsRequest = {
66	        designations,
67	        network_channel: trimOrUndefined(networkChannel),
68	      };
69	
70	      try {
71	        await onFanOut(payload);
72	        handleOpenChange(false);
73	      } catch {
74	        // The route hook owns the toast; keep the dialog open for correction.
75	      }
76	    },
77	    [designations, handleOpenChange, networkChannel, onFanOut]
78	  );
79	
80	  return {
81	    closeDialog,
82	    designationsText,
83	    formError,
84	    handleOpenChange,
85	    handleSubmit,
86	    networkChannel,
87	    open,
88	    openDialog,
89	    setDesignationsText,
90	    setNetworkChannel,
91	  };
92	}
93	
