1080	func formatNetworkMessageWithGuidance(
1081		envelope Envelope,
1082		guidanceMode networkMessageGuidanceMode,
1083	) (string, error) {
1084		return formatNetworkMessageWithDeliveryMode(envelope, guidanceMode, store.NetworkSubscriptionModeFull)
1085	}
