1087	type networkDeliveryBody struct {
1088		preview       string
1089		plainTextBody string
1090		canonicalBody []byte
1091	}
1092	
1093	func networkDeliveryBodyForEnvelope(envelope Envelope) (networkDeliveryBody, error) {
1094		body, err := envelope.DecodeBody()
1095		switch {
1096		case err == nil:
1097			if say, ok := body.(SayBody); ok && len(say.Artifacts) == 0 {
1098				return networkDeliveryBody{
1099					preview:       strings.TrimSpace(say.Text),
1100					plainTextBody: say.Text,
1101				}, nil
1102			}
1103			canonicalBody, marshalErr := json.Marshal(body)
1104			if marshalErr != nil {
1105				return networkDeliveryBody{}, fmt.Errorf("network: marshal canonical body for delivery: %w", marshalErr)
1106			}
1107			return networkDeliveryBody{
1108				preview:       previewForBody(body),
1109				canonicalBody: canonicalBody,
1110			}, nil
1111		case !json.Valid(envelope.Body):
1112			return networkDeliveryBody{}, fmt.Errorf("network: decode envelope body for delivery: %w", err)
1113		default:
1114			var compact bytes.Buffer
1115			if compactErr := json.Compact(&compact, envelope.Body); compactErr != nil {
1116				return networkDeliveryBody{}, fmt.Errorf("network: compact raw envelope body for delivery: %w", compactErr)
1117			}
1118			return networkDeliveryBody{canonicalBody: compact.Bytes()}, nil
1119		}
1120	}
