1122	func formatNetworkMessageWithDeliveryMode(
1123		envelope Envelope,
1124		guidanceMode networkMessageGuidanceMode,
1125		deliveryMode string,
1126	) (string, error) {
1127		if normalizePromptDeliveryMode(deliveryMode) == store.NetworkSubscriptionModeDigest {
1128			return formatNetworkDigestMessage(envelope, guidanceMode)
1129		}
1130	
1131		deliveryBody, err := networkDeliveryBodyForEnvelope(envelope)
1132		if err != nil {
1133			return "", err
1134		}
1135		encodedBody := ""
1136		if deliveryBody.plainTextBody == "" {
1137			encodedBody = base64.StdEncoding.EncodeToString(deliveryBody.canonicalBody)
1138		}
1139	
1140		var builder strings.Builder
1141		builder.Grow(
1142			base64.StdEncoding.EncodedLen(len(deliveryBody.canonicalBody)) +
1143				len(deliveryBody.preview)*6 +
1144				len(deliveryBody.plainTextBody)*2 +
1145				2048,
1146		)
1147		builder.WriteString("<network-message")
1148		writeNetworkMessageAttrs(&builder, envelope, "")
1149		builder.WriteString(">\n")
1150		if deliveryBody.preview != "" {
1151			builder.WriteString("  <network-preview encoding=\"xml-escaped\">")
1152			builder.WriteString(xmlEscape(deliveryBody.preview))
1153			builder.WriteString("</network-preview>\n")
1154		}
1155		if deliveryBody.plainTextBody != "" {
1156			builder.WriteString("  <network-body encoding=\"text\">")
1157			builder.WriteString(xmlEscape(deliveryBody.plainTextBody))
1158			builder.WriteString("</network-body>\n")
1159		} else {
1160			builder.WriteString("  <network-body encoding=\"base64-json\">")
1161			builder.WriteString(encodedBody)
1162			builder.WriteString("</network-body>\n")
1163		}
1164		builder.WriteString("</network-message>")
1165		writeReplyGuidance(&builder, envelope, guidanceMode)
1166	
1167		return builder.String(), nil
1168	}
